  'N5',
  85,
  'アパートのルール',
  '[{"word":"音","reading":"おと","meaning_ko":"소리"},{"word":"自転車","reading":"じてんしゃ","meaning_ko":"자전거"},{"word":"自転車置き場","reading":"じてんしゃおきば","meaning_ko":"자전거 보관소"},{"word":"管理人","reading":"かんりにん","meaning_ko":"관리인"},{"word":"気持ちよく","reading":"きもちよく","meaning_ko":"기분 좋게"}]'::jsonb,
