-- N5-5: 病院の受付案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'びょういんの うけつけ あんない',
  'さくら びょういん

しんさつの じかんは つぎの とおりです。

げつようび〜きんようび：あさ 9じ〜ひる 12じ、ごご 2じ〜ゆうがた 5じ
どようび：あさ 9じ〜ひる 12じ
にちようび：おやすみ

はじめての ひとは、うけつけで ほけんしょうを みせてください。
よやくは でんわで できます。でんわばんごうは 03-1234-5678 です。
くるまで くる ひとは、びょういんの うしろに ちゅうしゃじょうが あります。

さくら びょういん',
  'notice',
  'N5',
  90,
  '病院の受付案内',
  '[{"word":"病院","reading":"びょういん","meaning_ko":"병원"},{"word":"診察","reading":"しんさつ","meaning_ko":"진찰"},{"word":"保険証","reading":"ほけんしょう","meaning_ko":"보험증"},{"word":"予約","reading":"よやく","meaning_ko":"예약"},{"word":"駐車場","reading":"ちゅうしゃじょう","meaning_ko":"주차장"}]'::jsonb,
  ARRAY['〜てください', '〜で できます', '〜に あります'],
  '사쿠라 병원

진찰 시간은 다음과 같습니다.

월요일~금요일：오전 9시~낮 12시, 오후 2시~저녁 5시
토요일：오전 9시~낮 12시
일요일：휴진

처음 오시는 분은 접수처에서 보험증을 보여 주세요.
예약은 전화로 할 수 있습니다. 전화번호는 03-1234-5678입니다.
차로 오시는 분은 병원 뒤에 주차장이 있습니다.

사쿠라 병원',
