-- N5-6: 料理のレシピ (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'かんたん たまごやき',
  'たまごやきの つくりかた

ざいりょう：
・たまご 3つ
・さとう すこし
・しお すこし
・あぶら すこし

つくりかた：
1. たまごを ボウルに いれます。
2. さとうと しおを いれて、よく まぜます。
3. フライパンに あぶらを いれて、ひを つけます。
4. たまごを すこし いれて、くるくる まきます。
5. もういちど たまごを いれて、また まきます。
6. 3かい〜4かい くりかえします。
7. できました！さらに のせて、たべましょう。',
  'instruction',
  'N5',
  85,
  '料理のレシピ',
  '[{"word":"卵焼き","reading":"たまごやき","meaning_ko":"계란말이"},{"word":"材料","reading":"ざいりょう","meaning_ko":"재료"},{"word":"砂糖","reading":"さとう","meaning_ko":"설탕"},{"word":"塩","reading":"しお","meaning_ko":"소금"},{"word":"油","reading":"あぶら","meaning_ko":"기름"}]'::jsonb,
  ARRAY['〜ます', '〜て、〜ます', '〜ましょう'],
  '계란말이 만드는 법

재료：
・달걀 3개
・설탕 조금
・소금 조금
・기름 조금

만드는 법：
1. 달걀을 볼에 넣습니다.
2. 설탕과 소금을 넣고 잘 섞습니다.
3. 프라이팬에 기름을 넣고 불을 켭니다.
4. 달걀을 조금 넣고 돌돌 말아줍니다.
5. 다시 한번 달걀을 넣고 또 말아줍니다.
6. 3~4번 반복합니다.
7. 완성! 접시에 올려서 먹읍시다.',
