  '引っ越しの案内メール',
  '田中さんへ

お元気ですか。お知らせがあります。
来月の15日に新しいアパートに引っ越すことになりました。
今のアパートは駅から遠くて、ちょっと不便でした。
新しいアパートは駅から歩いて5分のところにあります。
部屋は今より少し広くて、近くにスーパーやコンビニもあります。

引っ越しが終わったら、ぜひ遊びに来てください。
新しい住所は下に書いてあります。

新住所：東京都中野区中央1-2-3 サニーハイツ305号室

パク・ジュンより',
  'email',
  'N4',
  100,
  '引っ越しの案内',
  '[{"word":"引っ越す","reading":"ひっこす","meaning_ko":"이사하다"},{"word":"不便","reading":"ふべん","meaning_ko":"불편"},{"word":"広い","reading":"ひろい","meaning_ko":"넓다"},{"word":"住所","reading":"じゅうしょ","meaning_ko":"주소"},{"word":"遊びに来る","reading":"あそびにくる","meaning_ko":"놀러 오다"}]'::jsonb,
