-- N4-2: 趣味のサークル紹介 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '趣味のサークル紹介',
  '「にほんご読書クラブ」のメンバーをぼしゅうしています！

私たちは月に2回、土曜日の午後に集まって、日本語の本を読んでいます。
やさしい本から始めるので、日本語がまだ上手じゃなくても大丈夫です。

活動内容：
・みんなで本を読みます
・わからない言葉をいっしょに調べます
・読んだ本の感想を話し合います

場所：中央公民館 2階 会議室
時間：毎月第1・第3土曜日 14:00〜16:00
会費：月500円（お茶代）

興味がある方は、山本（090-1111-2222）まで連絡してください。
見学もできます。お気軽にどうぞ！',
  'article',
  'N4',
  110,
  '趣味のサークル',
  '[{"word":"募集","reading":"ぼしゅう","meaning_ko":"모집"},{"word":"集まる","reading":"あつまる","meaning_ko":"모이다"},{"word":"感想","reading":"かんそう","meaning_ko":"감상"},{"word":"会費","reading":"かいひ","meaning_ko":"회비"},{"word":"見学","reading":"けんがく","meaning_ko":"견학, 참관"},{"word":"気軽に","reading":"きがるに","meaning_ko":"부담 없이"}]'::jsonb,
  ARRAY['〜ても大丈夫', '〜ので', '〜ている', '〜合います'],
  '"일본어 독서 클럽" 멤버를 모집하고 있습니다!

저희는 한 달에 2번, 토요일 오후에 모여서 일본어 책을 읽고 있습니다.
쉬운 책부터 시작하므로 일본어를 아직 잘 못해도 괜찮습니다.

활동 내용：
・다 같이 책을 읽습니다
・모르는 단어를 함께 찾아봅니다
・읽은 책의 감상을 이야기합니다

장소：중앙 공민관 2층 회의실
시간：매월 첫째·셋째 토요일 14:00〜16:00
회비：월 500엔 (차 비용)

관심 있는 분은 야마모토(090-1111-2222)에게 연락해 주세요.
견학도 가능합니다. 부담 없이 오세요!',
  11
);

-- N4-3: 旅行の計画・ガイドブック (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '京都旅行ガイド',
  '京都は日本で一番人気がある観光地の一つです。
お寺や神社がたくさんあって、日本の伝統的な文化を楽しむことができます。

おすすめの場所：
・金閣寺：金色のきれいなお寺です。バスで行くことができます。
・嵐山：秋の紅葉がとてもきれいです。川の近くを散歩するのがおすすめです。
・錦市場：おいしい食べ物がたくさんあります。「京都の台所」と呼ばれています。

旅行のアドバイス：
春（3月〜5月）と秋（10月〜11月）は人が多いですが、景色がとてもきれいです。
電車やバスが便利ですから、一日乗車券を買うといいでしょう。
歩くことが多いので、歩きやすい靴を持っていってください。',
  'article',
  'N4',
  120,
  '旅行ガイド',
  '[{"word":"観光地","reading":"かんこうち","meaning_ko":"관광지"},{"word":"伝統的","reading":"でんとうてき","meaning_ko":"전통적"},{"word":"紅葉","reading":"こうよう","meaning_ko":"단풍"},{"word":"台所","reading":"だいどころ","meaning_ko":"부엌"},{"word":"景色","reading":"けしき","meaning_ko":"경치"},{"word":"乗車券","reading":"じょうしゃけん","meaning_ko":"승차권"}]'::jsonb,
  ARRAY['〜ことができます', '〜と呼ばれています', '〜といいでしょう', '〜ので'],
  '교토는 일본에서 가장 인기 있는 관광지 중 하나입니다.
사찰과 신사가 많아서 일본의 전통적인 문화를 즐길 수 있습니다.

추천 장소：
・긴카쿠지：금색의 아름다운 사찰입니다. 버스로 갈 수 있습니다.
・아라시야마：가을 단풍이 매우 아름답습니다. 강 근처를 산책하는 것을 추천합니다.
・니시키 시장：맛있는 음식이 많습니다. "교토의 부엌"이라고 불립니다.

여행 조언：
봄(3월~5월)과 가을(10월~11월)은 사람이 많지만 경치가 매우 아름답습니다.
전철이나 버스가 편리하므로 1일 승차권을 사면 좋을 것입니다.
걷는 일이 많으니 편한 신발을 가져가세요.',
  12
);

-- N4-4: 区役所の手続き案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '区役所の手続き案内',
  '引っ越しをしたときの手続きについて

新しい区に引っ越した方は、14日以内に転入届を出してください。

必要なもの：
・在留カード
・パスポート
・前の区の転出届の紙

受付場所：1階 住民課
受付時間：月曜日〜金曜日 8:30〜17:00

注意：
・届を出さないと、保険や病院で困ることがあります。
・届を出した後、新しい住所が在留カードに書かれます。
・わからないことがあったら、外国語相談窓口（2階）を利用してください。
　日本語、英語、中国語、韓国語で相談できます。',
  'notice',
  'N4',
  110,
  '区役所の手続き',
  '[{"word":"手続き","reading":"てつづき","meaning_ko":"수속, 절차"},{"word":"転入届","reading":"てんにゅうとどけ","meaning_ko":"전입신고"},{"word":"在留カード","reading":"ざいりゅうカード","meaning_ko":"체류카드"},{"word":"届","reading":"とどけ","meaning_ko":"신고서"},{"word":"相談","reading":"そうだん","meaning_ko":"상담"}]'::jsonb,
  ARRAY['〜以内に', '〜ないと〜ことがあります', '〜たら', '〜てください'],
  '이사를 했을 때의 절차에 대하여

새로운 구에 이사하신 분은 14일 이내에 전입신고를 내 주세요.

필요한 것：
・체류카드
・여권
・이전 구의 전출신고서

접수 장소：1층 주민과
접수 시간：월요일~금요일 8:30~17:00

주의：
・신고를 내지 않으면 보험이나 병원에서 곤란할 수 있습니다.
・신고를 낸 후 새 주소가 체류카드에 기재됩니다.
・모르는 것이 있으면 외국어 상담 창구(2층)를 이용해 주세요.
　일본어, 영어, 중국어, 한국어로 상담할 수 있습니다.',
  13
);

-- N4-5: 健康診断の結果通知 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '健康診断の結果通知',
  'パク・ジュン様

先日の健康診断の結果をお知らせします。

身長：175cm　体重：72kg
血圧：120/78（正常）
視力：右 1.0　左 0.9

結果：
全体的に問題はありません。しかし、コレステロールの数値が少し高いです。

アドバイス：
・野菜や魚を多く食べるようにしましょう。
・揚げ物や甘いものを食べすぎないように気をつけてください。
・毎日30分くらい運動をするといいでしょう。
・来年もかならず健康診断を受けてください。

ご質問があれば、病院に電話してください。

さくら内科クリニック',
  'notice',
  'N4',
  110,
  '健康診断の結果',
  '[{"word":"健康診断","reading":"けんこうしんだん","meaning_ko":"건강검진"},{"word":"血圧","reading":"けつあつ","meaning_ko":"혈압"},{"word":"視力","reading":"しりょく","meaning_ko":"시력"},{"word":"数値","reading":"すうち","meaning_ko":"수치"},{"word":"運動","reading":"うんどう","meaning_ko":"운동"},{"word":"揚げ物","reading":"あげもの","meaning_ko":"튀김"}]'::jsonb,
  ARRAY['〜ようにしましょう', '〜すぎないように', '〜といいでしょう', '〜があれば'],
  '박준 님

지난 건강검진 결과를 알려드립니다.

신장：175cm　체중：72kg
혈압：120/78（정상）
시력：오른쪽 1.0　왼쪽 0.9

결과：
전체적으로 문제는 없습니다. 다만 콜레스테롤 수치가 약간 높습니다.

조언：
・채소와 생선을 많이 먹도록 합시다.
・튀김이나 단 것을 너무 많이 먹지 않도록 주의해 주세요.
・매일 30분 정도 운동을 하면 좋겠습니다.
・내년에도 반드시 건강검진을 받아 주세요.

질문이 있으시면 병원에 전화해 주세요.

사쿠라 내과 클리닉',
  14
);

-- N4-6: 料理教室のお知らせ (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
