  'N4',
  115,
  '料理教室',
  '[{"word":"家庭料理","reading":"かていりょうり","meaning_ko":"가정 요리"},{"word":"参加者","reading":"さんかしゃ","meaning_ko":"참가자"},{"word":"定員","reading":"ていいん","meaning_ko":"정원"},{"word":"先着順","reading":"せんちゃくじゅん","meaning_ko":"선착순"},{"word":"材料費","reading":"ざいりょうひ","meaning_ko":"재료비"},{"word":"申し込み","reading":"もうしこみ","meaning_ko":"신청"}]'::jsonb,
