-- N4-7: 日本の祝日・季節の行事 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の季節の行事',
  '日本にはいろいろな季節の行事があります。

春には「お花見」があります。3月の終わりから4月のはじめに、桜の木の下でお弁当を食べたり、お酒を飲んだりします。友達や家族と楽しく過ごします。

夏には「お盆」があります。8月13日から16日ごろに、亡くなった家族のためにお墓参りをします。この時期は多くの人がふるさとに帰ります。

秋には「紅葉狩り」があります。赤や黄色になった葉を見に、山やお寺に行きます。

冬には「お正月」があります。1月1日に家族で特別な料理「おせち」を食べます。神社に行って、新しい年のお願いをします。これを「初詣」と言います。

季節ごとに違う行事があるのは、日本のすてきな文化だと思います。',
  'article',
  'N4',
  120,
  '季節の行事',
  '[{"word":"行事","reading":"ぎょうじ","meaning_ko":"행사"},{"word":"桜","reading":"さくら","meaning_ko":"벚꽃"},{"word":"お盆","reading":"おぼん","meaning_ko":"오봉(추석과 비슷한 명절)"},{"word":"お墓参り","reading":"おはかまいり","meaning_ko":"성묘"},{"word":"紅葉狩り","reading":"もみじがり","meaning_ko":"단풍놀이"},{"word":"初詣","reading":"はつもうで","meaning_ko":"새해 첫 참배"}]'::jsonb,
  ARRAY['〜たり〜たりします', '〜ために', '〜と言います', '〜だと思います'],
  '일본에는 여러 가지 계절 행사가 있습니다.

봄에는 "꽃놀이"가 있습니다. 3월 말부터 4월 초에 벚나무 아래에서 도시락을 먹거나 술을 마시거나 합니다. 친구나 가족과 즐겁게 보냅니다.

여름에는 "오봉"이 있습니다. 8월 13일부터 16일경에 돌아가신 가족을 위해 성묘를 합니다. 이 시기에 많은 사람들이 고향에 돌아갑니다.

가을에는 "단풍놀이"가 있습니다. 빨갛고 노랗게 물든 잎을 보러 산이나 사찰에 갑니다.

겨울에는 "설날"이 있습니다. 1월 1일에 가족과 특별한 요리 "오세치"를 먹습니다. 신사에 가서 새해 소원을 빕니다. 이것을 "하쓰모우데"라고 합니다.

계절마다 다른 행사가 있는 것은 일본의 멋진 문화라고 생각합니다.',
  16
);

-- N4-8: リサイクル・ゴミ分別案内 (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'ゴミの出し方ガイド',
  'ゴミの出し方について

正しくゴミを分けて出しましょう。

【燃えるゴミ】月曜日・木曜日
生ゴミ、紙、布など
→ 市の指定のゴミ袋に入れてください。

【燃えないゴミ】第2・第4水曜日
ガラス、茶わん、金属など
→ 透明の袋に入れてください。

【資源ゴミ】金曜日
ペットボトル、かん、びん、段ボール
→ きれいに洗ってから出してください。
→ ペットボトルはキャップとラベルを外してください。

【大型ゴミ】予約制
家具や電化製品など
→ 電話（03-6666-7777）で予約してから、シールを買って貼ってください。

ゴミは朝8時までに出してください。
前の日の夜に出さないでください。
ルールを守って、きれいな町にしましょう。',
  'instruction',
  'N4',
  115,
  'ゴミ分別',
  '[{"word":"分ける","reading":"わける","meaning_ko":"분류하다"},{"word":"燃える","reading":"もえる","meaning_ko":"타다"},{"word":"指定","reading":"してい","meaning_ko":"지정"},{"word":"資源","reading":"しげん","meaning_ko":"자원"},{"word":"透明","reading":"とうめい","meaning_ko":"투명"},{"word":"大型","reading":"おおがた","meaning_ko":"대형"}]'::jsonb,
  ARRAY['〜てから', '〜ないでください', '〜ましょう', '〜など'],
  '쓰레기 배출 방법에 대하여

올바르게 쓰레기를 분류하여 내놓읍시다.

【타는 쓰레기】월요일·목요일
음식물 쓰레기, 종이, 천 등
→ 시 지정 쓰레기 봉투에 넣어 주세요.

【안 타는 쓰레기】둘째·넷째 수요일
유리, 그릇, 금속 등
→ 투명 봉투에 넣어 주세요.

【재활용 쓰레기】금요일
페트병, 캔, 병, 골판지
→ 깨끗이 씻고 나서 내놓아 주세요.
→ 페트병은 뚜껑과 라벨을 떼어 주세요.

【대형 쓰레기】예약제
가구나 가전제품 등
→ 전화(03-6666-7777)로 예약한 후 스티커를 사서 붙여 주세요.

쓰레기는 아침 8시까지 내놓아 주세요.
전날 밤에 내놓지 말아 주세요.
규칙을 지켜서 깨끗한 마을로 만듭시다.',
  17
);

-- N4-9: 近所のお店のレビュー (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '近所のパン屋さんレビュー',
  '駅前にできた新しいパン屋「森のパン工房」に行ってきました。

お店に入ると、パンのいい香りがします。
種類がとても多くて、50種類以上あるそうです。
私はメロンパンとカレーパンを買いました。

メロンパンは外がカリカリで、中はふわふわでした。今まで食べた中で一番おいしかったです。
カレーパンは中のカレーがたくさん入っていて、とても満足しました。

値段は少し高いですが、材料にこだわっているので、しかたがないと思います。
メロンパンは180円、カレーパンは220円でした。

お店の人もとても親切でした。
朝7時から開いているので、朝ごはんにもいいと思います。
ぜひ一度行ってみてください。おすすめです！

評価：★★★★☆（5点中4点）',
  'article',
  'N4',
  120,
  'お店のレビュー',
  '[{"word":"香り","reading":"かおり","meaning_ko":"향기"},{"word":"種類","reading":"しゅるい","meaning_ko":"종류"},{"word":"満足","reading":"まんぞく","meaning_ko":"만족"},{"word":"値段","reading":"ねだん","meaning_ko":"가격"},{"word":"材料","reading":"ざいりょう","meaning_ko":"재료"},{"word":"親切","reading":"しんせつ","meaning_ko":"친절"}]'::jsonb,
  ARRAY['〜そうです（伝聞）', '〜の中で一番', '〜てみてください', '〜ので'],
  '역 앞에 새로 생긴 빵집 "숲의 빵 공방"에 다녀왔습니다.

가게에 들어가면 빵의 좋은 향기가 납니다.
종류가 매우 많아서 50종류 이상 있다고 합니다.
저는 멜론빵과 카레빵을 샀습니다.

멜론빵은 겉은 바삭하고 속은 폭신했습니다. 지금까지 먹은 것 중에 가장 맛있었습니다.
카레빵은 안에 카레가 많이 들어있어서 매우 만족했습니다.

가격은 조금 비싸지만 재료에 신경을 쓰고 있어서 어쩔 수 없다고 생각합니다.
멜론빵은 180엔, 카레빵은 220엔이었습니다.

가게 직원도 매우 친절했습니다.
아침 7시부터 열기 때문에 아침 식사로도 좋다고 생각합니다.
꼭 한번 가 보세요. 추천합니다!

평가：★★★★☆（5점 만점에 4점）',
  18
);


