-- N3-1: 日本のマナーについてのコラム (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本のマナーについて',
  '日本で生活する上で、知っておいたほうがいいマナーがいくつかあります。

まず、靴を脱ぐ場面が多いことです。日本では家に入るとき、必ず靴を脱ぎます。お寺や旅館、一部のレストランでも靴を脱ぐ必要があります。靴をそろえて置くのがマナーです。

次に、電車の中でのマナーです。電車の中では大きな声で話したり、電話をしたりしないのが一般的です。優先席の近くでは、携帯電話の電源を切るか、マナーモードにしてください。

また、食事のときのマナーも大切です。「いただきます」と「ごちそうさまでした」は食事の前後に必ず言います。箸の使い方にもルールがあり、箸で食べ物を人に渡してはいけません。

最後に、ゴミのマナーです。日本の町にはゴミ箱が少ないので、自分のゴミは持ち帰るのが基本です。コンビニのゴミ箱はそのコンビニで買った物のゴミだけを捨てるようにしましょう。

これらのマナーは、日本人にとっては当たり前のことですが、外国から来た人には最初は難しいかもしれません。少しずつ慣れていきましょう。',
  'article',
  'N3',
  170,
  '日本のマナー',
  '[{"word":"場面","reading":"ばめん","meaning_ko":"장면, 상황"},{"word":"一般的","reading":"いっぱんてき","meaning_ko":"일반적"},{"word":"優先席","reading":"ゆうせんせき","meaning_ko":"우선석"},{"word":"携帯電話","reading":"けいたいでんわ","meaning_ko":"휴대전화"},{"word":"当たり前","reading":"あたりまえ","meaning_ko":"당연한"},{"word":"慣れる","reading":"なれる","meaning_ko":"익숙해지다"}]'::jsonb,
  ARRAY['〜上で', '〜てはいけません', '〜ようにしましょう', '〜かもしれません'],
  '일본에서 생활하는 데 있어 알아 두는 편이 좋은 매너가 몇 가지 있습니다.

먼저, 신발을 벗는 상황이 많다는 것입니다. 일본에서는 집에 들어갈 때 반드시 신발을 벗습니다. 사찰이나 여관, 일부 레스토랑에서도 신발을 벗어야 합니다. 신발을 가지런히 놓는 것이 매너입니다.

다음으로, 전철 안에서의 매너입니다. 전철 안에서는 큰 소리로 이야기하거나 전화를 하지 않는 것이 일반적입니다. 우선석 근처에서는 휴대전화 전원을 끄거나 매너모드로 해 주세요.

또한, 식사할 때의 매너도 중요합니다. "이타다키마스"와 "고치소사마데시타"는 식사 전후에 반드시 말합니다. 젓가락 사용법에도 규칙이 있어서 젓가락으로 음식을 다른 사람에게 건네면 안 됩니다.

마지막으로, 쓰레기 매너입니다. 일본 거리에는 쓰레기통이 적기 때문에 자신의 쓰레기는 가져가는 것이 기본입니다. 편의점 쓰레기통은 그 편의점에서 산 물건의 쓰레기만 버리도록 합시다.

이러한 매너는 일본인에게는 당연한 것이지만, 외국에서 온 사람에게는 처음에는 어려울지도 모릅니다. 조금씩 익숙해져 갑시다.',
  19
);

-- N3-2: 防災訓練のお知らせ (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '防災訓練のお知らせ',
  '住民の皆さまへ

秋の防災訓練を下記のとおり実施いたします。
地震はいつ起きるかわかりません。万が一のときに備えて、ぜひご参加ください。

日時：10月15日（日）午前9時〜12時
場所：中央公園

内容：
1. 地震発生時の避難訓練（9:00〜9:30）
   ※防災無線が鳴りますが、本当の地震ではありません。
2. 消火器の使い方体験（9:30〜10:30）
3. 応急手当の方法（10:30〜11:30）
4. 非常食の配布と試食（11:30〜12:00）

持ち物：動きやすい服装、タオル、飲み物
※雨天の場合は、市民体育館で行います。

参加申し込みは不要です。当日、直接会場にお越しください。
ご家族そろってのご参加をお待ちしています。

中央区 防災課',
  'notice',
  'N3',
  150,
  '防災訓練',
  '[{"word":"防災訓練","reading":"ぼうさいくんれん","meaning_ko":"방재 훈련"},{"word":"実施","reading":"じっし","meaning_ko":"실시"},{"word":"避難","reading":"ひなん","meaning_ko":"대피"},{"word":"消火器","reading":"しょうかき","meaning_ko":"소화기"},{"word":"応急手当","reading":"おうきゅうてあて","meaning_ko":"응급처치"},{"word":"非常食","reading":"ひじょうしょく","meaning_ko":"비상식량"}]'::jsonb,
  ARRAY['〜に備えて', '〜のとおり', '〜の場合は', '〜かわかりません'],
  '주민 여러분께

가을 방재 훈련을 아래와 같이 실시합니다.
지진은 언제 일어날지 모릅니다. 만일의 경우에 대비하여 꼭 참가해 주세요.

일시：10월 15일（일）오전 9시~12시
장소：중앙공원

내용：
1. 지진 발생 시 대피 훈련（9:00~9:30）
   ※방재 무선이 울리지만 실제 지진이 아닙니다.
2. 소화기 사용법 체험（9:30~10:30）
3. 응급처치 방법（10:30~11:30）
4. 비상식량 배포 및 시식（11:30~12:00）

지참물：움직이기 편한 복장, 타월, 음료
※우천 시에는 시민체육관에서 진행합니다.

참가 신청은 필요 없습니다. 당일 직접 행사장에 오세요.
가족 모두 함께 참가해 주시기를 기다리겠습니다.

중앙구 방재과',
  20
);

-- N3-3: ボランティア活動報告 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'ボランティア活動報告',
  '「川をきれいにしよう」ボランティア活動報告

9月10日（日）に、毎年恒例の河川清掃ボランティアを行いました。
今年は天気にも恵まれ、大人65名、子ども23名、合計88名の方に参加していただきました。昨年より15名も多く、過去最多の参加者数でした。

活動内容：
午前9時に市役所前に集合し、3つのグループに分かれて清掃を行いました。
多摩川の両岸を約2キロにわたって清掃し、約120袋のゴミを回収しました。
ペットボトルや空き缶が最も多く、中には自転車やタイヤなど大きなゴミもありました。

参加者の声：
「子どもと一緒に参加しました。環境について考えるいい機会になりました。」（40代女性）
「毎年参加しています。年々ゴミが減っているのを実感します。」（60代男性）

来年もこの活動を続けていく予定です。多くの方のご参加をお待ちしています。

中央区ボランティアセンター',
  'report',
  'N3',
  170,
  'ボランティア活動',
  '[{"word":"恒例","reading":"こうれい","meaning_ko":"항례, 매년 하는"},{"word":"河川","reading":"かせん","meaning_ko":"하천"},{"word":"清掃","reading":"せいそう","meaning_ko":"청소"},{"word":"回収","reading":"かいしゅう","meaning_ko":"회수"},{"word":"実感","reading":"じっかん","meaning_ko":"실감"},{"word":"環境","reading":"かんきょう","meaning_ko":"환경"}]'::jsonb,
  ARRAY['〜にわたって', '〜ていただきました', '〜ていく予定です', '〜のを実感する'],
  '"강을 깨끗이 하자" 봉사활동 보고

9월 10일(일)에 매년 실시하는 하천 청소 봉사활동을 진행했습니다.
올해는 날씨도 좋아서 어른 65명, 어린이 23명, 총 88명이 참가해 주셨습니다. 작년보다 15명이나 많은 역대 최다 참가자 수였습니다.

활동 내용：
오전 9시에 시청 앞에 모여서 3개 그룹으로 나뉘어 청소를 진행했습니다.
다마가와 양쪽 기슭을 약 2킬로에 걸쳐 청소하여 약 120봉지의 쓰레기를 회수했습니다.
페트병이나 빈 캔이 가장 많았고, 자전거나 타이어 등 큰 쓰레기도 있었습니다.

참가자 소감：
"아이와 함께 참가했습니다. 환경에 대해 생각하는 좋은 기회가 되었습니다."(40대 여성)
"매년 참가하고 있습니다. 해마다 쓰레기가 줄어들고 있음을 실감합니다."(60대 남성)

내년에도 이 활동을 계속해 나갈 예정입니다. 많은 분들의 참가를 기다리겠습니다.

중앙구 봉사센터',
  21
);

-- N3-4: 日本の食文化 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の食文化',
  '日本の食文化は2013年にユネスコの無形文化遺産に登録されました。「和食」と呼ばれる日本の伝統的な食文化には、いくつかの特徴があります。

一つ目は、「一汁三菜」という考え方です。ご飯、味噌汁、そして3つのおかずをバランスよく食べるという伝統があります。これによって栄養のバランスがとれた健康的な食事ができます。

二つ目は、季節を大切にすることです。日本人は「旬」の食材を使うことを好みます。春にはたけのこ、夏にはすいか、秋にはさんま、冬にはみかんなど、その季節に一番おいしい食べ物を楽しみます。

三つ目は、見た目の美しさです。日本料理は味だけでなく、盛り付けにもこだわります。色とりどりの食材を使い、器にも気を配ります。「目で食べる」という表現があるほど、見た目を大切にしています。

このような特徴を持つ日本の食文化は、世界中の人々に愛されています。しかし最近は、若い世代の食生活が変わりつつあり、伝統的な食文化をどう守っていくかが課題となっています。',
  'essay',
  'N3',
  180,
  '日本の食文化',
  '[{"word":"無形文化遺産","reading":"むけいぶんかいさん","meaning_ko":"무형문화유산"},{"word":"一汁三菜","reading":"いちじゅうさんさい","meaning_ko":"국 하나 반찬 셋"},{"word":"栄養","reading":"えいよう","meaning_ko":"영양"},{"word":"旬","reading":"しゅん","meaning_ko":"제철"},{"word":"盛り付け","reading":"もりつけ","meaning_ko":"담음새, 플레이팅"},{"word":"器","reading":"うつわ","meaning_ko":"그릇"}]'::jsonb,
  ARRAY['〜と呼ばれる', '〜つつある', '〜ほど', '〜にこだわる'],
  '일본의 식문화는 2013년에 유네스코 무형문화유산에 등재되었습니다. "와쇼쿠"라고 불리는 일본의 전통적인 식문화에는 몇 가지 특징이 있습니다.

첫째는 "이치주산사이(국 하나 반찬 셋)"라는 개념입니다. 밥, 된장국, 그리고 3가지 반찬을 균형 있게 먹는 전통이 있습니다. 이를 통해 영양 균형이 잡힌 건강한 식사를 할 수 있습니다.

둘째는 계절을 소중히 여기는 것입니다. 일본인은 "제철" 식재료를 사용하는 것을 좋아합니다. 봄에는 죽순, 여름에는 수박, 가을에는 꽁치, 겨울에는 귤 등 그 계절에 가장 맛있는 음식을 즐깁니다.

셋째는 외관의 아름다움입니다. 일본 요리는 맛뿐만 아니라 담음새에도 신경을 씁니다. 다양한 색깔의 식재료를 사용하고 그릇에도 신경을 씁니다. "눈으로 먹는다"라는 표현이 있을 만큼 외관을 중시합니다.

이러한 특징을 가진 일본의 식문화는 전 세계 사람들에게 사랑받고 있습니다. 하지만 최근 젊은 세대의 식생활이 변화하고 있어 전통적인 식문화를 어떻게 지켜나갈지가 과제가 되고 있습니다.',
  22
);

-- N3-5: 住民向けアンケート結果 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '住民アンケート結果',
  '「暮らしやすさに関するアンケート」結果報告

先月実施した住民アンケートの結果をお知らせします。
回答者数は1,200名で、回答率は48%でした。

【住んでいる地域の満足度】
満足・やや満足：62%
普通：25%
やや不満・不満：13%

【特に満足している点】（複数回答可）
1位：交通の便がいい（58%）
2位：買い物がしやすい（45%）
3位：公園や緑が多い（38%）

【改善してほしい点】（複数回答可）
1位：病院が少ない（42%）
2位：夜道が暗くて危ない（35%）
3位：子どもの遊び場が少ない（28%）

自由回答では、「最近、外国人住民が増えたので、多言語での案内を増やしてほしい」という意見が多くありました。
区としては、今回の結果を参考にして、来年度の計画に反映させていく方針です。

詳しい結果は区のホームページでご覧いただけます。

中央区 企画課',
  'report',
  'N3',
  160,
  '住民アンケート',
  '[{"word":"暮らし","reading":"くらし","meaning_ko":"생활, 삶"},{"word":"満足度","reading":"まんぞくど","meaning_ko":"만족도"},{"word":"改善","reading":"かいぜん","meaning_ko":"개선"},{"word":"多言語","reading":"たげんご","meaning_ko":"다국어"},{"word":"反映","reading":"はんえい","meaning_ko":"반영"},{"word":"方針","reading":"ほうしん","meaning_ko":"방침"}]'::jsonb,
  ARRAY['〜に関する', '〜てほしい', '〜させていく', '〜いただけます'],
  '"살기 좋은 환경에 관한 설문조사" 결과 보고

지난달 실시한 주민 설문조사 결과를 알려드립니다.
응답자 수는 1,200명이며, 응답률은 48%였습니다.

【거주 지역 만족도】
만족·대체로 만족：62%
보통：25%
다소 불만·불만：13%

【특히 만족하는 점】(복수 응답 가능)
1위：교통이 편리하다(58%)
2위：쇼핑하기 편리하다(45%)
3위：공원과 녹지가 많다(38%)

【개선을 원하는 점】(복수 응답 가능)
