2위：밤길이 어두워 위험하다(35%)
3위：아이들 놀이터가 적다(28%)

자유 응답에서는 "최근 외국인 주민이 늘었으므로 다국어 안내를 늘려 주었으면 한다"는 의견이 많았습니다.
구에서는 이번 결과를 참고하여 내년도 계획에 반영해 나갈 방침입니다.

자세한 결과는 구 홈페이지에서 확인하실 수 있습니다.

중앙구 기획과',
  23
);

-- N3-6: 電車通勤のマナー (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '電車通勤のマナー',
  '日本で電車に乗るとき、守るべきマナーがいくつかあります。毎日電車を利用する人も、たまにしか乗らない人も、ぜひ覚えておいてください。

まず、乗り降りのマナーです。電車が到着したら、まず降りる人を先に通してから乗りましょう。ドアの前に立ったまま乗り降りの邪魔をしないようにしてください。

次に、車内での過ごし方です。リュックサックは前に抱えるか、網棚の上に置くようにしましょう。混んでいる電車では、スマートフォンの操作も周りの迷惑にならないよう気をつけてください。音楽を聴くときは、音が漏れていないか確認しましょう。

また、座席についてのマナーもあります。荷物を座席に置いて場所を取らないようにしましょう。お年寄りや体が不自由な方、妊婦さんを見かけたら、席を譲るのが望ましいです。

朝の通勤時間帯は特に混雑しますが、お互いに思いやりを持って、気持ちよく移動できるようにしたいものです。',
  'article',
  'N3',
  175,
  '電車マナー',
  '[{"word":"乗り降り","reading":"のりおり","meaning_ko":"승하차"},{"word":"邪魔","reading":"じゃま","meaning_ko":"방해"},{"word":"網棚","reading":"あみだな","meaning_ko":"선반"},{"word":"迷惑","reading":"めいわく","meaning_ko":"폐, 민폐"},{"word":"妊婦","reading":"にんぷ","meaning_ko":"임산부"},{"word":"思いやり","reading":"おもいやり","meaning_ko":"배려"}]'::jsonb,
  ARRAY['〜べき', '〜ようにする', '〜たいものです', '〜のが望ましい'],
  '일본에서 전철을 탈 때 지켜야 할 매너가 몇 가지 있습니다. 매일 전철을 이용하는 사람도, 가끔 타는 사람도 꼭 기억해 두세요.

먼저, 승하차 매너입니다. 전철이 도착하면 먼저 내리는 사람을 먼저 보낸 후에 탑시다. 문 앞에 서서 승하차를 방해하지 않도록 해 주세요.

다음으로, 차내에서의 행동입니다. 배낭은 앞으로 안거나 선반 위에 올려놓도록 합시다. 붐비는 전철에서는 스마트폰 조작도 주위에 폐가 되지 않도록 주의해 주세요. 음악을 들을 때는 소리가 새어 나가지 않는지 확인합시다.

또한 좌석에 관한 매너도 있습니다. 짐을 좌석에 올려놓아 자리를 차지하지 않도록 합시다. 노인이나 몸이 불편한 분, 임산부를 보면 자리를 양보하는 것이 바람직합니다.

아침 출퇴근 시간대는 특히 혼잡하지만, 서로 배려심을 가지고 기분 좋게 이동할 수 있도록 하고 싶은 것입니다.',
  24
);

-- N3-7: 季節の手紙の書き方 (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '季節の手紙の書き方',
  '日本には、季節に合わせた手紙を書く文化があります。ここでは、基本的な季節の挨拶の書き方を紹介します。

【手紙の基本構成】
1. 時候の挨拶（季節の挨拶）
2. 相手の健康を気遣う言葉
3. 本文
4. 結びの言葉

【季節ごとの挨拶例】
春（4月）：「桜の花が美しい季節になりました。」
夏（7月）：「暑い日が続いておりますが、いかがお過ごしでしょうか。」
秋（10月）：「秋風が心地よい季節となりました。」
冬（1月）：「寒さ厳しい折、いかがお過ごしでしょうか。」

【書くときのポイント】
・季節の挨拶は、実際の天気や気候に合わせて書くと自然です。
・親しい友人への手紙では、もう少しくだけた表現でもかまいません。
・年賀状は1月1日に届くように、12月中旬までに出しましょう。
・暑中見舞いは7月中旬から8月初旬に出します。

手紙を書く習慣が少なくなっている現代ですが、心のこもった手書きの手紙は、もらった人をとても喜ばせるものです。',
  'instruction',
  'N3',
  175,
  '手紙の書き方',
  '[{"word":"時候","reading":"じこう","meaning_ko":"시후, 계절"},{"word":"気遣う","reading":"きづかう","meaning_ko":"걱정하다, 신경 쓰다"},{"word":"心地よい","reading":"ここちよい","meaning_ko":"기분 좋은"},{"word":"年賀状","reading":"ねんがじょう","meaning_ko":"연하장"},{"word":"暑中見舞い","reading":"しょちゅうみまい","meaning_ko":"서중 문안(여름 안부 인사)"},{"word":"心のこもった","reading":"こころのこもった","meaning_ko":"마음이 담긴"}]'::jsonb,
  ARRAY['〜に合わせて', '〜でもかまいません', '〜ように', '〜ものです'],
  '일본에는 계절에 맞는 편지를 쓰는 문화가 있습니다. 여기서는 기본적인 계절 인사의 쓰는 법을 소개합니다.

【편지의 기본 구성】
1. 계절 인사
2. 상대방의 건강을 걱정하는 말
3. 본문
4. 맺음말

【계절별 인사 예시】
봄(4월)："벚꽃이 아름다운 계절이 되었습니다."
여름(7월)："더운 날이 계속되고 있습니다만, 어떻게 지내고 계신지요."
가을(10월)："가을바람이 상쾌한 계절이 되었습니다."
겨울(1월)："추위가 엄한 이때, 어떻게 지내고 계신지요."

【쓸 때의 포인트】
・계절 인사는 실제 날씨나 기후에 맞춰 쓰면 자연스럽습니다.
・친한 친구에게 보내는 편지에서는 좀 더 편한 표현이어도 괜찮습니다.
・연하장은 1월 1일에 도착하도록 12월 중순까지 보냅시다.
・서중 문안은 7월 중순부터 8월 초순에 보냅니다.

편지를 쓰는 습관이 줄어들고 있는 현대이지만, 마음이 담긴 손 글씨 편지는 받은 사람을 매우 기쁘게 하는 것입니다.',
  25
);

-- N3-8: 地域のお祭りイベント報告 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '地域のお祭り報告',
  '第15回さくら祭りイベント報告

10月8日（日）、中央公園にて「第15回さくら祭り」が開催されました。
今年は3年ぶりの通常開催となり、約3,500人の来場者で大いににぎわいました。

【主なイベント内容】
・盆踊り大会：やぐらを中心に、子どもからお年寄りまで多くの方が踊りを楽しみました。
・屋台コーナー：焼きそば、たこ焼き、綿あめなど15の屋台が出店しました。
・ステージ発表：地元の小学生による太鼓の演奏や、ダンスグループの発表がありました。
・抽選会：地元商店街の協賛により、豪華な景品が当たる抽選会が行われました。

来場者の声：
「子どもたちが楽しそうに踊っている姿を見て、うれしくなりました。」
「久しぶりのお祭りで、近所の人たちと交流できてよかったです。」

ボランティアスタッフとして参加してくださった52名の皆さま、協賛いただいた地元企業の皆さまに感謝申し上げます。

さくら祭り実行委員会',
  'report',
  'N3',
  170,
  '地域のお祭り',
  '[{"word":"開催","reading":"かいさい","meaning_ko":"개최"},{"word":"来場者","reading":"らいじょうしゃ","meaning_ko":"방문객"},{"word":"盆踊り","reading":"ぼんおどり","meaning_ko":"본오도리(일본 전통춤)"},{"word":"屋台","reading":"やたい","meaning_ko":"포장마차"},{"word":"抽選会","reading":"ちゅうせんかい","meaning_ko":"추첨회"},{"word":"協賛","reading":"きょうさん","meaning_ko":"협찬"}]'::jsonb,
  ARRAY['〜ぶりの', '〜として', '〜により', '〜申し上げます'],
  '제15회 사쿠라 축제 이벤트 보고

10월 8일(일), 중앙공원에서 "제15회 사쿠라 축제"가 개최되었습니다.
올해는 3년 만의 정상 개최가 되어 약 3,500명의 방문객으로 대성황이었습니다.

【주요 이벤트 내용】
・본오도리 대회：무대를 중심으로 어린이부터 어르신까지 많은 분들이 춤을 즐겼습니다.
・포장마차 코너：야키소바, 타코야키, 솜사탕 등 15개 포장마차가 출점했습니다.
・스테이지 발표：지역 초등학생의 태고 연주와 댄스 그룹의 발표가 있었습니다.
・추첨회：지역 상점가의 협찬으로 호화로운 경품이 당첨되는 추첨회가 열렸습니다.

방문객 소감：
"아이들이 즐겁게 춤추는 모습을 보니 기뻤습니다."
"오랜만의 축제에서 이웃 사람들과 교류할 수 있어서 좋았습니다."

봉사 스태프로 참가해 주신 52명의 여러분, 협찬해 주신 지역 기업 여러분께 감사드립니다.

사쿠라 축제 실행위원회',
  26
);

-- N3-9: 日本の住宅事情 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の住宅事情',
  '日本で部屋を借りるとき、知っておくべきことがいくつかあります。

まず、費用についてです。日本では、入居するときに「敷金」と「礼金」を払うのが一般的です。敷金は家賃の1〜2か月分で、退去するときに部屋の修理代を引いた金額が戻ってきます。礼金は大家さんへのお礼で、こちらは戻ってきません。最近は敷金・礼金ゼロの物件も増えています。

次に、部屋の広さの表し方です。日本では「畳（じょう）」という単位を使います。1畳は約1.6平方メートルです。また、「1K」「2LDK」などの表記がよく使われます。「K」はキッチン、「L」はリビング、「D」はダイニングを意味します。

部屋を探すときは、不動産屋に行くか、インターネットで検索するのが一般的です。外国人の場合、保証人が必要になることが多いですが、保証会社を利用すれば保証人がいなくても借りられる場合があります。

また、日本のアパートやマンションでは、靴を脱いで生活するのが基本です。壁に穴を開けたり、ペットを飼ったりすることが禁止されている物件も多いので、契約前によく確認しましょう。',
  'article',
  'N3',
  180,
  '日本の住宅事情',
  '[{"word":"敷金","reading":"しききん","meaning_ko":"보증금"},{"word":"礼金","reading":"れいきん","meaning_ko":"사례금"},{"word":"退去","reading":"たいきょ","meaning_ko":"퇴거"},{"word":"大家","reading":"おおや","meaning_ko":"집주인"},{"word":"不動産屋","reading":"ふどうさんや","meaning_ko":"부동산"},{"word":"保証人","reading":"ほしょうにん","meaning_ko":"보증인"}]'::jsonb,
  ARRAY['〜べき', '〜のが一般的', '〜ば〜場合がある', '〜たりすること'],
  '일본에서 방을 빌릴 때 알아 두어야 할 것이 몇 가지 있습니다.

먼저, 비용에 대해서입니다. 일본에서는 입주할 때 "시키킨(보증금)"과 "레이킨(사례금)"을 내는 것이 일반적입니다. 시키킨은 월세의 1~2개월분으로, 퇴거할 때 방 수리비를 뺀 금액이 돌아옵니다. 레이킨은 집주인에게 드리는 감사의 의미로, 이것은 돌아오지 않습니다. 최근에는 시키킨·레이킨이 없는 물건도 늘고 있습니다.

다음으로, 방 넓이의 표시 방법입니다. 일본에서는 "조(다다미 수)"라는 단위를 사용합니다. 1조는 약 1.6제곱미터입니다. 또한 "1K", "2LDK" 등의 표기가 자주 사용됩니다. "K"는 주방, "L"은 거실, "D"는 다이닝을 의미합니다.

방을 찾을 때는 부동산에 가거나 인터넷에서 검색하는 것이 일반적입니다. 외국인의 경우 보증인이 필요한 경우가 많지만, 보증 회사를 이용하면 보증인이 없어도 빌릴 수 있는 경우가 있습니다.

또한 일본의 아파트나 맨션에서는 신발을 벗고 생활하는 것이 기본입니다. 벽에 구멍을 뚫거나 반려동물을 기르는 것이 금지된 물건도 많으므로 계약 전에 잘 확인합시다.',
  27
);


-- ============================================
-- N2 Reading Passages (9)
-- ============================================

-- N2-1: 少子高齢化の影響 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '少子高齢化の影響',
  '日本は現在、世界でも類を見ないスピードで少子高齢化が進行している。2023年の出生数は約75万人と過去最少を記録し、総人口に占める65歳以上の割合は29%を超えた。この人口構造の変化は、社会のあらゆる側面に深刻な影響を及ぼしている。

まず、労働力不足の問題がある。生産年齢人口の減少により、多くの業種で人手が足りない状況が続いている。特に介護、農業、建設といった分野では深刻であり、外国人労働者の受け入れ拡大が議論されている。

次に、社会保障制度への影響が挙げられる。年金や医療費を支える現役世代の負担は年々増加しており、制度の持続可能性が問われている。かつては高齢者1人を現役世代約10人で支えていたが、現在では約2人で支えなければならない計算になる。

さらに、地方の過疎化も深刻だ。若者が都市部に流出することで、地方の学校や病院が閉鎖され、コミュニティの維持が困難になっている地域が増えている。

政府はさまざまな対策を講じているが、出生率の回復には至っていない。子育て支援の充実、働き方改革、地方創生など、複合的なアプローチが求められている。少子高齢化は日本社会全体が真剣に向き合うべき最重要課題の一つであると言えよう。',
  'essay',
  'N2',
  240,
  '少子高齢化',
  '[{"word":"類を見ない","reading":"るいをみない","meaning_ko":"유례없는"},{"word":"出生数","reading":"しゅっしょうすう","meaning_ko":"출생 수"},{"word":"過疎化","reading":"かそか","meaning_ko":"과소화"},{"word":"持続可能性","reading":"じぞくかのうせい","meaning_ko":"지속 가능성"},{"word":"講じる","reading":"こうじる","meaning_ko":"강구하다"},{"word":"充実","reading":"じゅうじつ","meaning_ko":"충실"}]'::jsonb,
  ARRAY['〜に至っていない', '〜と言えよう', '〜べき', '〜ことで'],
  '일본은 현재 세계에서도 유례없는 속도로 저출산 고령화가 진행되고 있다. 2023년 출생 수는 약 75만 명으로 역대 최저를 기록했고, 총인구에서 65세 이상이 차지하는 비율은 29%를 넘었다. 이러한 인구 구조의 변화는 사회의 모든 측면에 심각한 영향을 미치고 있다.

먼저 노동력 부족 문제가 있다. 생산가능인구 감소로 인해 많은 업종에서 인력이 부족한 상황이 계속되고 있다. 특히 돌봄, 농업, 건설 등의 분야에서 심각하며 외국인 노동자 수용 확대가 논의되고 있다.

다음으로 사회보장제도에 대한 영향을 들 수 있다. 연금과 의료비를 지탱하는 현역 세대의 부담은 해마다 증가하고 있으며 제도의 지속 가능성이 의문시되고 있다. 과거에는 고령자 1명을 현역 세대 약 10명이 지탱했지만 현재는 약 2명으로 지탱해야 하는 계산이 된다.

게다가 지방의 과소화도 심각하다. 젊은이들이 도시 지역으로 유출됨에 따라 지방의 학교나 병원이 폐쇄되고 커뮤니티 유지가 어려워지는 지역이 늘고 있다.

정부는 다양한 대책을 강구하고 있지만 출산율 회복에는 이르지 못하고 있다. 육아 지원 충실화, 근무 방식 개혁, 지방 창생 등 복합적인 접근이 요구되고 있다. 저출산 고령화는 일본 사회 전체가 진지하게 마주해야 할 최중요 과제 중 하나라고 말할 수 있을 것이다.',
  28
);

-- N2-2: 日本の教育制度 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の教育制度',
  '日本の教育制度は「6-3-3-4制」と呼ばれ、小学校6年、中学校3年、高等学校3年、大学4年で構成されている。このうち小学校と中学校の9年間が義務教育であり、ほぼ全ての子どもが通っている。

日本の教育の特徴の一つは、学校行事が充実していることだ。運動会、文化祭、修学旅行など、教科の授業だけでなく、集団生活を通じて社会性を育む機会が多く設けられている。また、生徒が自ら教室を掃除する「清掃の時間」も日本独自の文化として知られている。

高校への進学率は約99%と非常に高く、大学・短大への進学率も約60%に達している。しかし、受験競争が激しいことが長年の問題として指摘されている。中学生や高校生が塾や予備校に通うことは珍しくなく、「受験戦争」という言葉も生まれた。

近年では、従来の「詰め込み教育」から「ゆとり教育」へ、そして現在の「主体的・対話的で深い学び」へと、教育方針の転換が繰り返されてきた。グローバル化に対応するため、英語教育の強化や、プログラミング教育の必修化なども進められている。

日本の教育制度は高い識字率や基礎学力の維持に貢献してきたが、個性や創造性をいかに伸ばすかという点では、まだ課題が残されていると言われている。',
  'article',
  'N2',
  240,
  '日本の教育制度',
  '[{"word":"義務教育","reading":"ぎむきょういく","meaning_ko":"의무교육"},{"word":"社会性","reading":"しゃかいせい","meaning_ko":"사회성"},{"word":"進学率","reading":"しんがくりつ","meaning_ko":"진학률"},{"word":"詰め込み","reading":"つめこみ","meaning_ko":"주입식"},{"word":"主体的","reading":"しゅたいてき","meaning_ko":"주체적"},{"word":"識字率","reading":"しきじりつ","meaning_ko":"문해율"}]'::jsonb,
  ARRAY['〜として知られている', '〜てきた', '〜いかに〜か', '〜と言われている'],
  '일본의 교육 제도는 "6-3-3-4제"라고 불리며 초등학교 6년, 중학교 3년, 고등학교 3년, 대학 4년으로 구성되어 있다. 이 중 초등학교와 중학교 9년간이 의무교육이며 거의 모든 아이가 다니고 있다.

일본 교육의 특징 중 하나는 학교 행사가 충실하다는 점이다. 운동회, 문화제, 수학여행 등 교과 수업뿐만 아니라 단체 생활을 통해 사회성을 기르는 기회가 많이 마련되어 있다. 또한 학생이 스스로 교실을 청소하는 "청소 시간"도 일본 특유의 문화로 알려져 있다.

고교 진학률은 약 99%로 매우 높으며 대학·단기대학 진학률도 약 60%에 달하고 있다. 그러나 입시 경쟁이 치열한 것이 오랜 문제로 지적되고 있다. 중학생이나 고등학생이 학원이나 입시학원에 다니는 것은 드문 일이 아니며 "수험 전쟁"이라는 말도 생겨났다.

최근에는 기존의 "주입식 교육"에서 "여유 교육"으로, 그리고 현재의 "주체적·대화적이고 깊은 배움"으로 교육 방침의 전환이 거듭되어 왔다. 글로벌화에 대응하기 위해 영어 교육 강화와 프로그래밍 교육 필수화 등도 추진되고 있다.

일본의 교육 제도는 높은 문해율과 기초 학력 유지에 공헌해 왔지만, 개성과 창의성을 어떻게 키울 것인가 하는 점에서는 아직 과제가 남아 있다고 말해지고 있다.',
  29
);

-- N2-3: 環境問題とエコ活動 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '環境問題とエコ活動',
  '地球温暖化や海洋プラスチック汚染など、環境問題は今や全人類が取り組むべき喫緊の課題となっている。日本においても、さまざまなレベルでエコ活動が展開されている。

政府レベルでは、2050年までにカーボンニュートラルを達成するという目標が掲げられている。再生可能エネルギーの普及促進や、電気自動車への移行支援などが進められている。2020年にはレジ袋の有料化が全国で実施され、マイバッグを持参する習慣が広く定着した。

自治体レベルでは、ゴミの分別収集やリサイクルの推進が行われている。日本のゴミ分別は世界でもトップレベルの細かさで、地域によっては10種類以上に分けることが求められる。また、フードバンクやフリーマーケットを通じた食品ロスの削減にも力を入れている自治体が増えている。

個人レベルでも、エコバッグやマイボトルの使用、節電・節水の心がけ、地産地消の食材を選ぶことなど、日常の中でできる取り組みは多い。最近では「エシカル消費」という概念も広まりつつあり、環境や社会に配慮した商品を選ぶ消費者が増えている。

しかし、便利さを追求する現代社会において、環境への配慮を継続することは容易ではない。一人ひとりの小さな行動の積み重ねが、大きな変化につながるという意識を持ち続けることが重要である。',
  'essay',
  'N2',
  230,
  '環境問題とエコ',
  '[{"word":"喫緊","reading":"きっきん","meaning_ko":"긴급한"},{"word":"カーボンニュートラル","reading":"カーボンニュートラル","meaning_ko":"탄소중립"},{"word":"定着","reading":"ていちゃく","meaning_ko":"정착"},{"word":"地産地消","reading":"ちさんちしょう","meaning_ko":"지산지소(지역 생산 지역 소비)"},{"word":"配慮","reading":"はいりょ","meaning_ko":"배려"},{"word":"積み重ね","reading":"つみかさね","meaning_ko":"축적, 쌓아감"}]'::jsonb,
  ARRAY['〜つつある', '〜において', '〜を通じた', '〜という意識'],
  '지구온난화나 해양 플라스틱 오염 등 환경 문제는 이제 전 인류가 대처해야 할 긴급한 과제가 되고 있다. 일본에서도 다양한 차원에서 친환경 활동이 전개되고 있다.

정부 차원에서는 2050년까지 탄소중립을 달성하겠다는 목표가 내걸려 있다. 재생가능 에너지의 보급 촉진이나 전기자동차 전환 지원 등이 추진되고 있다. 2020년에는 비닐봉지 유료화가 전국적으로 실시되어 에코백을 지참하는 습관이 널리 정착했다.

지자체 차원에서는 쓰레기 분리수거와 재활용 추진이 이루어지고 있다. 일본의 쓰레기 분류는 세계에서도 최고 수준의 세밀함으로 지역에 따라서는 10종류 이상으로 분류하는 것이 요구된다. 또한 푸드뱅크나 벼룩시장을 통한 음식물 쓰레기 감소에도 힘을 쏟는 지자체가 늘고 있다.

개인 차원에서도 에코백이나 개인 텀블러 사용, 절전·절수 실천, 지역 생산 식재료를 선택하는 것 등 일상 속에서 할 수 있는 노력은 많다. 최근에는 "윤리적 소비"라는 개념도 확산되고 있으며 환경이나 사회를 배려한 상품을 선택하는 소비자가 늘고 있다.

그러나 편리함을 추구하는 현대 사회에서 환경에 대한 배려를 지속하는 것은 쉽지 않다. 한 사람 한 사람의 작은 행동의 축적이 큰 변화로 이어진다는 의식을 계속 가지는 것이 중요하다.',
  30
);

-- N2-4: 食品ロスの現状 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '食品ロスの現状',
  '食品ロスとは、まだ食べられるのに廃棄される食品のことを指す。日本では年間約523万トンの食品ロスが発生しており、これは国民一人当たりに換算すると、毎日おにぎり約1個分を捨てている計算になる。

食品ロスの発生源は大きく二つに分けられる。一つは食品製造業や飲食店、スーパーなどの事業系で、全体の約54%を占める。もう一つは家庭系で、約46%を占めている。

事業系の食品ロスの主な原因としては、商品の売れ残り、返品、規格外品の廃棄などが挙げられる。特に日本独特の商習慣である「3分の1ルール」が問題視されている。これは、賞味期限の3分の1が過ぎた時点で小売店に納品できなくなるというルールで、まだ十分に食べられる商品が廃棄される一因となっている。

家庭系では、買いすぎによる食べ残し、調理の際に捨ててしまう過剰な皮むきなどが主な原因である。また、賞味期限と消費期限の違いを正しく理解していないために、食べられるものを捨ててしまうケースも多い。

この問題に対し、フードバンクへの寄付、食べきりサイズの商品開発、「てまえどり」の推進など、さまざまな取り組みが始まっている。食品ロスの削減は、環境保護だけでなく、食料安全保障の観点からも重要な課題である。',
  'report',
  'N2',
  240,
  '食品ロス',
  '[{"word":"廃棄","reading":"はいき","meaning_ko":"폐기"},{"word":"換算","reading":"かんさん","meaning_ko":"환산"},{"word":"規格外品","reading":"きかくがいひん","meaning_ko":"규격 외 제품"},{"word":"商習慣","reading":"しょうしゅうかん","meaning_ko":"상관행"},{"word":"賞味期限","reading":"しょうみきげん","meaning_ko":"유통기한"},{"word":"食料安全保障","reading":"しょくりょうあんぜんほしょう","meaning_ko":"식량 안보"}]'::jsonb,
  ARRAY['〜を指す', '〜として挙げられる', '〜一因となっている', '〜の観点からも'],
  '식품 로스란 아직 먹을 수 있는데도 폐기되는 식품을 가리킨다. 일본에서는 연간 약 523만 톤의 식품 로스가 발생하고 있으며, 이는 국민 1인당으로 환산하면 매일 주먹밥 약 1개분을 버리고 있는 셈이 된다.

식품 로스의 발생원은 크게 두 가지로 나뉜다. 하나는 식품 제조업이나 음식점, 슈퍼 등의 사업계로 전체의 약 54%를 차지한다. 다른 하나는 가정계로 약 46%를 차지하고 있다.

사업계 식품 로스의 주요 원인으로는 상품의 재고, 반품, 규격 외 제품의 폐기 등을 들 수 있다. 특히 일본 특유의 상관행인 "3분의 1 룰"이 문제시되고 있다. 이는 유통기한의 3분의 1이 지난 시점에서 소매점에 납품할 수 없게 되는 규칙으로, 아직 충분히 먹을 수 있는 상품이 폐기되는 한 원인이 되고 있다.

가정계에서는 과다 구매에 의한 음식 남기기, 조리 시 버려지는 과도한 껍질 벗기기 등이 주요 원인이다. 또한 유통기한과 소비기한의 차이를 올바르게 이해하지 못해 먹을 수 있는 것을 버리는 경우도 많다.

이 문제에 대해 푸드뱅크 기부, 다 먹을 수 있는 크기의 상품 개발, "앞에 있는 것부터 집기" 추진 등 다양한 노력이 시작되고 있다. 식품 로스 감소는 환경 보호뿐만 아니라 식량 안보의 관점에서도 중요한 과제이다.',
  31
);

-- N2-5: 外国人住民への生活支援 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '外国人住民への生活支援',
  '日本に住む外国人の数は年々増加しており、2023年末時点で約340万人に達した。こうした状況の中、外国人住民が安心して暮らせるよう、さまざまな生活支援の取り組みが進められている。

言語面での支援は最も基本的なものだ。多くの自治体では、市役所の窓口に多言語対応のスタッフを配置したり、翻訳タブレットを導入したりしている。また、無料の日本語教室を開催し、日本語学習の機会を提供している自治体も増えている。災害時の多言語情報発信も、外国人の安全を守る上で欠かせない取り組みである。

生活面では、ゴミの出し方や交通ルール、医療制度の利用方法など、日本の生活習慣に関する情報を多言語で提供するガイドブックが作成されている。特に医療に関しては、言葉の壁により適切な治療を受けられないケースが問題となっており、医療通訳の整備が急がれている。

子育て支援も重要な分野だ。外国にルーツを持つ子どもたちが学校生活に適応できるよう、日本語指導や母語を活用した学習支援が行われている。しかし、こうした支援は地域によって格差があり、十分な支援を受けられない子どもたちも少なくない。

多文化共生社会の実現には、行政のサポートだけでなく、地域住民一人ひとりが異なる文化を理解し、尊重する姿勢を持つことが不可欠である。',
  'article',
  'N2',
  245,
  '外国人生活支援',
  '[{"word":"自治体","reading":"じちたい","meaning_ko":"지자체"},{"word":"配置","reading":"はいち","meaning_ko":"배치"},{"word":"欠かせない","reading":"かかせない","meaning_ko":"빠뜨릴 수 없는"},{"word":"整備","reading":"せいび","meaning_ko":"정비"},{"word":"格差","reading":"かくさ","meaning_ko":"격차"},{"word":"不可欠","reading":"ふかけつ","meaning_ko":"불가결한"}]'::jsonb,
  ARRAY['〜上で', '〜ケースが問題となっている', '〜よう', '〜によって格差がある'],
  '일본에 사는 외국인 수는 해마다 증가하고 있으며 2023년 말 시점에서 약 340만 명에 달했다. 이러한 상황 속에서 외국인 주민이 안심하고 살 수 있도록 다양한 생활 지원 노력이 추진되고 있다.

언어적 지원은 가장 기본적인 것이다. 많은 지자체에서는 시청 창구에 다국어 대응 직원을 배치하거나 번역 태블릿을 도입하고 있다. 또한 무료 일본어 교실을 개최하여 일본어 학습 기회를 제공하는 지자체도 늘고 있다. 재해 시 다국어 정보 발신도 외국인의 안전을 지키는 데 빠뜨릴 수 없는 노력이다.

생활면에서는 쓰레기 배출 방법이나 교통 규칙, 의료 제도 이용 방법 등 일본의 생활 습관에 관한 정보를 다국어로 제공하는 가이드북이 작성되고 있다. 특히 의료에 관해서는 언어 장벽으로 인해 적절한 치료를 받지 못하는 경우가 문제가 되고 있어 의료 통역 정비가 시급하다.

육아 지원도 중요한 분야이다. 외국에 뿌리를 둔 아이들이 학교 생활에 적응할 수 있도록 일본어 지도와 모국어를 활용한 학습 지원이 이루어지고 있다. 그러나 이러한 지원은 지역에 따라 격차가 있어 충분한 지원을 받지 못하는 아이들도 적지 않다.

다문화 공생 사회의 실현에는 행정의 지원뿐만 아니라 지역 주민 한 사람 한 사람이 서로 다른 문화를 이해하고 존중하는 자세를 갖는 것이 불가결하다.',
  32
);

-- N2-6: 日本の医療制度 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の医療制度',
  '日本の医療制度は「国民皆保険」を基本としており、全ての国民が何らかの公的な健康保険に加入することが義務づけられている。これにより、医療費の自己負担は原則3割で済み、高額な治療を受けた場合でも「高額療養費制度」によって月々の負担に上限が設けられている。

病院には大きく分けて、地域のクリニック（診療所）と総合病院がある。日本では「かかりつけ医」を持つことが推奨されており、まず近くのクリニックを受診し、必要に応じて紹介状を書いてもらい、大きな病院を受診するという流れが一般的だ。紹介状なしで大病院を受診すると、追加の費用がかかる場合がある。

救急医療体制も整備されている。夜間や休日に急病になった場合は、「#7119」に電話すれば、症状に応じた対応を案内してもらえる。命に関わる緊急事態には「119」で救急車を呼ぶことができ、この利用は無料である。

しかし、日本の医療制度にも課題がある。高齢化に伴い、医療費の総額は年々増加しており、制度の財政的な持続性が懸念されている。また、医師の偏在も問題で、都市部と地方では医師の数に大きな差がある。特に産婦人科や小児科の医師不足は深刻であり、地域によっては必要な医療を受けるのが困難な状況も生まれている。',
  'article',
  'N2',
  245,
  '日本の医療制度',
  '[{"word":"国民皆保険","reading":"こくみんかいほけん","meaning_ko":"국민개보험"},{"word":"自己負担","reading":"じこふたん","meaning_ko":"자기부담"},{"word":"高額療養費","reading":"こうがくりょうようひ","meaning_ko":"고액요양비"},{"word":"かかりつけ医","reading":"かかりつけい","meaning_ko":"주치의"},{"word":"偏在","reading":"へんざい","meaning_ko":"편재"},{"word":"懸念","reading":"けねん","meaning_ko":"우려"}]'::jsonb,
  ARRAY['〜が義務づけられている', '〜に応じて', '〜に伴い', '〜のが困難な'],
  '일본의 의료 제도는 "국민개보험"을 기본으로 하고 있으며 모든 국민이 어떤 형태든 공적 건강보험에 가입할 의무가 있다. 이에 따라 의료비 자기부담은 원칙적으로 3할이며 고액 치료를 받았을 경우에도 "고액요양비 제도"에 의해 월별 부담에 상한이 설정되어 있다.

병원은 크게 나누어 지역 클리닉(진료소)과 종합병원이 있다. 일본에서는 "주치의"를 가지는 것이 권장되고 있으며, 먼저 가까운 클리닉을 방문하고 필요에 따라 소개장을 받아 큰 병원을 방문하는 흐름이 일반적이다. 소개장 없이 대형 병원을 방문하면 추가 비용이 발생할 수 있다.

응급 의료 체계도 정비되어 있다. 야간이나 휴일에 급병이 생겼을 때는 "#7119"에 전화하면 증상에 따른 대응을 안내받을 수 있다. 생명에 관련된 긴급 사태에는 "119"로 구급차를 부를 수 있으며 이 이용은 무료이다.

그러나 일본의 의료 제도에도 과제가 있다. 고령화에 따라 의료비 총액은 해마다 증가하고 있으며 제도의 재정적 지속성이 우려되고 있다. 또한 의사의 편재도 문제로, 도시 지역과 지방에서는 의사 수에 큰 차이가 있다. 특히 산부인과와 소아과 의사 부족은 심각하며, 지역에 따라서는 필요한 의료를 받기가 어려운 상황도 발생하고 있다.',
  33
);

-- N2-7: ワークライフバランス (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'ワークライフバランス',
  '「ワークライフバランス」という言葉が日本で広く知られるようになって久しい。仕事と私生活の調和を意味するこの概念は、かつての日本の働き方を大きく見直すきっかけとなった。

日本はかつて「企業戦士」「モーレツ社員」という言葉に象徴されるように、長時間労働が美徳とされる社会だった。残業は当たり前で、有給休暇の取得率も先進国の中で最低水準だった。その結果、「過労死」という言葉が英語でも「Karoshi」としてそのまま使われるほど、深刻な社会問題となった。

こうした状況を改善するため、政府は2019年に「働き方改革関連法」を施行した。残業時間の上限規制や、年5日の有給休暇取得の義務化などが盛り込まれた。また、新型コロナウイルスの流行をきっかけに、テレワークが急速に普及し、働く場所や時間の柔軟性が高まった。

しかし、制度が整っても、実際の運用はまだ十分とは言えない。「空気を読む」文化の中で、周囲が残業しているのに自分だけ帰るのは気が引けるという声も根強い。育児や介護のための休暇を取りにくいという問題も依然として存在する。

真のワークライフバランスを実現するには、制度の整備だけでなく、社会全体の意識改革が必要だ。「休むことは悪いことではない」「効率よく働くことこそが大切だ」という価値観が、もっと広まることが期待される。',
  'essay',
  'N2',
  250,
  'ワークライフバランス',
  '[{"word":"調和","reading":"ちょうわ","meaning_ko":"조화"},{"word":"美徳","reading":"びとく","meaning_ko":"미덕"},{"word":"過労死","reading":"かろうし","meaning_ko":"과로사"},{"word":"施行","reading":"しこう","meaning_ko":"시행"},{"word":"柔軟性","reading":"じゅうなんせい","meaning_ko":"유연성"},{"word":"意識改革","reading":"いしきかいかく","meaning_ko":"의식 개혁"}]'::jsonb,
  ARRAY['〜て久しい', '〜とは言えない', '〜をきっかけに', '〜ことこそが'],
  '"워크라이프 밸런스"라는 말이 일본에서 널리 알려지게 된 지 오래다. 일과 사생활의 조화를 의미하는 이 개념은 과거 일본의 근무 방식을 크게 재검토하는 계기가 되었다.

일본은 과거 "기업 전사", "맹렬 사원"이라는 말로 상징되듯이 장시간 노동이 미덕으로 여겨지는 사회였다. 야근은 당연했고, 유급휴가 사용률도 선진국 중 최저 수준이었다. 그 결과 "과로사"라는 말이 영어에서도 "Karoshi"로 그대로 사용될 만큼 심각한 사회 문제가 되었다.

이러한 상황을 개선하기 위해 정부는 2019년에 "근무 방식 개혁 관련법"을 시행했다. 잔업 시간 상한 규제와 연간 5일 유급휴가 사용 의무화 등이 포함되었다. 또한 코로나바이러스 유행을 계기로 재택근무가 급속히 보급되어 일하는 장소와 시간의 유연성이 높아졌다.

그러나 제도가 갖춰져도 실제 운용은 아직 충분하다고 말하기 어렵다. "눈치를 보는" 문화 속에서 주위가 야근하고 있는데 자기만 퇴근하는 것은 꺼려진다는 목소리도 뿌리 깊다. 육아나 돌봄을 위한 휴가를 쓰기 어렵다는 문제도 여전히 존재한다.

진정한 워크라이프 밸런스를 실현하려면 제도 정비뿐만 아니라 사회 전체의 의식 개혁이 필요하다. "쉬는 것은 나쁜 것이 아니다", "효율적으로 일하는 것이야말로 중요하다"라는 가치관이 더 확산되는 것이 기대된다.',
  34
);

-- N2-8: 地方移住のトレンド (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '地方移住のトレンド',
  '近年、東京をはじめとする大都市から地方へ移住する人が増えている。内閣府の調査によると、東京圏在住者の約3割が地方移住に関心を持っており、特に20代〜30代の若い世代で関心が高い。

移住の動機はさまざまだ。自然に囲まれた環境で子育てをしたい、通勤ラッシュから解放されたい、地域のコミュニティに貢献したいなど、人生の質を重視する価値観の変化がうかがえる。また、コロナ禍でテレワークが定着したことで、都市部で働きながら地方に住むという選択肢が現実的になったことも大きな要因である。

受け入れ側の自治体も、移住支援に力を入れている。住宅取得への補助金、子育て支援の充実、空き家の活用支援など、多様な施策が展開されている。また、いきなり移住するのではなく、まずは短期間の「お試し移住」を体験できる制度を設けている自治体もあり、移住へのハードルを下げる工夫がなされている。

一方で、課題も少なくない。地方では都市部と比べて仕事の選択肢が限られるため、移住後の収入減を懸念する声が多い。また、地域の人間関係の密度に戸惑う移住者や、期待していた田舎暮らしの現実とのギャップに悩むケースも報告されている。

移住を成功させるには、事前の情報収集と現地の人々との交流が鍵となる。理想だけでなく現実も見据えた上で、自分に合った地域を見つけることが大切である。',
  'article',
  'N2',
  245,
  '地方移住',
  '[{"word":"動機","reading":"どうき","meaning_ko":"동기"},{"word":"価値観","reading":"かちかん","meaning_ko":"가치관"},{"word":"施策","reading":"しさく","meaning_ko":"시책"},{"word":"空き家","reading":"あきや","meaning_ko":"빈집"},{"word":"戸惑う","reading":"とまどう","meaning_ko":"당황하다"},{"word":"見据える","reading":"みすえる","meaning_ko":"내다보다"}]'::jsonb,
  ARRAY['〜をはじめとする', '〜ことも大きな要因', '〜上で', '〜ケースも報告されている'],
  '최근 도쿄를 비롯한 대도시에서 지방으로 이주하는 사람이 늘고 있다. 내각부 조사에 따르면 도쿄권 거주자의 약 3할이 지방 이주에 관심을 가지고 있으며, 특히 20대~30대 젊은 세대에서 관심이 높다.

이주 동기는 다양하다. 자연에 둘러싸인 환경에서 육아를 하고 싶다, 출퇴근 러시에서 해방되고 싶다, 지역 커뮤니티에 공헌하고 싶다 등 삶의 질을 중시하는 가치관 변화가 엿보인다. 또한 코로나 사태로 재택근무가 정착되면서 도시에서 일하면서 지방에 사는 선택지가 현실적이 된 것도 큰 요인이다.

받아들이는 측 지자체도 이주 지원에 힘을 쏟고 있다. 주택 취득 보조금, 육아 지원 충실화, 빈집 활용 지원 등 다양한 시책이 전개되고 있다. 또한 갑자기 이주하는 것이 아니라 먼저 단기간 "체험 이주"를 경험할 수 있는 제도를 마련한 지자체도 있어 이주의 문턱을 낮추는 방안이 마련되고 있다.

한편 과제도 적지 않다. 지방은 도시 지역에 비해 일자리 선택지가 제한되기 때문에 이주 후 수입 감소를 우려하는 목소리가 많다. 또한 지역 인간관계의 밀도에 당황하는 이주자나, 기대했던 시골 생활의 현실과의 괴리에 고민하는 경우도 보고되고 있다.

이주를 성공시키려면 사전 정보 수집과 현지 사람들과의 교류가 열쇠가 된다. 이상뿐만 아니라 현실도 내다보면서 자신에게 맞는 지역을 찾는 것이 중요하다.',
  35
);

-- N2-9: SNSとコミュニケーション (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'SNSとコミュニケーション',
  'SNS（ソーシャル・ネットワーキング・サービス）の普及は、私たちのコミュニケーションのあり方を根本的に変えた。総務省の調査によると、日本のSNS利用率は約80%に達しており、特にLINEは生活インフラの一つと言えるほど浸透している。

SNSの利点は数多い。遠く離れた家族や友人とも手軽に連絡が取れるようになり、同じ趣味を持つ人とのつながりも簡単に作れるようになった。災害時の安否確認や情報共有にも大きな力を発揮する。また、個人が情報を発信する手段としても広く活用されている。

しかし、SNSがもたらす問題も無視できない。匿名性を利用した誹謗中傷は深刻な社会問題となっており、精神的な被害を受ける人が後を絶たない。特に若年層への影響は大きく、SNS上でのいじめや、「いいね」の数に自己価値を依存してしまう問題なども指摘されている。

また、SNS上の情報は必ずしも正確ではなく、フェイクニュースが拡散されるリスクも高い。情報の真偽を見極めるメディアリテラシーの重要性がかつてないほど高まっている。

さらに、対面でのコミュニケーション能力の低下を懸念する声もある。文字だけのやり取りでは表情や声のトーンが伝わらず、誤解が生じやすいという問題もある。

SNSは便利なツールであるが、それに振り回されるのではなく、上手に付き合っていくことが現代社会を生きる上で不可欠なスキルとなっている。',
  'essay',
  'N2',
  250,
  'SNSとコミュニケーション',
  '[{"word":"浸透","reading":"しんとう","meaning_ko":"침투, 보급"},{"word":"安否確認","reading":"あんぴかくにん","meaning_ko":"안부 확인"},{"word":"誹謗中傷","reading":"ひぼうちゅうしょう","meaning_ko":"비방 중상"},{"word":"匿名性","reading":"とくめいせい","meaning_ko":"익명성"},{"word":"真偽","reading":"しんぎ","meaning_ko":"진위"},{"word":"振り回される","reading":"ふりまわされる","meaning_ko":"휘둘리다"}]'::jsonb,
  ARRAY['〜と言えるほど', '〜を絶たない', '〜のではなく', '〜上で不可欠な'],
  'SNS(소셜 네트워킹 서비스)의 보급은 우리의 커뮤니케이션 방식을 근본적으로 바꾸었다. 총무성 조사에 따르면 일본의 SNS 이용률은 약 80%에 달하며, 특히 LINE은 생활 인프라의 하나라고 말할 수 있을 만큼 침투해 있다.

SNS의 장점은 많다. 멀리 떨어진 가족이나 친구와도 쉽게 연락할 수 있게 되었고, 같은 취미를 가진 사람과의 유대도 쉽게 만들 수 있게 되었다. 재해 시 안부 확인이나 정보 공유에도 큰 힘을 발휘한다. 또한 개인이 정보를 발신하는 수단으로도 널리 활용되고 있다.

그러나 SNS가 가져오는 문제도 무시할 수 없다. 익명성을 이용한 비방 중상은 심각한 사회 문제가 되고 있으며 정신적 피해를 입는 사람이 끊이지 않는다. 특히 젊은 층에 대한 영향이 크며, SNS상의 왕따나 "좋아요" 수에 자기 가치를 의존하는 문제 등도 지적되고 있다.

또한 SNS상의 정보는 반드시 정확하지 않으며 가짜 뉴스가 확산되는 위험도 높다. 정보의 진위를 가려내는 미디어 리터러시의 중요성이 그 어느 때보다 높아지고 있다.

더 나아가 대면 커뮤니케이션 능력 저하를 우려하는 목소리도 있다. 글자만으로의 소통에서는 표정이나 목소리 톤이 전달되지 않아 오해가 생기기 쉽다는 문제도 있다.

SNS는 편리한 도구이지만, 그것에 휘둘리는 것이 아니라 잘 활용해 나가는 것이 현대 사회를 살아가는 데 불가결한 스킬이 되고 있다.',
  36
);


