-- N1-1: 日本語の敬語体系の変遷 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語の敬語体系の変遷',
  '日本語の敬語は、世界の言語の中でも極めて精緻な体系を持つことで知られている。しかし、その体系は時代とともに変化を遂げてきた。

伝統的に、日本語の敬語は「尊敬語」「謙譲語」「丁寧語」の三分類で整理されてきた。ところが、2007年に文化審議会が発表した「敬語の指針」では、これが五分類に再編された。具体的には、従来の謙譲語が「謙譲語I（相手を立てる）」と「謙譲語II（丁重語）」に分けられ、また「丁寧語」から「美化語」が独立した形となった。

こうした分類の変更は、現代社会における敬語使用の実態をより正確に反映するためのものであった。たとえば、「お料理」「お花」などの美化語は、必ずしも相手への敬意を表すものではなく、話者自身の品位を示す機能を持つ。これを丁寧語と同一に扱うのは不適切だという認識が広まったのである。

一方、現代の日本社会では敬語の「簡略化」が進んでいるとも指摘される。かつては厳格に区別されていた尊敬語と謙譲語の混同が見られるようになり、いわゆる「マニュアル敬語」や「バイト敬語」と呼ばれる不自然な表現も広まっている。「ご注文は以上でよろしかったでしょうか」「千円からお預かりします」といった表現は、文法的には誤りとされるが、日常的に耳にするようになった。

敬語の変化をどう捉えるかについては、意見が分かれる。言語学的に見れば、言葉は常に変化するものであり、それ自体は自然な現象である。しかし、敬語が日本の社会的な人間関係を円滑にする重要な機能を担っていることを考えると、その本質的な部分は失われるべきではないという主張にも一理ある。

今後、グローバル化が進む中で日本語の敬語がどのように変容していくのか、注目に値する問題である。',
  'essay',
  'N1',
  310,
  '敬語体系の変遷',
  '[{"word":"精緻","reading":"せいち","meaning_ko":"정치, 정교"},{"word":"変遷","reading":"へんせん","meaning_ko":"변천"},{"word":"再編","reading":"さいへん","meaning_ko":"재편"},{"word":"品位","reading":"ひんい","meaning_ko":"품위"},{"word":"簡略化","reading":"かんりゃくか","meaning_ko":"간략화"},{"word":"円滑","reading":"えんかつ","meaning_ko":"원활"}]'::jsonb,
  ARRAY['〜ことで知られている', '〜とも指摘される', '〜べきではない', '〜に値する'],
  '일본어의 경어는 세계 언어 중에서도 극히 정교한 체계를 갖추고 있는 것으로 알려져 있다. 그러나 그 체계는 시대와 함께 변화를 이루어 왔다.

전통적으로 일본어의 경어는 "존경어", "겸양어", "정중어"의 세 가지 분류로 정리되어 왔다. 그런데 2007년에 문화심의회가 발표한 "경어의 지침"에서는 이것이 다섯 가지로 재편되었다. 구체적으로는 기존의 겸양어가 "겸양어I(상대를 높이는)" 과 "겸양어II(정중어)"로 나뉘었고, 또한 "정중어"에서 "미화어"가 독립된 형태가 되었다.

이러한 분류 변경은 현대 사회에서의 경어 사용 실태를 보다 정확하게 반영하기 위한 것이었다. 예를 들어 "오요리(요리)", "오하나(꽃)" 등의 미화어는 반드시 상대에 대한 경의를 나타내는 것이 아니라 화자 자신의 품위를 보여주는 기능을 가진다. 이를 정중어와 동일하게 다루는 것은 부적절하다는 인식이 확산된 것이다.

한편 현대 일본 사회에서는 경어의 "간략화"가 진행되고 있다고도 지적된다. 과거에는 엄격하게 구별되었던 존경어와 겸양어의 혼동이 나타나게 되었고, 이른바 "매뉴얼 경어"나 "아르바이트 경어"로 불리는 부자연스러운 표현도 확산되고 있다. "주문은 이상으로 괜찮으셨습니까?", "천 엔에서 받겠습니다" 등의 표현은 문법적으로는 오류로 여겨지지만 일상적으로 듣게 되었다.

경어의 변화를 어떻게 받아들일 것인가에 대해서는 의견이 나뉜다. 언어학적으로 보면 말은 항상 변화하는 것이며 그 자체는 자연스러운 현상이다. 그러나 경어가 일본의 사회적 인간관계를 원활하게 하는 중요한 기능을 담당하고 있음을 고려하면, 그 본질적인 부분은 잃어서는 안 된다는 주장에도 일리가 있다.

앞으로 글로벌화가 진행되는 가운데 일본어의 경어가 어떻게 변용되어 갈 것인지 주목할 만한 문제이다.',
  37
);

-- N1-2: 多文化共生社会の課題 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '多文化共生社会の課題',
  '日本における外国人住民の増加に伴い、「多文化共生」という理念が政策の柱の一つとして位置づけられるようになった。総務省は多文化共生を「国籍や民族などの異なる人々が、互いの文化的違いを認め合い、対等な関係を築こうとしながら、地域社会の構成員として共に生きていくこと」と定義している。

しかし、理念と現実の間には依然として大きな隔たりがある。外国人住民が直面する課題は多岐にわたる。言語の壁は最も根本的な障壁であり、行政サービスへのアクセス、医療機関での意思疎通、子どもの教育など、生活のあらゆる場面で困難を引き起こしている。

特に教育の分野では、日本語指導が必要な児童生徒が約5万8千人に上り、そのうち約1割が必要な指導を受けられていないという実態がある。日本語能力が不十分なまま通常の授業に参加せざるを得ない子どもたちは、学力の遅れだけでなく、アイデンティティの揺らぎという問題にも直面する。母語も日本語も中途半端になる「ダブルリミテッド」の状態に陥るケースも報告されている。

また、外国人に対する偏見や差別も根深い問題である。住居の賃貸を断られる、就職面接で不利な扱いを受けるといった事例は珍しくない。2016年に施行されたヘイトスピーチ対策法は一定の成果を上げたものの、オンライン上での差別的な言説は依然として後を絶たない。

多文化共生社会の実現に向けては、制度的な支援の充実とともに、マジョリティ側の意識変革が不可欠である。異文化を「特殊なもの」として捉えるのではなく、社会を豊かにする源泉として積極的に受け入れる姿勢が求められている。それは、均質性を重視してきた日本社会のあり方そのものを問い直す作業でもある。',
  'essay',
  'N1',
  330,
  '多文化共生社会',
  '[{"word":"隔たり","reading":"へだたり","meaning_ko":"격차, 간극"},{"word":"多岐にわたる","reading":"たきにわたる","meaning_ko":"다방면에 걸치다"},{"word":"意思疎通","reading":"いしそつう","meaning_ko":"의사소통"},{"word":"偏見","reading":"へんけん","meaning_ko":"편견"},{"word":"均質性","reading":"きんしつせい","meaning_ko":"균질성"},{"word":"源泉","reading":"げんせん","meaning_ko":"원천"}]'::jsonb,
  ARRAY['〜に伴い', '〜ざるを得ない', '〜ものの', '〜のではなく'],
  '일본의 외국인 주민 증가에 따라 "다문화 공생"이라는 이념이 정책의 기둥 중 하나로 자리잡게 되었다. 총무성은 다문화 공생을 "국적이나 민족 등이 다른 사람들이 서로의 문화적 차이를 인정하고 대등한 관계를 구축하면서 지역 사회의 구성원으로서 함께 살아가는 것"이라고 정의하고 있다.

그러나 이념과 현실 사이에는 여전히 큰 간극이 있다. 외국인 주민이 직면하는 과제는 다방면에 걸친다. 언어 장벽은 가장 근본적인 장애이며, 행정 서비스 접근, 의료기관에서의 의사소통, 자녀 교육 등 생활의 모든 장면에서 어려움을 초래하고 있다.

특히 교육 분야에서는 일본어 지도가 필요한 아동·학생이 약 5만 8천 명에 달하며, 그 중 약 1할이 필요한 지도를 받지 못하고 있다는 실태가 있다. 일본어 능력이 불충분한 채로 정상 수업에 참가할 수밖에 없는 아이들은 학력 저하뿐만 아니라 정체성의 흔들림이라는 문제에도 직면한다. 모국어도 일본어도 중간 수준에 머무는 "더블 리미티드" 상태에 빠지는 경우도 보고되고 있다.

또한 외국인에 대한 편견과 차별도 뿌리 깊은 문제이다. 주거 임대를 거절당하거나, 취업 면접에서 불리한 대우를 받는 사례는 드물지 않다. 2016년에 시행된 혐오 발언 대책법은 일정한 성과를 거두었지만 온라인상에서의 차별적 발언은 여전히 끊이지 않는다.

다문화 공생 사회 실현을 위해서는 제도적 지원의 충실과 함께 다수자 측의 의식 변혁이 불가결하다. 이문화를 "특수한 것"으로 받아들이는 것이 아니라 사회를 풍요롭게 하는 원천으로서 적극적으로 수용하는 자세가 요구되고 있다. 그것은 균질성을 중시해 온 일본 사회의 존재 방식 그 자체를 재고하는 작업이기도 하다.',
  38
);

-- N1-3: 日本の消費行動の変化 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の消費行動の変化',
  'バブル経済崩壊以降、日本人の消費行動は大きく変容してきた。かつてのような「モノ消費」、すなわちブランド品や高級車を所有することにステータスを見出す傾向は薄れ、代わりに「コト消費」と呼ばれる体験型の消費が台頭している。

この変化の背景には、複数の要因がある。まず、長期にわたるデフレーションと所得の伸び悩みにより、消費者の価格意識が高まったことが挙げられる。100円ショップやファストファッションの隆盛は、その象徴と言えよう。一方で、単に安いだけでなく、品質と価格のバランスを重視する「賢い消費」も定着している。

また、ミニマリズムやシンプルライフといった価値観の浸透も見逃せない。断捨離ブームに代表されるように、物を持たないことに価値を見出す層が拡大している。シェアリングエコノミーの普及もこの文脈で理解できる。カーシェアリングやフリマアプリの利用者数の増加は、所有から利用へという消費パラダイムの転換を如実に物語っている。

さらに近年では、「イミ消費」という新たな概念も注目されている。これは、商品やサービスの社会的意義に共感して消費する行動を指す。環境に配慮した製品を選ぶ、地域の生産者を応援するために地元の商品を購入するなど、消費を通じて社会課題の解決に参加しようとする意識の表れである。

こうした消費行動の変化は、企業のマーケティング戦略にも大きな影響を与えている。商品の機能や価格だけでなく、その背後にあるストーリーや価値観を消費者に伝えることの重要性が、ますます高まっているのである。',
  'article',
  'N1',
  310,
  '消費行動の変化',
  '[{"word":"台頭","reading":"たいとう","meaning_ko":"대두"},{"word":"隆盛","reading":"りゅうせい","meaning_ko":"융성"},{"word":"浸透","reading":"しんとう","meaning_ko":"침투, 보급"},{"word":"如実に","reading":"にょじつに","meaning_ko":"여실히"},{"word":"共感","reading":"きょうかん","meaning_ko":"공감"},{"word":"戦略","reading":"せんりゃく","meaning_ko":"전략"}]'::jsonb,
  ARRAY['〜と言えよう', '〜も見逃せない', '〜を物語っている', '〜の表れである'],
  '버블 경제 붕괴 이후 일본인의 소비 행동은 크게 변용해 왔다. 과거와 같은 "물건 소비", 즉 브랜드품이나 고급차를 소유하는 것에 지위를 발견하는 경향은 옅어지고, 대신 "경험 소비"라 불리는 체험형 소비가 대두하고 있다.

이 변화의 배경에는 복수의 요인이 있다. 먼저 장기적인 디플레이션과 소득 정체로 인해 소비자의 가격 의식이 높아진 점을 들 수 있다. 100엔숍이나 패스트 패션의 융성은 그 상징이라 할 수 있을 것이다. 한편 단순히 싸기만 한 것이 아니라 품질과 가격의 균형을 중시하는 "현명한 소비"도 정착하고 있다.

또한 미니멀리즘이나 심플 라이프라는 가치관의 침투도 간과할 수 없다. 정리정돈 붐으로 대표되듯이 물건을 갖지 않는 것에 가치를 발견하는 층이 확대되고 있다. 공유 경제의 보급도 이 맥락에서 이해할 수 있다. 카셰어링이나 중고거래 앱 이용자 수의 증가는 소유에서 이용으로라는 소비 패러다임의 전환을 여실히 말해주고 있다.

나아가 최근에는 "의미 소비"라는 새로운 개념도 주목받고 있다. 이는 상품이나 서비스의 사회적 의의에 공감하여 소비하는 행동을 가리킨다. 환경에 배려한 제품을 고르거나 지역 생산자를 응원하기 위해 지역 상품을 구매하는 등 소비를 통해 사회 과제 해결에 참여하려는 의식의 표현이다.

이러한 소비 행동의 변화는 기업의 마케팅 전략에도 큰 영향을 주고 있다. 상품의 기능이나 가격뿐만 아니라 그 배후에 있는 스토리와 가치관을 소비자에게 전달하는 것의 중요성이 점점 더 높아지고 있는 것이다.',
  39
);

-- N1-4: 地域コミュニティの衰退と再生 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '地域コミュニティの衰退と再生',
  'かつて日本の地域社会を支えてきた「向こう三軒両隣」の精神は、都市化と核家族化の進行とともに急速に希薄化した。町内会への加入率は全国平均で50%を下回り、自治会の役員のなり手不足は深刻な問題となっている。

地域コミュニティ衰退の背景には、生活様式の変化がある。共働き世帯の増加により、平日の地域活動に参加することが困難になった。また、プライバシー意識の高まりから、近隣との付き合いを煩わしいと感じる人も少なくない。マンションのオートロック化に象徴されるように、物理的にも心理的にも、人と人との間に壁が築かれてきたのである。

しかし、東日本大震災をはじめとする度重なる自然災害は、地域のつながりの重要性を改めて浮き彫りにした。災害時に最も頼りになるのは、日頃から顔の見える関係を築いている隣人たちだということが、多くの被災地の経験から明らかになった。いわゆる「共助」の力は、行政の「公助」だけでは補いきれない部分を担う不可欠な存在なのである。

こうした認識のもと、新しい形のコミュニティが各地で生まれている。子ども食堂は、子どもの居場所づくりと地域交流の拠点として急速に広がり、全国で9千か所以上に達した。コミュニティカフェや地域の縁側といった、誰もが気軽に立ち寄れるサードプレイスも注目を集めている。

重要なのは、かつてのような義務的な近所付き合いを復活させることではなく、緩やかでありながらも信頼に基づいたつながりを新たに構築することであろう。それぞれの生活スタイルを尊重しつつ、必要な時に助け合える関係性こそが、現代の地域コミュニティに求められているものではないだろうか。',
  'essay',
  'N1',
  340,
  '地域コミュニティ',
  '[{"word":"希薄化","reading":"きはくか","meaning_ko":"희박화"},{"word":"煩わしい","reading":"わずらわしい","meaning_ko":"번거로운"},{"word":"浮き彫り","reading":"うきぼり","meaning_ko":"부각"},{"word":"共助","reading":"きょうじょ","meaning_ko":"공조, 상호 도움"},{"word":"拠点","reading":"きょてん","meaning_ko":"거점"},{"word":"構築","reading":"こうちく","meaning_ko":"구축"}]'::jsonb,
  ARRAY['〜とともに', '〜ことではなく〜ことであろう', '〜こそが', '〜のではないだろうか'],
  '한때 일본의 지역 사회를 지탱해 온 "이웃사촌" 정신은 도시화와 핵가족화의 진행과 함께 급속히 희박해졌다. 마을회 가입률은 전국 평균 50%를 밑돌고, 자치회 임원의 후임자 부족은 심각한 문제가 되고 있다.

지역 커뮤니티 쇠퇴의 배경에는 생활 양식의 변화가 있다. 맞벌이 세대 증가로 인해 평일의 지역 활동에 참가하기가 어려워졌다. 또한 사생활 의식의 고양으로 이웃과의 교류를 번거롭다고 느끼는 사람도 적지 않다. 아파트의 자동잠금 시스템에 상징되듯이 물리적으로도 심리적으로도 사람과 사람 사이에 벽이 세워져 온 것이다.

그러나 동일본 대지진을 비롯한 잇따른 자연재해는 지역 유대의 중요성을 다시금 부각시켰다. 재해 시 가장 의지가 되는 것은 평소부터 얼굴을 아는 관계를 구축하고 있는 이웃들이라는 것이 많은 피해 지역의 경험에서 분명해졌다. 이른바 "공조"의 힘은 행정의 "공적 지원"만으로는 보완할 수 없는 부분을 담당하는 불가결한 존재인 것이다.

이러한 인식 아래 새로운 형태의 커뮤니티가 각지에서 탄생하고 있다. 어린이 식당은 아이들의 거처 만들기와 지역 교류의 거점으로서 급속히 퍼져 전국에서 9천 곳 이상에 달했다. 커뮤니티 카페나 지역 마루와 같은 누구나 부담 없이 들를 수 있는 제3의 장소도 주목받고 있다.

중요한 것은 과거와 같은 의무적인 이웃 교류를 부활시키는 것이 아니라, 느슨하면서도 신뢰에 기반한 유대를 새롭게 구축하는 것이리라. 각자의 생활 스타일을 존중하면서 필요한 때에 서로 도울 수 있는 관계야말로 현대의 지역 커뮤니티에 요구되는 것이 아닐까.',
  40
);

-- N1-5: 日本の四季と文学 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の四季と文学',
  '日本文学において、四季の描写は単なる背景ではなく、作品の根幹をなす要素として機能してきた。万葉集の時代から現代に至るまで、日本の作家たちは季節の移ろいに人間の感情を重ね合わせ、独自の美意識を育んできたのである。

俳句における「季語」は、この伝統の最も凝縮された形と言える。わずか十七音の中に季節の本質を封じ込める季語は、単なる時期の指標ではなく、その季節に付随する感情や文化的記憶の総体を喚起する装置として機能する。松尾芭蕉の「古池や蛙飛び込む水の音」における「蛙」は春の季語であり、冬の静寂が破られる瞬間の生命の躍動を表現している。

清少納言の『枕草子』は、「春はあけぼの」という有名な冒頭に始まり、各季節の最も美しい時間帯を繊細に描き出した。ここに見られるのは、自然のありのままの美しさを愛でるのではなく、その中から最も洗練された瞬間を切り取る、日本独自の審美眼である。

近代文学においても、四季は重要なモチーフであり続けた。川端康成の『雪国』冒頭の「国境の長いトンネルを抜けると雪国であった」という一文は、冬の白い世界への突然の転換を通じて、日常から非日常への移行を鮮やかに描いている。

しかし、気候変動により日本の四季そのものが変容しつつある現在、文学における季節の描写にも変化が見られる。桜の開花時期の早まりや、猛暑日の増加、秋の短縮化といった現象は、従来の季語体系との齟齬を生じさせている。四季と文学の関係は、新たな局面を迎えていると言えるだろう。',
  'essay',
  'N1',
  320,
  '四季と文学',
  '[{"word":"根幹","reading":"こんかん","meaning_ko":"근간"},{"word":"凝縮","reading":"ぎょうしゅく","meaning_ko":"응축"},{"word":"喚起","reading":"かんき","meaning_ko":"환기"},{"word":"審美眼","reading":"しんびがん","meaning_ko":"심미안"},{"word":"齟齬","reading":"そご","meaning_ko":"어긋남, 불일치"},{"word":"局面","reading":"きょくめん","meaning_ko":"국면"}]'::jsonb,
  ARRAY['〜をなす', '〜と言える', '〜つつある', '〜を通じて'],
  '일본 문학에서 사계절의 묘사는 단순한 배경이 아니라 작품의 근간을 이루는 요소로서 기능해 왔다. 만요슈 시대부터 현대에 이르기까지 일본의 작가들은 계절의 변화에 인간의 감정을 겹쳐놓으며 독자적인 미의식을 키워 온 것이다.

하이쿠에서의 "기고(계절어)"는 이 전통의 가장 응축된 형태라 할 수 있다. 불과 17음 안에 계절의 본질을 담아내는 기고는 단순한 시기의 지표가 아니라 그 계절에 부수되는 감정이나 문화적 기억의 총체를 환기하는 장치로서 기능한다. 마쓰오 바쇼의 "후루이케야 가와즈 토비코무 미즈노 오토(오래된 연못이여 개구리 뛰어드는 물소리)"에서 "개구리"는 봄의 기고이며, 겨울의 정적이 깨지는 순간의 생명의 약동을 표현하고 있다.

세이쇼나곤의 "마쿠라노소시(베개풀)"는 "봄은 새벽"이라는 유명한 도입부에서 시작하여 각 계절의 가장 아름다운 시간대를 섬세하게 그려냈다. 여기에서 볼 수 있는 것은 자연의 있는 그대로의 아름다움을 사랑하는 것이 아니라 그 속에서 가장 세련된 순간을 포착하는 일본 특유의 심미안이다.

근대 문학에서도 사계절은 중요한 모티프이기를 계속했다. 가와바타 야스나리의 "유키구니(설국)" 도입부의 "국경의 긴 터널을 빠져나오니 설국이었다"라는 한 문장은 겨울의 하얀 세계로의 갑작스러운 전환을 통해 일상에서 비일상으로의 이행을 선명하게 그리고 있다.

그러나 기후변동으로 일본의 사계절 자체가 변용하고 있는 현재, 문학에서의 계절 묘사에도 변화가 보인다. 벚꽃 개화 시기의 앞당겨짐이나 폭염일의 증가, 가을의 단축화 같은 현상은 기존의 기고 체계와의 불일치를 야기하고 있다. 사계절과 문학의 관계는 새로운 국면을 맞이하고 있다고 말할 수 있을 것이다.',
  41
);

-- N1-6: 高齢社会における介護問題 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '高齢社会における介護問題',
  '超高齢社会を迎えた日本において、介護問題は国家的な課題となっている。2025年には、いわゆる「団塊の世代」が全員75歳以上となる「2025年問題」を迎え、要介護者の急増が見込まれている。

日本の介護保険制度は2000年に創設され、40歳以上の国民が保険料を納め、必要になった時に介護サービスを受けられる仕組みとなっている。在宅介護と施設介護の両方を支援する包括的な制度として評価されてきたが、制度開始から20年以上が経ち、さまざまな問題が顕在化している。

最も深刻なのは、介護人材の不足である。介護職の離職率は高く、その背景には低賃金と過酷な労働環境がある。全産業平均と比較して月額約6万円低い給与水準は、若い世代がこの業界を敬遠する一因となっている。政府は処遇改善加算などの対策を講じているが、抜本的な解決には至っていない。

もう一つの重大な問題は、「介護離職」である。親の介護のために仕事を辞めざるを得ない人は年間約10万人に上る。介護離職は、当事者の経済的困窮を招くだけでなく、企業にとっても熟練した人材の流出という損失をもたらす。

さらに、「老老介護」と「認認介護」の問題も深刻化している。前者は65歳以上の高齢者が同じく高齢の配偶者や親を介護する状態を指し、後者は認知症の人が認知症の人を介護するケースである。共に介護者自身の健康悪化や孤立のリスクが高く、悲惨な事件につながるケースも報告されている。

介護問題の解決には、テクノロジーの活用、地域包括ケアシステムの強化、そして何より介護に対する社会全体の意識改革が求められる。介護を個人や家族の問題として抱え込むのではなく、社会全体で支える仕組みの構築が急務である。',
  'essay',
  'N1',
  340,
  '介護問題',
  '[{"word":"顕在化","reading":"けんざいか","meaning_ko":"현재화, 표면화"},{"word":"離職率","reading":"りしょくりつ","meaning_ko":"이직률"},{"word":"敬遠","reading":"けいえん","meaning_ko":"기피"},{"word":"抜本的","reading":"ばっぽんてき","meaning_ko":"근본적"},{"word":"困窮","reading":"こんきゅう","meaning_ko":"곤궁"},{"word":"急務","reading":"きゅうむ","meaning_ko":"급선무"}]'::jsonb,
  ARRAY['〜に至っていない', '〜ざるを得ない', '〜をもたらす', '〜のではなく'],
  '초고령 사회를 맞이한 일본에서 돌봄 문제는 국가적 과제가 되고 있다. 2025년에는 이른바 "베이비붐 세대"가 전원 75세 이상이 되는 "2025년 문제"를 맞이하여 요돌봄자의 급증이 예상되고 있다.

일본의 돌봄보험 제도는 2000년에 창설되어 40세 이상의 국민이 보험료를 납부하고 필요시 돌봄 서비스를 받을 수 있는 구조로 되어 있다. 재택 돌봄과 시설 돌봄 양쪽을 지원하는 포괄적 제도로 평가받아 왔지만, 제도 시행 후 20년 이상이 지나 여러 문제가 표면화되고 있다.

가장 심각한 것은 돌봄 인력 부족이다. 돌봄직의 이직률은 높으며 그 배경에는 낮은 임금과 가혹한 노동 환경이 있다. 전 산업 평균과 비교하여 월액 약 6만 엔 낮은 급여 수준은 젊은 세대가 이 업계를 기피하는 한 요인이 되고 있다. 정부는 처우 개선 가산 등의 대책을 강구하고 있지만 근본적 해결에는 이르지 못하고 있다.

또 하나의 중대한 문제는 "돌봄 이직"이다. 부모의 돌봄을 위해 직장을 그만둘 수밖에 없는 사람이 연간 약 10만 명에 이른다. 돌봄 이직은 당사자의 경제적 곤궁을 초래할 뿐만 아니라 기업에도 숙련된 인재 유출이라는 손실을 가져온다.

나아가 "노노돌봄"과 "인인돌봄" 문제도 심각해지고 있다. 전자는 65세 이상의 고령자가 마찬가지로 고령인 배우자나 부모를 돌보는 상태를 가리키며, 후자는 치매 환자가 치매 환자를 돌보는 경우이다. 모두 돌봄 제공자 자신의 건강 악화와 고립 위험이 높으며 비참한 사건으로 이어지는 경우도 보고되고 있다.

돌봄 문제의 해결에는 기술 활용, 지역포괄 케어 시스템 강화, 그리고 무엇보다 돌봄에 대한 사회 전체의 의식 개혁이 요구된다. 돌봄을 개인이나 가족의 문제로 안고 있는 것이 아니라 사회 전체에서 지탱하는 구조의 구축이 급선무이다.',
  42
);

-- N1-7: 教育格差と機会の平等 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '教育格差と機会の平等',
  '教育の機会均等は、民主主義社会の根幹をなす理念の一つである。日本国憲法第26条は、全ての国民に等しく教育を受ける権利を保障している。しかし、現実にはさまざまな要因によって教育格差が生じており、その是正は日本社会の重要な課題となっている。

教育格差の最大の要因は、家庭の経済力である。文部科学省の調査によると、世帯年収が高い家庭ほど子どもの大学進学率が高いという相関関係が明確に示されている。年収400万円未満の家庭の大学進学率が約30%であるのに対し、年収1000万円以上の家庭では約60%に達する。この差は、塾や予備校の費用、大学の学費など、教育にかかる経済的負担の大きさを反映している。

地域間格差も看過できない問題だ。都市部には多様な教育機関や文化施設が集中しているのに対し、地方では選択肢が限られる。過疎地域では学校の統廃合が進み、通学に長時間を要する児童生徒も少なくない。オンライン教育の普及は地域格差の解消に一定の役割を果たしているが、インフラ整備の遅れやデジタル格差という新たな問題も浮上している。

また、外国にルーツを持つ子どもたちの教育格差も深刻である。日本語能力の不足により学業についていけない子どもや、高校進学を断念する子どもも存在する。彼らの多くは不安定な雇用に就くことになり、貧困の連鎖に陥るリスクが高い。

教育格差を解消するためには、奨学金制度の拡充、無償教育の範囲拡大、地域間の教育資源の再配分など、制度的な取り組みが不可欠である。しかしそれ以上に重要なのは、教育を受ける機会が生まれた環境によって左右されてはならないという、社会全体の強い意志であろう。全ての子どもが等しく可能性を開花させられる社会の実現は、次世代への責務にほかならない。',
  'essay',
  'N1',
  340,
  '教育格差',
  '[{"word":"機会均等","reading":"きかいきんとう","meaning_ko":"기회 균등"},{"word":"是正","reading":"ぜせい","meaning_ko":"시정"},{"word":"相関関係","reading":"そうかんかんけい","meaning_ko":"상관관계"},{"word":"看過","reading":"かんか","meaning_ko":"간과"},{"word":"統廃合","reading":"とうはいごう","meaning_ko":"통폐합"},{"word":"責務","reading":"せきむ","meaning_ko":"책무"}]'::jsonb,
  ARRAY['〜をなす', '〜のに対し', '〜にほかならない', '〜てはならない'],
  '교육의 기회 균등은 민주주의 사회의 근간을 이루는 이념 중 하나이다. 일본 헌법 제26조는 모든 국민에게 동등하게 교육을 받을 권리를 보장하고 있다. 그러나 현실에는 다양한 요인에 의해 교육 격차가 발생하고 있으며, 그 시정은 일본 사회의 중요한 과제가 되고 있다.

교육 격차의 최대 요인은 가정의 경제력이다. 문부과학성 조사에 따르면 세대 연수입이 높은 가정일수록 자녀의 대학 진학률이 높다는 상관관계가 명확히 나타나 있다. 연수입 400만 엔 미만 가정의 대학 진학률이 약 30%인 데 비해 연수입 1000만 엔 이상 가정에서는 약 60%에 달한다. 이 차이는 학원이나 입시학원 비용, 대학 학비 등 교육에 들어가는 경제적 부담의 크기를 반영하고 있다.

지역 간 격차도 간과할 수 없는 문제이다. 도시 지역에는 다양한 교육 기관과 문화 시설이 집중되어 있는 반면 지방에서는 선택지가 제한된다. 과소 지역에서는 학교 통폐합이 진행되어 통학에 장시간이 소요되는 아동·학생도 적지 않다. 온라인 교육의 보급은 지역 격차 해소에 일정한 역할을 하고 있지만 인프라 정비의 지연과 디지털 격차라는 새로운 문제도 부상하고 있다.

또한 외국에 뿌리를 둔 아이들의 교육 격차도 심각하다. 일본어 능력 부족으로 학업을 따라가지 못하는 아이나 고교 진학을 포기하는 아이도 존재한다. 그들의 다수는 불안정한 고용에 종사하게 되며 빈곤의 연쇄에 빠질 위험이 높다.

교육 격차를 해소하기 위해서는 장학금 제도의 확충, 무상 교육 범위 확대, 지역 간 교육 자원의 재배분 등 제도적 노력이 불가결하다. 그러나 그 이상으로 중요한 것은 교육을 받을 기회가 태어난 환경에 따라 좌우되어서는 안 된다는 사회 전체의 강한 의지일 것이다. 모든 아이가 동등하게 가능성을 꽃피울 수 있는 사회의 실현은 다음 세대에 대한 책무에 다름 아니다.',
  43
);

-- N1-8: 食の安全と消費者意識 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '食の安全と消費者意識',
  '食の安全に対する消費者の関心は、過去の食品偽装事件や農薬混入問題を経て、かつてないほど高まっている。日本の食品安全行政は、2003年に設立された食品安全委員会を中心に、リスク評価とリスク管理を科学的根拠に基づいて行う体系が構築されている。

食品の安全性を確保するための制度として、トレーサビリティシステムの導入が進んでいる。生産から流通、販売に至るまでの過程を追跡可能にすることで、問題が発生した際に迅速な対応を可能にするものだ。特に牛肉に関しては、BSE問題を契機に個体識別番号による管理が義務化され、消費者が生産履歴を確認できる仕組みが整えられた。

食品表示法に基づく表示制度も重要な役割を果たしている。原材料名、原産地、アレルゲン情報、栄養成分表示などが義務づけられ、消費者が適切な選択を行うための情報が提供されている。2022年からは、遺伝子組み換え食品の表示制度が厳格化され、「遺伝子組み換えでない」と表記できる基準がより厳しくなった。

一方、消費者側の意識にも変化が見られる。有機栽培や無農薬の農産物への需要が高まり、オーガニック市場は着実に拡大している。産地直送の通販サイトや、生産者の顔が見えるファーマーズマーケットの人気も、食への信頼を直接確認したいという消費者心理の表れである。

しかし、食の安全性とコストの間にはトレードオフの関係がある。安全性の高い食品は総じて価格も高く、全ての消費者が手にできるわけではない。食の安全を一部の富裕層だけの特権としないためにも、安全で手頃な価格の食品を安定的に供給できる仕組みの構築が、今後ますます重要になるだろう。',
  'article',
  'N1',
  320,
  '食の安全',
  '[{"word":"偽装","reading":"ぎそう","meaning_ko":"위장"},{"word":"追跡","reading":"ついせき","meaning_ko":"추적"},{"word":"契機","reading":"けいき","meaning_ko":"계기"},{"word":"厳格化","reading":"げんかくか","meaning_ko":"엄격화"},{"word":"有機栽培","reading":"ゆうきさいばい","meaning_ko":"유기 재배"},{"word":"特権","reading":"とっけん","meaning_ko":"특권"}]'::jsonb,
  ARRAY['〜を経て', '〜を契機に', '〜わけではない', '〜ためにも'],
  '식품 안전에 대한 소비자의 관심은 과거의 식품 위장 사건이나 농약 혼입 문제를 겪으면서 그 어느 때보다 높아지고 있다. 일본의 식품 안전 행정은 2003년에 설립된 식품안전위원회를 중심으로 리스크 평가와 리스크 관리를 과학적 근거에 기반하여 수행하는 체계가 구축되어 있다.

식품의 안전성을 확보하기 위한 제도로서 이력추적 시스템의 도입이 진행되고 있다. 생산부터 유통, 판매에 이르기까지의 과정을 추적 가능하게 함으로써 문제가 발생했을 때 신속한 대응을 가능하게 하는 것이다. 특히 소고기에 관해서는 BSE 문제를 계기로 개체 식별 번호에 의한 관리가 의무화되어 소비자가 생산 이력을 확인할 수 있는 구조가 마련되었다.

식품표시법에 기반한 표시 제도도 중요한 역할을 하고 있다. 원재료명, 원산지, 알레르겐 정보, 영양 성분 표시 등이 의무화되어 소비자가 적절한 선택을 하기 위한 정보가 제공되고 있다. 2022년부터는 유전자 변형 식품의 표시 제도가 엄격화되어 "유전자 변형이 아닌"이라고 표기할 수 있는 기준이 더 엄격해졌다.

한편 소비자 측의 의식에도 변화가 보인다. 유기 재배나 무농약 농산물에 대한 수요가 높아지며 오가닉 시장은 착실하게 확대되고 있다. 산지 직송 통신판매 사이트나 생산자의 얼굴이 보이는 파머스 마켓의 인기도 식품에 대한 신뢰를 직접 확인하고 싶다는 소비자 심리의 표현이다.

그러나 식품 안전성과 비용 사이에는 트레이드오프 관계가 있다. 안전성이 높은 식품은 대체로 가격도 높으며 모든 소비자가 손에 넣을 수 있는 것은 아니다. 식품 안전을 일부 부유층만의 특권으로 만들지 않기 위해서도, 안전하고 합리적인 가격의 식품을 안정적으로 공급할 수 있는 구조의 구축이 앞으로 점점 더 중요해질 것이다.',
  44
);

-- N1-9: 日本語の曖昧表現と文化的背景 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語の曖昧表現と文化的背景',
  '日本語は、世界の言語の中でも特に曖昧な表現が多い言語だと言われている。「ちょっと…」「考えておきます」「前向きに検討します」といった表現は、言葉通りに受け取ると肯定的に聞こえるが、実際には婉曲的な断りを意味することが多い。この独特のコミュニケーションスタイルは、日本語学習者にとって最も理解しにくい側面の一つである。

こうした曖昧表現の背景には、日本社会に根づいた「和」の精神がある。聖徳太子の十七条憲法に「和を以て貴しとなす」とあるように、集団の調和を重視する価値観は日本文化の根底に流れている。直接的な拒絶や否定は相手の面子を潰し、人間関係に亀裂を生じさせるリスクがある。そのため、真意を直接伝えるのではなく、相手に「察してもらう」ことを期待するコミュニケーションが発達したのである。

言語学者のエドワード・ホールが提唱した「高コンテクスト文化」の概念は、この現象を理解する上で有用である。日本は典型的な高コンテクスト文化に分類され、言葉そのものよりも、その場の雰囲気、話者同士の関係性、非言語的な手がかりから意味を読み取ることが重視される。「空気を読む」という日本語表現は、まさにこの文化的特質を端的に示している。

しかし、グローバル化が進む現代社会において、この曖昧さは時として深刻なミスコミュニケーションの原因となる。低コンテクスト文化圏の人々にとって、「検討します」が「やりません」を意味するという理解は容易ではない。また、日本社会の内部においても、若い世代を中心に、より直接的なコミュニケーションを好む傾向が見られるようになっている。

曖昧表現を日本語の「欠点」と見るか「豊かさ」と見るかは、立場によって異なる。確かに、曖昧さが責任の所在を不明確にし、意思決定を遅延させるという批判は正当である。しかし同時に、相手の立場を慮り、衝突を回避しようとする配慮の表れでもある。重要なのは、相手や状況に応じて、曖昧な表現と明確な表現を使い分ける能力を身につけることであろう。それこそが、真の言語運用能力と言えるのではないだろうか。',
  'essay',
  'N1',
  350,
  '曖昧表現と文化',
  '[{"word":"婉曲的","reading":"えんきょくてき","meaning_ko":"완곡적"},{"word":"亀裂","reading":"きれつ","meaning_ko":"균열"},{"word":"提唱","reading":"ていしょう","meaning_ko":"제창"},{"word":"端的に","reading":"たんてきに","meaning_ko":"단적으로"},{"word":"慮る","reading":"おもんぱかる","meaning_ko":"배려하다, 헤아리다"},{"word":"遅延","reading":"ちえん","meaning_ko":"지연"}]'::jsonb,
  ARRAY['〜と言われている', '〜のではないだろうか', '〜に応じて', '〜こそが'],
  '일본어는 세계 언어 중에서도 특히 모호한 표현이 많은 언어라고 말해지고 있다. "쵸또(좀)...", "생각해 두겠습니다", "전향적으로 검토하겠습니다" 등의 표현은 말 그대로 받아들이면 긍정적으로 들리지만 실제로는 완곡적인 거절을 의미하는 경우가 많다. 이 독특한 커뮤니케이션 스타일은 일본어 학습자에게 가장 이해하기 어려운 측면 중 하나이다.

이러한 모호한 표현의 배경에는 일본 사회에 뿌리내린 "와(화합)"의 정신이 있다. 쇼토쿠 태자의 17조 헌법에 "화합을 귀히 여기라"고 있듯이, 집단의 조화를 중시하는 가치관은 일본 문화의 근저에 흐르고 있다. 직접적인 거절이나 부정은 상대의 체면을 손상시키고 인간관계에 균열을 일으킬 위험이 있다. 그러므로 진의를 직접 전하는 것이 아니라 상대가 "알아차려 주기"를 기대하는 커뮤니케이션이 발달한 것이다.

언어학자 에드워드 홀이 제창한 "고맥락 문화"의 개념은 이 현상을 이해하는 데 유용하다. 일본은 전형적인 고맥락 문화로 분류되며, 말 자체보다 그 자리의 분위기, 화자 간의 관계성, 비언어적 단서에서 의미를 읽어내는 것이 중시된다. "쿠키오 요무(분위기를 읽다)"라는 일본어 표현은 바로 이 문화적 특질을 단적으로 보여주고 있다.

그러나 글로벌화가 진행되는 현대 사회에서 이 모호함은 때때로 심각한 미스커뮤니케이션의 원인이 된다. 저맥락 문화권 사람들에게 "검토하겠습니다"가 "하지 않겠습니다"를 의미한다는 이해는 쉽지 않다. 또한 일본 사회 내부에서도 젊은 세대를 중심으로 보다 직접적인 커뮤니케이션을 선호하는 경향이 나타나고 있다.

모호한 표현을 일본어의 "결점"으로 볼 것인가 "풍요로움"으로 볼 것인가는 입장에 따라 다르다. 확실히 모호함이 책임 소재를 불명확하게 하고 의사결정을 지연시킨다는 비판은 정당하다. 그러나 동시에 상대의 입장을 헤아리고 충돌을 회피하려는 배려의 표현이기도 하다. 중요한 것은 상대나 상황에 따라 모호한 표현과 명확한 표현을 구사하는 능력을 갖추는 것이리라. 그것이야말로 진정한 언어 운용 능력이라고 말할 수 있지 않을까.',
  45
);

