-- N5-18: やすみの ひの にっき (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'やすみの ひの にっき',
  'きょうは にちようびです。やすみでした。

あさ 9じに おきました。
あさごはんに パンと たまごを たべました。
それから せんたくを しました。

ひるに ともだちと えいがを みました。
えいがは とても おもしろかったです。

えいがの あとで いっしょに カフェに いきました。
コーヒーを のみながら たくさん はなしました。

よる 7じに うちに かえりました。
ばんごはんは カレーを つくりました。
とても いい いちにちでした。',
  'essay',
  'N5',
  70,
  '休みの日の日記',
  '[{"word":"洗濯","reading":"せんたく","meaning_ko":"세탁, 빨래"},{"word":"映画","reading":"えいが","meaning_ko":"영화"},{"word":"面白い","reading":"おもしろい","meaning_ko":"재미있다"},{"word":"話す","reading":"はなす","meaning_ko":"이야기하다"},{"word":"一日","reading":"いちにち","meaning_ko":"하루"}]'::jsonb,
  ARRAY['〜ました', '〜かったです', '〜ながら'],
  '오늘은 일요일입니다. 쉬는 날이었습니다.

아침 9시에 일어났습니다.
아침밥으로 빵과 달걀을 먹었습니다.
그리고 빨래를 했습니다.

점심에 친구와 영화를 봤습니다.
영화는 매우 재미있었습니다.

영화 후에 같이 카페에 갔습니다.
커피를 마시면서 많이 이야기했습니다.

밤 7시에 집에 돌아왔습니다.
저녁은 카레를 만들었습니다.
정말 좋은 하루였습니다.',
  18
);

