おすしは にほんの ゆうめいな たべものです。
おこめの うえに さかなが のっています。
わたしは サーモンが いちばん すきです。

ラーメンも にんきが あります。
しょうゆ、みそ、しお、とんこつの あじが あります。
ふゆに あつい ラーメンを たべると あたたかくなります。

てんぷらは やさいや えびを あぶらで あげた たべものです。
さくさくして おいしいです。

にほんの たべものは せかいで にんきが あります。',
  'article',
  'N5',
  70,
  '日本の食べ物',
  '[{"word":"紹介","reading":"しょうかい","meaning_ko":"소개"},{"word":"有名","reading":"ゆうめい","meaning_ko":"유명한"},{"word":"人気","reading":"にんき","meaning_ko":"인기"},{"word":"天ぷら","reading":"てんぷら","meaning_ko":"덴푸라"},{"word":"世界","reading":"せかい","meaning_ko":"세계"}]'::jsonb,
  ARRAY['〜が あります', '〜が いちばん すきです', '〜と あたたかくなります'],
  '일본 음식을 소개합니다.

초밥은 일본의 유명한 음식입니다.
밥 위에 생선이 올려져 있습니다.
저는 연어가 가장 좋아합니다.

라멘도 인기가 있습니다.
간장, 미소, 소금, 돈코츠 맛이 있습니다.
겨울에 뜨거운 라멘을 먹으면 따뜻해집니다.

