-- N4-11: 日本の電車の乗り方 (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の電車の乗り方',
  '日本で電車に乗る方法を説明します。

1. 切符を買う
駅の券売機で切符を買います。行きたい駅までの値段を確認してから、お金を入れてボタンを押します。ICカード（SuicaやPASMO）を使うと便利です。

2. 改札を通る
切符は改札機に入れてください。ICカードはタッチするだけです。

3. ホームに行く
案内板を見て、正しいホームに行きます。電車の方向を間違えないように気をつけてください。

4. 電車に乗る
ドアが開いたら、降りる人を先に通してから乗ります。

5. 降りる
目的の駅に着いたら、改札で切符を入れるか、ICカードをタッチして出ます。',
  'instruction',
  'N4',
  120,
  '電車の乗り方',
  '[{"word":"券売機","reading":"けんばいき","meaning_ko":"자동 매표기"},{"word":"改札","reading":"かいさつ","meaning_ko":"개찰구"},{"word":"案内板","reading":"あんないばん","meaning_ko":"안내판"},{"word":"方向","reading":"ほうこう","meaning_ko":"방향"},{"word":"目的","reading":"もくてき","meaning_ko":"목적"}]'::jsonb,
  ARRAY['〜てから', '〜ように気をつける', '〜たら'],
  '일본에서 전철 타는 방법을 설명합니다.

1. 표 사기
역의 자동 매표기에서 표를 삽니다. 가고 싶은 역까지의 가격을 확인한 후 돈을 넣고 버튼을 누릅니다. IC카드(Suica나 PASMO)를 사용하면 편리합니다.

2. 개찰구 통과
표는 개찰기에 넣어 주세요. IC카드는 터치만 하면 됩니다.

3. 플랫폼으로 가기
안내판을 보고 올바른 플랫폼으로 갑니다. 전철 방향을 틀리지 않도록 주의해 주세요.

4. 전철 타기
문이 열리면 내리는 사람을 먼저 보낸 후에 탑니다.

5. 내리기
목적지 역에 도착하면 개찰구에서 표를 넣거나 IC카드를 터치하고 나갑니다.',
  20
);

-- N4-12: 外国人向け防災ガイド (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '地震のときの行動ガイド',
  '外国人のための防災ガイド ― 地震のとき

日本は地震が多い国です。地震が起きたときの正しい行動を覚えましょう。

【地震のとき】
1. まず、テーブルの下に入って頭を守ります。
2. 揺れが止まったら、火を消してください。
3. ドアを開けて、逃げる道を作りましょう。
4. あわてて外に出ないでください。

【地震の後】
・テレビやラジオで情報を確認しましょう。
・エレベーターは使わないでください。
・避難場所は近くの学校や公園です。

【準備しておくもの】
水（1人3リットル×3日分）、食べ物、懐中電灯、電池、薬

地域の防災訓練にも参加しましょう。',
  'instruction',
  'N4',
  130,
  '防災ガイド',
  '[{"word":"地震","reading":"じしん","meaning_ko":"지진"},{"word":"揺れ","reading":"ゆれ","meaning_ko":"흔들림"},{"word":"避難場所","reading":"ひなんばしょ","meaning_ko":"대피소"},{"word":"懐中電灯","reading":"かいちゅうでんとう","meaning_ko":"손전등"},{"word":"防災訓練","reading":"ぼうさいくんれん","meaning_ko":"방재 훈련"}]'::jsonb,
  ARRAY['〜たら', '〜ないでください', '〜ておく'],
  '외국인을 위한 방재 가이드 ― 지진 발생 시

일본은 지진이 많은 나라입니다. 지진이 발생했을 때의 올바른 행동을 기억합시다.

【지진 발생 시】
1. 우선 테이블 아래로 들어가 머리를 보호합니다.
2. 흔들림이 멈추면 불을 꺼 주세요.
3. 문을 열어 도망갈 길을 만듭시다.
4. 당황해서 밖으로 나가지 마세요.

【지진 후】
・TV나 라디오로 정보를 확인합시다.
・엘리베이터는 사용하지 마세요.
・대피소는 가까운 학교나 공원입니다.

【준비해 둘 것】
물(1인 3리터×3일분), 식품, 손전등, 건전지, 약

지역 방재 훈련에도 참가합시다.',
  21
);

-- N4-13: 友達への旅行の感想メール (email)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '旅行の感想メール',
  '山田さんへ

先週の大阪旅行、とても楽しかったです！教えてくれてありがとう。

道頓堀はとてもにぎやかでした。たこ焼きとお好み焼きを食べました。たこ焼きは外がカリカリで中がとろとろで、おいしかったです。東京のたこ焼きとは全然違いました。

大阪城にも行きました。天守閣から大阪の街を見ることができて、感動しました。思っていたより大きくて、びっくりしました。

USJは人が多くて、3時間も並びました。でも、ジェットコースターに乗れたので、うれしかったです。

次は一緒に行きましょう！写真を送りますね。

パクより',
  'email',
  'N4',
  120,
  '旅行の感想',
  '[{"word":"道頓堀","reading":"どうとんぼり","meaning_ko":"도톤보리"},{"word":"天守閣","reading":"てんしゅかく","meaning_ko":"천수각"},{"word":"感動","reading":"かんどう","meaning_ko":"감동"},{"word":"並ぶ","reading":"ならぶ","meaning_ko":"줄을 서다"},{"word":"送る","reading":"おくる","meaning_ko":"보내다"}]'::jsonb,
  ARRAY['〜てくれてありがとう', '〜より〜のほうが', '〜ことができて'],
  '야마다 씨에게

지난주 오사카 여행, 정말 즐거웠어요! 알려줘서 고마워요.

도톤보리는 정말 활기찼습니다. 타코야키와 오코노미야키를 먹었습니다. 타코야키는 겉은 바삭하고 속이 부드러워서 맛있었습니다. 도쿄의 타코야키와는 전혀 달랐습니다.

오사카성에도 갔습니다. 천수각에서 오사카 시내를 볼 수 있어서 감동했습니다. 생각보다 크서 깜짝 놀랐습니다.

USJ는 사람이 많아서 3시간이나 줄을 섰습니다. 하지만 제트코스터를 탈 수 있어서 기뻤습니다.

다음에는 같이 갑시다! 사진 보낼게요.

박 올림',
  22
);

-- N4-14: 会社の歓迎会のお知らせ (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '歓迎会のお知らせ',
  '社員のみなさんへ

4月に入社する新入社員の歓迎会を行います。

日時：4月5日（金）19:00〜21:00
場所：居酒屋「さくら」（会社から歩いて3分）
会費：3500円（新入社員は無料）
幹事：営業部 木村

メニューは飲み放題・食べ放題のコースです。
アレルギーがある方は、事前に木村まで連絡してください。

参加・不参加を3月25日までにメールで知らせてください。
たくさんの参加をお待ちしています。

総務部',
  'notice',
  'N4',
  110,
  '歓迎会',
  '[{"word":"歓迎会","reading":"かんげいかい","meaning_ko":"환영회"},{"word":"新入社員","reading":"しんにゅうしゃいん","meaning_ko":"신입사원"},{"word":"幹事","reading":"かんじ","meaning_ko":"간사, 총무"},{"word":"飲み放題","reading":"のみほうだい","meaning_ko":"무한 음료"},{"word":"事前","reading":"じぜん","meaning_ko":"사전에"}]'::jsonb,
