-- N4-15: 銀行口座の開設案内 (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '銀行口座の開設案内',
  '外国人の方の銀行口座開設について

日本で生活するために、銀行口座が必要です。

必要なもの：
・在留カード
・パスポート
・印鑑（サインでも可能な場合があります）
・住所がわかるもの（住民票など）

手続きの流れ：
1. 銀行の窓口に行きます。
2.「口座を作りたいです」と言ってください。
3. 書類に名前や住所を書きます。
4. 本人確認書類を見せます。
5. キャッシュカードは後日届きます（1〜2週間）。

注意：
・来日して6か月未満の方は、口座が作れない銀行もあります。
・ゆうちょ銀行は比較的作りやすいです。',
  'instruction',
  'N4',
  120,
  '銀行口座の開設',
  '[{"word":"口座","reading":"こうざ","meaning_ko":"계좌"},{"word":"印鑑","reading":"いんかん","meaning_ko":"도장"},{"word":"住民票","reading":"じゅうみんひょう","meaning_ko":"주민표"},{"word":"本人確認","reading":"ほんにんかくにん","meaning_ko":"본인 확인"},{"word":"比較的","reading":"ひかくてき","meaning_ko":"비교적"}]'::jsonb,
  ARRAY['〜ために', '〜てください', '〜場合があります'],
  '외국인의 은행 계좌 개설에 대하여

일본에서 생활하기 위해 은행 계좌가 필요합니다.

필요한 것:
・체류카드
・여권
・도장 (서명으로도 가능한 경우가 있습니다)
・주소를 알 수 있는 것 (주민표 등)

수속 절차:
1. 은행 창구에 갑니다.
2. "계좌를 만들고 싶습니다"라고 말해 주세요.
3. 서류에 이름이나 주소를 씁니다.
4. 본인 확인 서류를 보여줍니다.
5. 현금카드는 후일 도착합니다 (1~2주).

주의:
・일본에 온 지 6개월 미만인 분은 계좌를 만들 수 없는 은행도 있습니다.
・우체국 은행은 비교적 만들기 쉽습니다.',
  24
);

-- N4-16: 携帯電話プランの比較 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '携帯電話プランの比較',
  '日本で携帯電話を使うとき、いろいろなプランがあります。自分に合ったプランを選びましょう。

【大手キャリア】（ドコモ、au、ソフトバンク）
・月額5000円〜8000円
・通信が安定していて、サポートも充実している
・店舗が多いので、困ったとき相談できる

【格安SIM】（楽天モバイル、UQモバイルなど）
・月額1000円〜3000円
・大手より安いが、通信速度が遅いことがある
・サポートはオンラインが中心

【プリペイドSIM】
・短期滞在の方におすすめ
・空港のコンビニなどで買える
・期間が決まっている（7日、30日など）

日本語が苦手な方は、外国語対応の店舗で契約するのがおすすめです。',
  'article',
  'N4',
  130,
  '携帯電話プラン',
  '[{"word":"月額","reading":"げつがく","meaning_ko":"월액"},{"word":"通信","reading":"つうしん","meaning_ko":"통신"},{"word":"充実","reading":"じゅうじつ","meaning_ko":"충실"},{"word":"格安","reading":"かくやす","meaning_ko":"저렴한"},{"word":"契約","reading":"けいやく","meaning_ko":"계약"}]'::jsonb,
  ARRAY['〜に合った', '〜ことがある', '〜のがおすすめ'],
  '일본에서 휴대전화를 사용할 때 여러 요금제가 있습니다. 자신에게 맞는 요금제를 선택합시다.

【대형 통신사】(도코모, au, 소프트뱅크)
・월 5000엔~8000엔
・통신이 안정적이고 지원도 충실
・매장이 많아서 곤란할 때 상담 가능

【저가 SIM】(라쿠텐 모바일, UQ모바일 등)
・월 1000엔~3000엔
・대형보다 싸지만 통신 속도가 느릴 수 있음
・지원은 온라인 중심

【선불 SIM】
・단기 체류자에게 추천
・공항 편의점 등에서 구매 가능
・기간이 정해져 있음 (7일, 30일 등)

일본어가 어려운 분은 외국어 대응 매장에서 계약하는 것을 추천합니다.',
  25
);

-- N4-17: 日本のお花見文化 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本のお花見文化',
  '日本では、春になると「お花見」をします。お花見とは、桜の花を見ながら、公園などで食べたり飲んだりすることです。

桜は3月の終わりから4月の始めに咲きます。でも、場所によって違います。南の方が早く咲いて、北の方が遅く咲きます。テレビやインターネットで「桜前線」を確認すると、いつ咲くかわかります。

お花見のとき、日本人はブルーシートを敷いて、その上に座ります。お弁当やおにぎり、お酒などを持っていきます。友達や会社の人と一緒に楽しむ人が多いです。

会社では、新入社員が朝早く行って場所を取ることがあります。「場所取り」はちょっと大変ですが、みんなのためにがんばります。

夜に桜を見ることを「夜桜」と言います。ライトアップされた桜はとてもきれいです。',
  'essay',
  'N4',
  140,
  'お花見文化',
  '[{"word":"桜前線","reading":"さくらぜんせん","meaning_ko":"벚꽃 전선"},{"word":"ブルーシート","reading":"ぶるーしーと","meaning_ko":"돗자리"},{"word":"場所取り","reading":"ばしょとり","meaning_ko":"자리잡기"},{"word":"夜桜","reading":"よざくら","meaning_ko":"야간 벚꽃"},{"word":"咲く","reading":"さく","meaning_ko":"피다"}]'::jsonb,
  ARRAY['〜ながら', '〜によって違う', '〜ことがある'],
  '일본에서는 봄이 되면 "하나미(꽃구경)"를 합니다. 하나미란 벚꽃을 보면서 공원 등에서 먹고 마시는 것입니다.

벚꽃은 3월 말부터 4월 초에 핍니다. 하지만 장소에 따라 다릅니다. 남쪽이 먼저 피고 북쪽이 늦게 핍니다. TV나 인터넷에서 "벚꽃 전선"을 확인하면 언제 피는지 알 수 있습니다.

하나미를 할 때 일본인들은 돗자리를 깔고 그 위에 앉습니다. 도시락이나 주먹밥, 술 등을 가져갑니다. 친구나 회사 사람과 함께 즐기는 사람이 많습니다.

회사에서는 신입사원이 아침 일찍 가서 자리를 잡는 경우가 있습니다. "자리잡기"는 좀 힘들지만 모두를 위해 힘냅니다.

밤에 벚꽃을 보는 것을 "요자쿠라"라고 합니다. 조명이 비춰진 벚꽃은 정말 아름답습니다.',
  26
);

-- N4-18: 美容院の予約 (email)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '美容院の予約メール',
  '美容院ヘアサロン「カット＆スタイル」さま

はじめてメールします。パク・ミンジと申します。

来週の土曜日（3月22日）に予約をしたいのですが、空いている時間はありますか。

希望するメニュー：
・カット
・カラー（暗い茶色にしたいです）

午前中が都合がいいのですが、午後でも大丈夫です。

日本語はだいたいわかりますが、難しい言葉はわからないかもしれません。写真を見せながら説明してもいいですか。

お返事をお待ちしています。

パク・ミンジ
090-1234-5678',
  'email',
  'N4',
  100,
  '美容院の予約',
  '[{"word":"美容院","reading":"びよういん","meaning_ko":"미용실"},{"word":"予約","reading":"よやく","meaning_ko":"예약"},{"word":"希望","reading":"きぼう","meaning_ko":"희망"},{"word":"都合","reading":"つごう","meaning_ko":"형편, 사정"},{"word":"説明","reading":"せつめい","meaning_ko":"설명"}]'::jsonb,
  ARRAY['〜と申します', '〜のですが', '〜てもいいですか'],
  '미용실 헤어살롱 "컷&스타일" 님

처음 메일드립니다. 박민지라고 합니다.

다음 주 토요일 (3월 22일)에 예약을 하고 싶은데, 비어있는 시간이 있습니까?

희망 메뉴:
・커트
・컬러 (어두운 갈색으로 하고 싶습니다)

오전이 사정이 좋은데, 오후에도 괜찮습니다.

일본어는 대충 알지만, 어려운 말은 모를 수도 있습니다. 사진을 보여주면서 설명해도 괜찮을까요?

답변 기다리겠습니다.

박민지
090-1234-5678',
  27
);

-- N4-19: マンションの掲示板 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'マンションの掲示板',
  '入居者のみなさまへ

お知らせが3つあります。

1. エレベーターの点検
来週月曜日（3月18日）9:00〜12:00の間、エレベーターが使えません。階段をご利用ください。

2. 駐輪場について
最近、決められた場所以外に自転車が止めてあることが多いです。必ず自分のスペースに止めてください。

3. 宅配ボックスについて
宅配ボックスに荷物が入ったまま長い間取りに来ない方がいます。届いたら、できるだけ早く取りに来てください。

ルールを守って、気持ちよく生活しましょう。

管理組合',
  'notice',
  'N4',
  120,
  'マンションのお知らせ',
  '[{"word":"入居者","reading":"にゅうきょしゃ","meaning_ko":"입주자"},{"word":"点検","reading":"てんけん","meaning_ko":"점검"},{"word":"駐輪場","reading":"ちゅうりんじょう","meaning_ko":"자전거 주차장"},{"word":"宅配ボックス","reading":"たくはいぼっくす","meaning_ko":"택배 보관함"},{"word":"管理組合","reading":"かんりくみあい","meaning_ko":"관리조합"}]'::jsonb,
  ARRAY['〜てあること', '〜たまま', '〜ように'],
  '입주자 여러분에게

안내가 3가지 있습니다.

1. 엘리베이터 점검
다음 주 월요일 (3월 18일) 9:00~12:00 동안 엘리베이터를 사용할 수 없습니다. 계단을 이용해 주세요.

2. 자전거 주차장에 대하여
최근 정해진 장소 이외에 자전거를 세워두는 경우가 많습니다. 반드시 자기 자리에 세워 주세요.

3. 택배 보관함에 대하여
택배 보관함에 짐이 들어간 채로 오랫동안 찾으러 오지 않는 분이 있습니다. 도착하면 가능한 빨리 찾으러 와 주세요.

규칙을 지켜서 기분 좋게 생활합시다.

관리조합',
  28
);

-- N4-20: 日本語能力試験の案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語能力試験の案内',
  '日本語能力試験（JLPT）のお知らせ

次の試験は7月に行われます。

試験日：7月7日（日）
申し込み期間：3月25日〜4月15日
申し込み方法：インターネットから
受験料：7500円

レベル：N1〜N5
・N5（一番やさしい）〜N1（一番難しい）

試験は「言語知識」「読解」「聴解」の3つがあります。
合格するためには、全体の点数と各セクションの点数の両方が必要です。

試験会場は申し込みの後で決まります。
結果は9月にインターネットで確認できます。

がんばって勉強しましょう！',
  'notice',
  'N4',
  110,
  '日本語能力試験',
  '[{"word":"能力試験","reading":"のうりょくしけん","meaning_ko":"능력시험"},{"word":"申し込み","reading":"もうしこみ","meaning_ko":"신청"},{"word":"受験料","reading":"じゅけんりょう","meaning_ko":"수험료"},{"word":"合格","reading":"ごうかく","meaning_ko":"합격"},{"word":"試験会場","reading":"しけんかいじょう","meaning_ko":"시험장"}]'::jsonb,
  ARRAY['〜ために', '〜の後で', '〜で確認できます'],
  '일본어능력시험(JLPT) 안내

다음 시험은 7월에 실시됩니다.

시험일: 7월 7일 (일)
접수 기간: 3월 25일~4월 15일
접수 방법: 인터넷으로
수험료: 7500엔

레벨: N1~N5
・N5 (가장 쉬움)~N1 (가장 어려움)

시험은 "언어지식", "독해", "청해"의 3가지가 있습니다.
합격하려면 전체 점수와 각 섹션 점수 모두가 필요합니다.

시험장은 접수 후에 결정됩니다.
결과는 9월에 인터넷에서 확인할 수 있습니다.

열심히 공부합시다!',
  29
);

-- N4-21: アルバイトの面接体験記 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'アルバイトの面接体験記',
  '先週、コンビニのアルバイトの面接を受けました。

面接の日は、スーツを着て行きました。5分前に着くようにしました。面接官は店長で、やさしそうな人でした。

質問されたこと：
・日本に来てどのくらいですか？
・日本語はどのくらいできますか？
・週に何日、何時間働けますか？
・アルバイトの経験はありますか？

私は「日本語学校に通いながら、週に3日働きたいです」と答えました。韓国のコンビニでアルバイトをしたことがあるので、それも話しました。

面接は15分くらいで終わりました。3日後に「採用します」と電話がありました。とてもうれしかったです。来月から働きます。',
  'essay',
  'N4',
  130,
  'アルバイトの面接',
  '[{"word":"面接","reading":"めんせつ","meaning_ko":"면접"},{"word":"面接官","reading":"めんせつかん","meaning_ko":"면접관"},{"word":"店長","reading":"てんちょう","meaning_ko":"점장"},{"word":"採用","reading":"さいよう","meaning_ko":"채용"},{"word":"経験","reading":"けいけん","meaning_ko":"경험"}]'::jsonb,
  ARRAY['〜ようにする', '〜ながら', '〜ことがある'],
  '지난주, 편의점 아르바이트 면접을 봤습니다.

면접 날은 정장을 입고 갔습니다. 5분 전에 도착하도록 했습니다. 면접관은 점장으로, 친절해 보이는 사람이었습니다.

질문받은 것:
・일본에 온 지 얼마나 되었습니까?
・일본어는 얼마나 할 수 있습니까?
・주에 며칠, 몇 시간 일할 수 있습니까?
・아르바이트 경험이 있습니까?

저는 "일본어 학교에 다니면서 주 3일 일하고 싶습니다"라고 답했습니다. 한국 편의점에서 아르바이트한 적이 있어서 그것도 이야기했습니다.

면접은 15분 정도에 끝났습니다. 3일 후에 "채용합니다"라는 전화가 왔습니다. 정말 기뻤습니다. 다음 달부터 일합니다.',
  30
);

-- N4-22: 通勤電車のトラブル報告 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '通勤電車の遅延報告',
  '遅延のお知らせ

本日3月10日、中央線は人身事故のため、東京〜新宿間で運転を見合わせていました。

影響時間：7:30〜9:15（約1時間45分）
原因：吉祥寺駅での人身事故
影響：上り・下りとも全線で運転見合わせ

振替輸送：
・京王線
・丸ノ内線
・総武線

現在は運転を再開していますが、ダイヤが大幅に乱れています。お急ぎの方は、別の路線をご利用ください。

遅延証明書は改札で配布しています。会社に遅刻するときは、遅延証明書をもらってください。

ご迷惑をおかけして、大変申し訳ございません。',
  'report',
  'N4',
  120,
  '電車の遅延',
  '[{"word":"遅延","reading":"ちえん","meaning_ko":"지연"},{"word":"人身事故","reading":"じんしんじこ","meaning_ko":"인신사고"},{"word":"運転見合わせ","reading":"うんてんみあわせ","meaning_ko":"운행 보류"},{"word":"振替輸送","reading":"ふりかえゆそう","meaning_ko":"대체 수송"},{"word":"遅延証明書","reading":"ちえんしょうめいしょ","meaning_ko":"지연 증명서"}]'::jsonb,
  ARRAY['〜ため', '〜ています', '〜ございません'],
  '지연 안내

오늘 3월 10일, 주오선은 인신사고로 인해 도쿄~신주쿠 구간에서 운행을 보류하고 있었습니다.

영향 시간: 7:30~9:15 (약 1시간 45분)
원인: 기치조지역에서의 인신사고
영향: 상행·하행 모두 전 노선 운행 보류

대체 수송:
・게이오선
・마루노우치선
・소부선

현재는 운행을 재개했지만 시간표가 크게 흐트러져 있습니다. 급하신 분은 다른 노선을 이용해 주세요.

지연 증명서는 개찰구에서 배부하고 있습니다. 회사에 지각할 때는 지연 증명서를 받아 주세요.

불편을 끼쳐 대단히 죄송합니다.',
  31
);

-- N4-23: 健康的な生活のアドバイス (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '健康的な生活のアドバイス',
  '健康な毎日を過ごすために、次のことを心がけましょう。

【食事】
・1日3食、バランスよく食べましょう。
・野菜を多く食べることが大切です。
・甘い物やジュースは控えめにしましょう。

【運動】
・毎日30分くらい歩くだけでも効果があります。
・エスカレーターより階段を使いましょう。
・週に2〜3回は体を動かす時間を作りましょう。

【睡眠】
・毎日同じ時間に寝て、同じ時間に起きましょう。
・寝る前にスマートフォンを見ないようにしましょう。
・7〜8時間の睡眠が理想的です。

小さなことから始めれば、続けることができます。',
  'article',
  'N4',
  120,
  '健康的な生活',
  '[{"word":"心がける","reading":"こころがける","meaning_ko":"마음에 새기다"},{"word":"控えめ","reading":"ひかえめ","meaning_ko":"절제하는"},{"word":"効果","reading":"こうか","meaning_ko":"효과"},{"word":"睡眠","reading":"すいみん","meaning_ko":"수면"},{"word":"理想的","reading":"りそうてき","meaning_ko":"이상적"}]'::jsonb,
  ARRAY['〜ために', '〜ようにする', '〜ば〜できます'],
  '건강한 매일을 보내기 위해 다음을 명심합시다.

【식사】
・하루 3끼 균형 있게 먹읍시다.
・채소를 많이 먹는 것이 중요합니다.
・단 것이나 주스는 적당히 합시다.

【운동】
・매일 30분 정도 걷는 것만으로도 효과가 있습니다.
・에스컬레이터보다 계단을 이용합시다.
・주 2~3회는 몸을 움직이는 시간을 만듭시다.

【수면】
・매일 같은 시간에 자고 같은 시간에 일어납시다.
・자기 전에 스마트폰을 보지 않도록 합시다.
・7~8시간의 수면이 이상적입니다.

작은 것부터 시작하면 계속할 수 있습니다.',
  32
);

-- N4-24: 日本のコンビニ文化 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本のコンビニ文化',
  '日本のコンビニエンスストアは、とても便利です。24時間開いていて、食べ物や飲み物だけでなく、いろいろなサービスがあります。

コンビニでできること：
・ATMでお金を下ろす
・電気代やガス代などを払う
・コピーやプリントをする
・宅配便を送る
・チケットを買う
・住民票を取る

おにぎりやお弁当の種類がとても多くて、味もおいしいです。新商品が毎週出るので、飽きることがありません。

外国人に人気があるのは、肉まんやおでんなどのホットスナックです。冬にレジの横のおでんを買う人がたくさんいます。

日本全国に約5万6千のコンビニがあるそうです。歩いて5分以内にコンビニがあることも珍しくありません。',
  'article',
  'N4',
  130,
  'コンビニ文化',
  '[{"word":"宅配便","reading":"たくはいびん","meaning_ko":"택배"},{"word":"住民票","reading":"じゅうみんひょう","meaning_ko":"주민표"},{"word":"新商品","reading":"しんしょうひん","meaning_ko":"신상품"},{"word":"珍しい","reading":"めずらしい","meaning_ko":"드문, 특이한"},{"word":"飽きる","reading":"あきる","meaning_ko":"질리다"}]'::jsonb,
  ARRAY['〜だけでなく', '〜ことがない', '〜そうです（伝聞）'],
  '일본의 편의점은 정말 편리합니다. 24시간 열려 있고, 음식이나 음료뿐만 아니라 여러 서비스가 있습니다.

편의점에서 할 수 있는 것:
・ATM으로 돈을 인출
・전기세나 가스비 등을 납부
・복사나 프린트
・택배 발송
・티켓 구매
・주민표 발급

주먹밥이나 도시락의 종류가 매우 많고 맛도 있습니다. 신상품이 매주 나오기 때문에 질릴 일이 없습니다.

외국인에게 인기 있는 것은 고기만두나 오뎅 등의 핫스낵입니다. 겨울에 계산대 옆의 오뎅을 사는 사람이 많습니다.

일본 전국에 약 5만 6천 개의 편의점이 있다고 합니다. 걸어서 5분 이내에 편의점이 있는 것도 드물지 않습니다.',
  33
);

-- N4-25: 引っ越しの手続きチェックリスト (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '引っ越しの手続きチェックリスト',
  '引っ越しのときにすること

【引っ越しの前】
□ 引っ越し会社に予約する（1か月前）
□ 今のアパートの管理会社に連絡する（1か月前）
□ 電気・ガス・水道の解約の連絡をする（2週間前）
□ 郵便局で転送届を出す（1週間前）
□ 荷物を箱に入れる

【引っ越しの後】
□ 区役所で転入届を出す（14日以内）
□ 在留カードの住所を変更する
□ 銀行・携帯電話の住所を変更する
□ 電気・ガス・水道の申し込みをする
□ 近所の人にあいさつをする

引っ越しは大変ですが、一つずつやれば大丈夫です。',
  'instruction',
  'N4',
  110,
  '引っ越しの手続き',
  '[{"word":"解約","reading":"かいやく","meaning_ko":"해약"},{"word":"転送届","reading":"てんそうとどけ","meaning_ko":"전송 신고"},{"word":"転入届","reading":"てんにゅうとどけ","meaning_ko":"전입 신고"},{"word":"変更","reading":"へんこう","meaning_ko":"변경"},{"word":"あいさつ","reading":"あいさつ","meaning_ko":"인사"}]'::jsonb,
  ARRAY['〜ときにすること', '〜以内に', '〜ば大丈夫'],
  '이사할 때 할 일

【이사 전】
□ 이사 회사에 예약 (1개월 전)
□ 현재 아파트 관리회사에 연락 (1개월 전)
□ 전기·가스·수도 해약 연락 (2주 전)
□ 우체국에서 전송 신고서 제출 (1주 전)
□ 짐을 상자에 넣기

【이사 후】
□ 구청에서 전입 신고 (14일 이내)
□ 체류카드 주소 변경
□ 은행·휴대전화 주소 변경
□ 전기·가스·수도 신청
□ 이웃에게 인사하기

이사는 힘들지만 하나씩 하면 괜찮습니다.',
  34
);

-- N4-26: 日本の温泉マナー (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の温泉マナー',
  '温泉に入るときのマナー

日本の温泉は裸で入ります。水着は着ません。タオルもお湯に入れないでください。

【入る前に】
1. 脱衣所で服を全部脱ぎます。
2. 体を洗ってからお湯に入ります。
3. シャワーで石けんをきれいに流してください。

【お湯の中で】
・タオルをお湯の中に入れないでください。頭の上に置きます。
・大きい声で話さないでください。
・泳がないでください。
・長い髪はまとめてください。

【出た後】
・体をふいてから脱衣所に戻りましょう。
・水分をしっかり取りましょう。

マナーを守って、気持ちよく温泉を楽しみましょう。',
  'instruction',
  'N4',
  120,
  '温泉マナー',
  '[{"word":"温泉","reading":"おんせん","meaning_ko":"온천"},{"word":"裸","reading":"はだか","meaning_ko":"벌거벗은"},{"word":"脱衣所","reading":"だついじょ","meaning_ko":"탈의실"},{"word":"石けん","reading":"せっけん","meaning_ko":"비누"},{"word":"水分","reading":"すいぶん","meaning_ko":"수분"}]'::jsonb,
  ARRAY['〜てから', '〜ないでください', '〜ましょう'],
  '온천에 들어갈 때의 매너

일본의 온천은 알몸으로 들어갑니다. 수영복은 입지 않습니다. 수건도 탕에 넣지 말아 주세요.

【들어가기 전에】
1. 탈의실에서 옷을 전부 벗습니다.
2. 몸을 씻은 후에 탕에 들어갑니다.
3. 샤워로 비누를 깨끗이 씻어 주세요.

【탕 안에서】
・수건을 탕 안에 넣지 말아 주세요. 머리 위에 올립니다.
・큰 소리로 이야기하지 말아 주세요.
・수영하지 말아 주세요.
・긴 머리는 묶어 주세요.

【나온 후】
・몸을 닦은 후 탈의실로 돌아갑시다.
・수분을 충분히 섭취합시다.

매너를 지켜서 기분 좋게 온천을 즐깁시다.',
  35
);

-- N4-27: フリーマーケットの案内 (advertisement)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'フリーマーケットの案内',
