  'フリーマーケット',
  '[{"word":"開催","reading":"かいさい","meaning_ko":"개최"},{"word":"入場","reading":"にゅうじょう","meaning_ko":"입장"},{"word":"食器","reading":"しょっき","meaning_ko":"식기"},{"word":"出店","reading":"しゅってん","meaning_ko":"출점"},{"word":"販売","reading":"はんばい","meaning_ko":"판매"}]'::jsonb,
  ARRAY['〜たり〜たり', '〜の場合は', '〜はできません'],
  '봄의 프리마켓 개최!

필요 없게 된 물건을 팔거나, 저렴하게 쇼핑할 수 있는 기회입니다!

