-- N4-28: 日本語学校の卒業スピーチ (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語学校の卒業スピーチ',
  'みなさん、こんにちは。パク・ジュンです。

2年前に韓国から日本に来ました。最初は日本語が全然わからなくて、買い物もできませんでした。店員さんが何を言っているか、わかりませんでした。

でも、毎日少しずつ勉強しました。先生たちはいつも「間違えても大丈夫」と言ってくれました。クラスメートとは日本語で話すようにしました。

一番うれしかったのは、日本人の友達ができたことです。一緒にご飯を食べたり、カラオケに行ったりしました。友達と話すことで、教科書にない表現をたくさん覚えました。

来月からIT会社で働きます。まだ日本語が完璧ではありませんが、これからも勉強を続けます。

先生方、クラスメートのみなさん、本当にありがとうございました。',
  'essay',
  'N4',
  140,
  '卒業スピーチ',
  '[{"word":"卒業","reading":"そつぎょう","meaning_ko":"졸업"},{"word":"最初","reading":"さいしょ","meaning_ko":"처음"},{"word":"間違える","reading":"まちがえる","meaning_ko":"틀리다"},{"word":"表現","reading":"ひょうげん","meaning_ko":"표현"},{"word":"完璧","reading":"かんぺき","meaning_ko":"완벽"}]'::jsonb,
  ARRAY['〜ようにする', '〜ことで', '〜を続ける'],
  '여러분, 안녕하세요. 박준입니다.

2년 전에 한국에서 일본에 왔습니다. 처음에는 일본어를 전혀 몰라서 쇼핑도 못 했습니다. 점원이 무슨 말을 하는지 몰랐습니다.

하지만 매일 조금씩 공부했습니다. 선생님들은 항상 "틀려도 괜찮아"라고 말해 주셨습니다. 반 친구들과는 일본어로 이야기하도록 했습니다.

가장 기뻤던 것은 일본인 친구가 생긴 것입니다. 함께 밥을 먹거나 노래방에 가거나 했습니다. 친구와 이야기하면서 교과서에 없는 표현을 많이 외웠습니다.

다음 달부터 IT 회사에서 일합니다. 아직 일본어가 완벽하지 않지만 앞으로도 공부를 계속하겠습니다.

선생님들, 반 친구 여러분, 정말 감사했습니다.',
  37
);

-- N4-29: 図書館のイベント案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '図書館のイベント案内',
  '中央図書館 4月のイベント

① 外国語の絵本読み聞かせ
  日時：4月6日（土）14:00〜15:00
  場所：2階 子どもコーナー
  英語・中国語・韓国語の絵本を読みます。
