  場所：3階 会議室
  やさしい日本語の小説を一緒に読みます。
  N4以上の日本語力がある方が対象です。

③ パソコン教室（初心者向け）
  日時：4月20日（土）13:00〜15:00
  場所：1階 パソコンルーム
  ワードとエクセルの基本を学びます。
  定員10名（先着順）

すべて参加費無料です。予約は窓口またはお電話で。',
  'notice',
  'N4',
  120,
  '図書館のイベント',
  '[{"word":"絵本","reading":"えほん","meaning_ko":"그림책"},{"word":"読み聞かせ","reading":"よみきかせ","meaning_ko":"읽어주기"},{"word":"小説","reading":"しょうせつ","meaning_ko":"소설"},{"word":"初心者","reading":"しょしんしゃ","meaning_ko":"초보자"},{"word":"先着順","reading":"せんちゃくじゅん","meaning_ko":"선착순"}]'::jsonb,
  ARRAY['〜向け', '〜と一緒に', '〜が対象です'],
  '중앙도서관 4월 이벤트

① 외국어 그림책 읽어주기
  일시: 4월 6일 (토) 14:00~15:00
  장소: 2층 어린이 코너
  영어·중국어·한국어 그림책을 읽습니다.
  자녀와 함께 참가할 수 있습니다.

② 일본어 책 읽는 모임
  일시: 4월 13일 (토) 10:00~11:30
  장소: 3층 회의실
  쉬운 일본어 소설을 함께 읽습니다.
  N4 이상의 일본어 능력이 있는 분이 대상입니다.

③ 컴퓨터 교실 (초보자용)
  일시: 4월 20일 (토) 13:00~15:00
  장소: 1층 컴퓨터실
  워드와 엑셀의 기본을 배웁니다.
  정원 10명 (선착순)

모두 참가비 무료입니다. 예약은 창구 또는 전화로.',
