);

-- N4-30: 外国人の友達への手紙 (letter)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '韓国の友達への手紙',
  'ジュンへ

お元気ですか。東京はだんだん暖かくなってきました。

日本に来て半年が過ぎました。やっと生活にも慣れてきた気がします。最初は電車の乗り方もわからなくて大変でしたが、今はどこでも一人で行けるようになりました。

仕事も少しずつ慣れてきました。周りの人はみんなやさしいですが、敬語がまだ難しくて、よく間違えます。「お疲れ様です」と「ご苦労様です」の使い分けを最近やっと覚えました。

週末はよく近くの商店街で買い物をします。八百屋のおばさんが「今日は大根が安いよ」といつも声をかけてくれます。こういう人のやさしさが、日本で頑張る力になっています。

今度、韓国に帰るとき、お土産を持っていきますね。体に気をつけて。

ミンスより',
  'letter',
  'N4',
  140,
  '友達への手紙',
  '[{"word":"慣れる","reading":"なれる","meaning_ko":"익숙해지다"},{"word":"敬語","reading":"けいご","meaning_ko":"경어, 존댓말"},{"word":"使い分け","reading":"つかいわけ","meaning_ko":"구분하여 사용"},{"word":"商店街","reading":"しょうてんがい","meaning_ko":"상점가"},{"word":"お土産","reading":"おみやげ","meaning_ko":"선물, 기념품"}]'::jsonb,
  ARRAY['〜てきた', '〜ようになった', '〜てくれる'],
  '준에게

잘 지내고 있어? 도쿄는 점점 따뜻해지고 있어.

일본에 온 지 반년이 지났어. 드디어 생활에도 익숙해진 것 같아. 처음에는 전철 타는 법도 몰라서 힘들었는데, 지금은 어디든 혼자 갈 수 있게 되었어.

일도 조금씩 익숙해지고 있어. 주변 사람들은 모두 친절하지만 경어가 아직 어려워서 자주 틀려. "오쓰카레사마데스"와 "고쿠로사마데스"의 구분을 최근에 겨우 외웠어.

주말에는 자주 근처 상점가에서 장을 봐. 채소 가게 아주머니가 "오늘은 무가 싸요"라고 항상 말을 걸어 줘. 이런 사람들의 따뜻함이 일본에서 힘내는 원동력이 되고 있어.

다음에 한국에 돌아갈 때 선물 가져갈게. 건강 조심해.

민수 올림',
  39
);

