-- N3-10: IT企業の新入社員研修案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'IT企業の新入社員研修案内',
  '新入社員研修のご案内

2026年度新入社員のみなさんへ

入社式後、以下のスケジュールで研修を実施します。

【研修スケジュール】
第1週（4/1〜4/5）：ビジネスマナー研修
　・名刺交換、電話対応、メールの書き方
　・社内ルールとセキュリティポリシー

第2週（4/8〜4/12）：技術基礎研修
　・プログラミング基礎（Java）
　・データベースの基本操作
　・バージョン管理（Git）

第3〜4週（4/15〜4/26）：チーム開発演習
　・4〜5人のチームでWebアプリケーションを開発
　・最終日にプレゼンテーション

持ち物：ノートPC（支給品）、筆記用具
服装：1週目はスーツ、2週目以降はオフィスカジュアル可

不明な点は人事部（内線2100）までお問い合わせください。',
  'notice',
  'N3',
  160,
  'IT企業の研修',
  '[{"word":"研修","reading":"けんしゅう","meaning_ko":"연수"},{"word":"実施","reading":"じっし","meaning_ko":"실시"},{"word":"名刺交換","reading":"めいしこうかん","meaning_ko":"명함 교환"},{"word":"支給品","reading":"しきゅうひん","meaning_ko":"지급품"},{"word":"人事部","reading":"じんじぶ","meaning_ko":"인사부"}]'::jsonb,
  ARRAY['〜以降は', '〜までお問い合わせください', '〜可'],
  '신입사원 연수 안내

2026년도 신입사원 여러분에게

입사식 후 아래 일정으로 연수를 실시합니다.

【연수 일정】
제1주 (4/1~4/5): 비즈니스 매너 연수
　・명함 교환, 전화 응대, 메일 작성법
　・사내 규칙과 보안 정책

제2주 (4/8~4/12): 기술 기초 연수
　・프로그래밍 기초 (Java)
　・데이터베이스 기본 조작
　・버전 관리 (Git)

제3~4주 (4/15~4/26): 팀 개발 실습
　・4~5명 팀으로 웹 애플리케이션 개발
　・마지막 날 프레젠테이션

지참물: 노트PC (지급품), 필기구
복장: 1주차는 정장, 2주차 이후 오피스 캐주얼 가능

