-- N3-11: リモートワークのガイドライン (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'リモートワークのガイドライン',
  'リモートワーク実施ガイドライン

当社では週2日までリモートワークが可能です。以下のルールを守ってください。

【勤務開始・終了】
・始業時刻（9:00）にSlackで「おはようございます」と報告
・終業時刻（18:00）に「お疲れ様でした」と報告
・外出や中抜けの際は上司に連絡

【コミュニケーション】
・カメラはオンにすることを推奨
・チャットの返信は30分以内を目安に
・重要な相談は対面またはビデオ通話で

【セキュリティ】
・カフェなどの公共の場所では、画面にのぞき見防止フィルターを使用
・社内システムへのアクセスは必ずVPNを使用
・業務データを個人の端末にコピーしないこと

【禁止事項】
・リモートワーク中の副業
・許可なく勤務場所を変更すること

ガイドラインに違反した場合、リモートワークの許可が取り消されることがあります。',
  'instruction',
  'N3',
  180,
  'リモートワーク',
  '[{"word":"始業","reading":"しぎょう","meaning_ko":"시업, 업무 시작"},{"word":"推奨","reading":"すいしょう","meaning_ko":"추천"},{"word":"副業","reading":"ふくぎょう","meaning_ko":"부업"},{"word":"違反","reading":"いはん","meaning_ko":"위반"},{"word":"取り消す","reading":"とりけす","meaning_ko":"취소하다"}]'::jsonb,
  ARRAY['〜こと（ルール）', '〜を目安に', '〜ことがあります'],
  '리모트 워크 실시 가이드라인

당사에서는 주 2일까지 리모트 워크가 가능합니다. 아래 규칙을 지켜 주세요.

【근무 시작·종료】
・시업 시각(9:00)에 Slack으로 "안녕하세요" 보고
・종업 시각(18:00)에 "수고하셨습니다" 보고
・외출이나 중간 이탈 시 상사에게 연락

【커뮤니케이션】
・카메라는 켜는 것을 권장
・채팅 답변은 30분 이내를 기준으로
・중요한 상담은 대면 또는 화상통화로

【보안】
・카페 등 공공장소에서는 화면에 엿보기 방지 필터 사용
・사내 시스템 접속은 반드시 VPN 사용
・업무 데이터를 개인 단말에 복사하지 않을 것

【금지 사항】
・리모트 워크 중 부업
・허가 없이 근무 장소를 변경하는 것

가이드라인을 위반한 경우, 리모트 워크 허가가 취소될 수 있습니다.',
  29
);

-- N3-12: プログラマーの1日ブログ (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'プログラマーの1日',
  '日本のIT企業で働くプログラマーの1日を紹介します。

8:30　出社。コーヒーを入れて、メールとSlackをチェック。
9:00　朝会（スタンドアップミーティング）。各自が昨日やったこと、今日やること、困っていることを共有。だいたい15分で終わる。
9:15　コーディング開始。今のプロジェクトはReactとTypeScriptを使ったWebアプリの開発。
12:00　昼休み。同僚と近くのラーメン屋に行くことが多い。
13:00　午後のコーディング。集中力が必要な作業は午後にまとめて行う。
15:00　コードレビュー。先輩のコードを確認したり、自分のコードにフィードバックをもらったりする。
16:00　テストを書く。バグが出ないように、テストコードも大切。
17:30　日報を書いて退社。残業は月に20時間くらい。

プログラミングだけでなく、コミュニケーション力も大切だと感じています。',
  'essay',
  'N3',
  180,
  'IT企業の仕事',
  '[{"word":"朝会","reading":"あさかい","meaning_ko":"아침 회의"},{"word":"共有","reading":"きょうゆう","meaning_ko":"공유"},{"word":"同僚","reading":"どうりょう","meaning_ko":"동료"},{"word":"日報","reading":"にっぽう","meaning_ko":"일보"},{"word":"残業","reading":"ざんぎょう","meaning_ko":"잔업, 야근"}]'::jsonb,
  ARRAY['〜たり〜たりする', '〜ように', '〜だけでなく'],
  '일본 IT 기업에서 일하는 프로그래머의 하루를 소개합니다.

8:30　출근. 커피를 타고 메일과 Slack 체크.
9:00　아침 미팅(스탠드업 미팅). 각자 어제 한 일, 오늘 할 일, 곤란한 점을 공유. 대략 15분에 끝남.
9:15　코딩 시작. 지금 프로젝트는 React와 TypeScript를 사용한 웹앱 개발.
12:00　점심. 동료와 근처 라멘집에 가는 경우가 많음.
13:00　오후 코딩. 집중력이 필요한 작업은 오후에 모아서 진행.
15:00　코드 리뷰. 선배의 코드를 확인하거나 자기 코드에 피드백을 받거나 함.
16:00　테스트 작성. 버그가 나오지 않도록 테스트 코드도 중요.
17:30　일보를 쓰고 퇴근. 야근은 월 20시간 정도.

프로그래밍뿐만 아니라 커뮤니케이션 능력도 중요하다고 느끼고 있습니다.',
  30
);

-- N3-13: 製品リコールのお知らせ (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '製品リコールのお知らせ',
  '重要なお知らせ — 製品の回収について

弊社が販売したモバイルバッテリー「パワーチャージ3000」（型番：PC-3000）において、バッテリーが過熱する可能性があることが判明しました。お客様の安全を最優先に考え、対象製品の無償回収を実施いたします。

対象製品：パワーチャージ3000（PC-3000）
製造期間：2025年6月〜2025年10月
対象台数：約12,000台

症状：充電中に本体が異常に熱くなる場合があります。

お客様へのお願い：
1. 対象製品の使用を直ちに中止してください。
2. 以下の連絡先までご連絡ください。
3. 着払いで製品をお送りいただくか、最寄りの店舗にお持ちください。
4. 製品代金を全額返金いたします。

お問い合わせ先：カスタマーセンター 0120-XXX-XXXX（9:00〜18:00）

ご不便をおかけし、深くお詫び申し上げます。',
  'notice',
  'N3',
  170,
  '製品リコール',
  '[{"word":"回収","reading":"かいしゅう","meaning_ko":"회수"},{"word":"過熱","reading":"かねつ","meaning_ko":"과열"},{"word":"判明","reading":"はんめい","meaning_ko":"판명"},{"word":"無償","reading":"むしょう","meaning_ko":"무상"},{"word":"返金","reading":"へんきん","meaning_ko":"환불"}]'::jsonb,
  ARRAY['〜において', '〜いたします', '〜申し上げます'],
  '중요 안내 — 제품 회수에 대하여

당사가 판매한 모바일 배터리 "파워차지 3000" (형번: PC-3000)에서 배터리가 과열될 가능성이 있음이 판명되었습니다. 고객님의 안전을 최우선으로 생각하여 대상 제품의 무상 회수를 실시합니다.

대상 제품: 파워차지 3000 (PC-3000)
제조 기간: 2025년 6월~2025년 10월
대상 수량: 약 12,000대

증상: 충전 중 본체가 비정상적으로 뜨거워지는 경우가 있습니다.

고객님께 부탁 말씀:
1. 대상 제품의 사용을 즉시 중지해 주세요.
2. 아래 연락처로 연락해 주세요.
3. 착불로 제품을 보내시거나 가까운 매장에 가져와 주세요.
4. 제품 대금을 전액 환불해 드립니다.

문의처: 고객센터 0120-XXX-XXXX (9:00~18:00)

불편을 끼쳐 깊이 사과드립니다.',
