  '[{"word":"進捗","reading":"しんちょく","meaning_ko":"진척"},{"word":"実装","reading":"じっそう","meaning_ko":"구현"},{"word":"仕様","reading":"しよう","meaning_ko":"사양, 스펙"},{"word":"確定","reading":"かくてい","meaning_ko":"확정"},{"word":"依頼","reading":"いらい","meaning_ko":"의뢰"}]'::jsonb,
