-- N3-15: 日本の働き方改革 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の働き方改革',
  '日本では近年、「働き方改革」が大きなテーマになっています。長時間労働を減らし、仕事と生活のバランスを改善することが目標です。

これまで日本では、長い時間働くことが「頑張っている」と評価される傾向がありました。しかし、過労による健康被害やメンタルヘルスの問題が社会問題となり、法律の改正が行われました。

2019年に施行された働き方改革関連法では、残業時間の上限が月45時間、年360時間と定められました。また、有給休暇の取得を促進するため、年5日以上の取得が義務化されました。

IT企業を中心に、リモートワークやフレックスタイム制度を導入する会社も増えています。コロナ禍をきっかけに、この流れはさらに加速しました。

一方で、中小企業では人手不足から、なかなか労働時間を減らせないという現実もあります。制度を作るだけでなく、企業文化そのものを変えていく必要があるでしょう。',
  'article',
  'N3',
  190,
  '働き方改革',
  '[{"word":"働き方改革","reading":"はたらきかたかいかく","meaning_ko":"일하는 방식 개혁"},{"word":"過労","reading":"かろう","meaning_ko":"과로"},{"word":"施行","reading":"しこう","meaning_ko":"시행"},{"word":"有給休暇","reading":"ゆうきゅうきゅうか","meaning_ko":"유급 휴가"},{"word":"人手不足","reading":"ひとでぶそく","meaning_ko":"인력 부족"}]'::jsonb,
  ARRAY['〜ことが〜になっている', '〜をきっかけに', '〜ていく必要がある'],
  '일본에서는 최근 "일하는 방식 개혁"이 큰 테마가 되고 있습니다. 장시간 노동을 줄이고 일과 생활의 균형을 개선하는 것이 목표입니다.

지금까지 일본에서는 오래 일하는 것이 "열심히 하고 있다"고 평가받는 경향이 있었습니다. 그러나 과로로 인한 건강 피해와 정신 건강 문제가 사회 문제가 되어 법률 개정이 이루어졌습니다.

2019년에 시행된 일하는 방식 개혁 관련법에서는 잔업 시간 상한이 월 45시간, 연 360시간으로 정해졌습니다. 또한 유급 휴가 취득을 촉진하기 위해 연 5일 이상의 취득이 의무화되었습니다.

IT 기업을 중심으로 리모트 워크나 유연 근무제를 도입하는 회사도 늘고 있습니다. 코로나 사태를 계기로 이 흐름은 더욱 가속화되었습니다.

한편 중소기업에서는 인력 부족으로 좀처럼 노동 시간을 줄이지 못하는 현실도 있습니다. 제도를 만드는 것뿐만 아니라 기업 문화 자체를 바꿔 나갈 필요가 있을 것입니다.',
  33
);

-- N3-16: アプリのレビュー (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '学習アプリのレビュー',
  '日本語学習アプリ「NihonGo!」を3か月使ってみたレビューです。

【良い点】
・AIが弱点を分析して、効率的に学習できる。苦手な文法が重点的に出題されるので、弱点を克服しやすい。
・通勤時間に使えるので、忙しくても毎日続けられる。
・ネイティブの音声が聞けるので、リスニングの練習にもなる。

【改善してほしい点】
・読解の問題が少ない。文法と語彙が中心で、長文読解の練習がもっと欲しい。
・無料版だと広告が多くて集中できない。
・オフラインでは使えないので、電波が悪いところでは不便。

【料金】
無料版：基本機能のみ（広告あり）
プレミアム版：月額980円（広告なし、全機能利用可）

総合評価：★★★★☆（4/5）

N3〜N2レベルの学習者におすすめです。ただし、これだけで十分とは言えないので、教科書や実際の会話と組み合わせるのが良いでしょう。',
  'article',
  'N3',
  180,
  'アプリレビュー',
  '[{"word":"弱点","reading":"じゃくてん","meaning_ko":"약점"},{"word":"効率的","reading":"こうりつてき","meaning_ko":"효율적"},{"word":"克服","reading":"こくふく","meaning_ko":"극복"},{"word":"語彙","reading":"ごい","meaning_ko":"어휘"},{"word":"組み合わせる","reading":"くみあわせる","meaning_ko":"조합하다"}]'::jsonb,
  ARRAY['〜てみた', '〜やすい', '〜とは言えない'],
  '일본어 학습 앱 "NihonGo!"를 3개월 사용해 본 리뷰입니다.

【좋은 점】
・AI가 약점을 분석해서 효율적으로 학습할 수 있다. 약한 문법이 중점적으로 출제되어 약점을 극복하기 쉽다.
・통근 시간에 사용할 수 있어서 바빠도 매일 계속할 수 있다.
・원어민 음성을 들을 수 있어서 리스닝 연습도 된다.

【개선 희망 사항】
・독해 문제가 적다. 문법과 어휘가 중심이라 장문 독해 연습이 더 필요하다.
・무료 버전은 광고가 많아서 집중하기 어렵다.
・오프라인에서는 사용 불가하여 전파가 나쁜 곳에서는 불편하다.

【요금】
무료 버전: 기본 기능만 (광고 있음)
프리미엄 버전: 월 980엔 (광고 없음, 전 기능 이용 가능)

종합 평가: ★★★★☆ (4/5)

N3~N2 레벨 학습자에게 추천합니다. 다만 이것만으로 충분하다고는 할 수 없으므로 교과서나 실제 대화와 조합하는 것이 좋을 것입니다.',
  34
);

-- N3-17: 職場のハラスメント対策 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '職場のハラスメント対策',
  '社員のみなさまへ

職場のハラスメント防止に関する重要なお知らせです。

当社では、すべての社員が安心して働ける環境づくりを推進しています。以下の行為はハラスメントに該当する可能性がありますので、十分にご注意ください。

【パワーハラスメント】
・人前で大声で怒鳴ること
・能力を超えた業務を押しつけること
・必要以上に長時間の叱責

【セクシャルハラスメント】
・外見や容姿に関する不適切な発言
・不必要な身体的接触

【相談窓口】
ハラスメントを受けた方、または目撃した方は、以下の窓口にご相談ください。
・社内相談窓口：人事部（内線3000）
・外部相談窓口：03-XXXX-XXXX（専門カウンセラー対応）

相談者のプライバシーは厳守します。報復行為は厳しく処分されます。

一人で悩まず、まずはご相談ください。',
  'notice',
  'N3',
  180,
  'ハラスメント対策',
  '[{"word":"防止","reading":"ぼうし","meaning_ko":"방지"},{"word":"該当","reading":"がいとう","meaning_ko":"해당"},{"word":"叱責","reading":"しっせき","meaning_ko":"질책"},{"word":"厳守","reading":"げんしゅ","meaning_ko":"엄수"},{"word":"報復","reading":"ほうふく","meaning_ko":"보복"}]'::jsonb,
  ARRAY['〜に該当する', '〜ことのないよう', '〜ください'],
  '사원 여러분에게

직장 내 괴롭힘 방지에 관한 중요한 안내입니다.

당사에서는 모든 사원이 안심하고 일할 수 있는 환경 만들기를 추진하고 있습니다. 아래 행위는 괴롭힘에 해당할 가능성이 있으니 충분히 주의해 주세요.

【파워 해러스먼트】
・사람들 앞에서 큰 소리로 호통치는 것
・능력을 넘는 업무를 떠맡기는 것
・필요 이상으로 오랜 시간의 질책

【성적 괴롭힘】
・외모나 용모에 관한 부적절한 발언
・불필요한 신체적 접촉

【상담 창구】
괴롭힘을 당한 분 또는 목격한 분은 아래 창구에 상담해 주세요.
・사내 상담 창구: 인사부 (내선 3000)
・외부 상담 창구: 03-XXXX-XXXX (전문 카운슬러 대응)

상담자의 프라이버시는 엄수합니다. 보복 행위는 엄격히 처분됩니다.

혼자 고민하지 말고 먼저 상담해 주세요.',
  35
);

-- N3-18: 日本の四季と食文化 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の四季と食文化',
  '日本には四季があり、季節ごとに旬の食材を楽しむ文化があります。

春には、桜の季節に合わせて桜餅やいちご大福などの和菓子が店頭に並びます。また、たけのこや菜の花など、春の野菜も人気です。花見のときに食べるお弁当には、旬の食材が詰まっています。

夏は暑さ対策として、冷たい食べ物が好まれます。そうめん、冷やし中華、かき氷などが定番です。土用の丑の日にうなぎを食べる習慣は、江戸時代から続いていると言われています。

秋は「食欲の秋」と呼ばれ、多くの食材が旬を迎えます。秋刀魚、松茸、栗、柿など、実りの季節ならではの味覚が楽しめます。

冬は温かい鍋料理が欠かせません。すき焼き、しゃぶしゃぶ、おでんなど、体が温まる料理が食卓に上がります。年末年始にはおせち料理やお雑煮を食べ、新しい年の健康を祈ります。

旬の食材を大切にする日本の食文化は、自然との共生を表していると言えるでしょう。',
  'essay',
  'N3',
  200,
  '四季と食文化',
  '[{"word":"旬","reading":"しゅん","meaning_ko":"제철"},{"word":"店頭","reading":"てんとう","meaning_ko":"점두, 매장"},{"word":"定番","reading":"ていばん","meaning_ko":"정석, 단골"},{"word":"食欲","reading":"しょくよく","meaning_ko":"식욕"},{"word":"共生","reading":"きょうせい","meaning_ko":"공생"}]'::jsonb,
  ARRAY['〜ごとに', '〜と言われている', '〜ならではの'],
  '일본에는 사계절이 있으며 계절마다 제철 식재료를 즐기는 문화가 있습니다.

봄에는 벚꽃 시즌에 맞춰 사쿠라모찌나 딸기 다이후쿠 등의 화과자가 매장에 진열됩니다. 또한 죽순이나 유채꽃 등 봄 채소도 인기입니다. 하나미 때 먹는 도시락에는 제철 식재료가 가득합니다.

여름에는 더위 대책으로 차가운 음식이 선호됩니다. 소면, 히야시 츄카, 빙수 등이 정석입니다. 도요노우시노히에 장어를 먹는 습관은 에도 시대부터 이어져 왔다고 합니다.

가을은 "식욕의 가을"이라고 불리며 많은 식재료가 제철을 맞이합니다. 꽁치, 송이버섯, 밤, 감 등 수확의 계절만의 미각을 즐길 수 있습니다.

겨울에는 따뜻한 전골 요리가 빠질 수 없습니다. 스키야키, 샤부샤부, 오뎅 등 몸이 따뜻해지는 요리가 식탁에 오릅니다. 연말연시에는 오세치 요리와 오조니를 먹으며 새해의 건강을 빕니다.

제철 식재료를 소중히 하는 일본의 식문화는 자연과의 공생을 나타내고 있다고 할 수 있을 것입니다.',
  36
);

-- N3-19: 社内アンケート結果報告 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '社内アンケート結果報告',
  '2025年度 社員満足度アンケート結果報告

実施期間：2025年12月1日〜12月15日
回答率：87.3%（対象254名中222名が回答）

【主な結果】

1. 総合満足度：3.8/5.0（前年比+0.3）
　改善傾向が見られ、特にコミュニケーション面で向上しました。

2. カテゴリー別スコア
　・仕事のやりがい：4.1
　・人間関係：3.9
　・給与・待遇：3.2
　・ワークライフバランス：3.7
　・キャリア成長：3.6

3. 改善要望（上位3つ）
　①リモートワークの日数を増やしてほしい（48%）
　②研修・スキルアップの機会を増やしてほしい（35%）
　③評価制度をより透明にしてほしい（28%）

【今後の対応】
・4月からリモートワーク可能日を週2日→3日に拡大
・四半期ごとのスキルアップ研修を新設
・評価基準の明文化と半年ごとの面談を実施

詳細は社内ポータルサイトに掲載しています。',
  'report',
  'N3',
  190,
  '社内アンケート',
  '[{"word":"満足度","reading":"まんぞくど","meaning_ko":"만족도"},{"word":"前年比","reading":"ぜんねんひ","meaning_ko":"전년 대비"},{"word":"待遇","reading":"たいぐう","meaning_ko":"대우"},{"word":"透明","reading":"とうめい","meaning_ko":"투명"},{"word":"明文化","reading":"めいぶんか","meaning_ko":"명문화"}]'::jsonb,
  ARRAY['〜てほしい', '〜ごとの', '〜に掲載しています'],
  '2025년도 사원 만족도 설문조사 결과 보고

실시 기간: 2025년 12월 1일~12월 15일
응답률: 87.3% (대상 254명 중 222명 응답)

【주요 결과】

1. 종합 만족도: 3.8/5.0 (전년 대비 +0.3)
　개선 경향이 보이며 특히 커뮤니케이션 면에서 향상되었습니다.

2. 카테고리별 점수
　・업무 보람: 4.1
　・인간관계: 3.9
　・급여·대우: 3.2
　・워라밸: 3.7
　・커리어 성장: 3.6

3. 개선 요망 (상위 3개)
　①리모트 워크 일수를 늘려 주었으면 (48%)
　②연수·스킬업 기회를 늘려 주었으면 (35%)
　③평가 제도를 더 투명하게 해 주었으면 (28%)

【향후 대응】
・4월부터 리모트 워크 가능일을 주 2일→3일로 확대
・분기별 스킬업 연수 신설
・평가 기준의 명문화와 반기별 면담 실시

상세 내용은 사내 포털사이트에 게재되어 있습니다.',
  37
);

-- N3-20: 外国人の日本での生活体験記 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本で驚いたこと',
  '日本に来て1年が経ちました。韓国と似ている部分もありますが、驚いたことがたくさんあります。

まず、電車の正確さです。韓国の地下鉄も時間通りに来ますが、日本の電車は秒単位で正確です。1分遅れただけで遅延証明書が出ることに驚きました。

次に、ゴミの分別の厳しさです。韓国でもリサイクルはしますが、日本はもっと細かく分けなければなりません。ペットボトルのラベルを剥がして、キャップと本体を別々に捨てるなど、最初は戸惑いました。

また、接客サービスの丁寧さにも感動しました。コンビニでも「いらっしゃいませ」と笑顔で迎えてくれます。ただし、その分、サービス業で働く人の負担は大きいのではないかとも感じます。

最後に、現金文化が根強いことです。韓国ではほとんどカードで支払いますが、日本ではまだ現金のみの店が意外と多いです。最近はキャッシュレスが進んでいますが、完全には浸透していない印象です。

文化の違いを知ることで、自分の国のことも改めて考えるようになりました。',
  'essay',
  'N3',
  200,
  '日本での生活体験',
  '[{"word":"秒単位","reading":"びょうたんい","meaning_ko":"초 단위"},{"word":"分別","reading":"ぶんべつ","meaning_ko":"분별, 분류"},{"word":"戸惑う","reading":"とまどう","meaning_ko":"당혹하다"},{"word":"根強い","reading":"ねづよい","meaning_ko":"뿌리 깊은"},{"word":"浸透","reading":"しんとう","meaning_ko":"침투"}]'::jsonb,
  ARRAY['〜なければならない', '〜のではないか', '〜ようになった'],
  '일본에 온 지 1년이 지났습니다. 한국과 비슷한 부분도 있지만 놀란 것이 많이 있습니다.

먼저 전철의 정확성입니다. 한국 지하철도 시간대로 오지만 일본 전철은 초 단위로 정확합니다. 1분 늦은 것만으로도 지연 증명서가 나오는 것에 놀랐습니다.

다음으로 쓰레기 분류의 엄격함입니다. 한국에서도 재활용을 하지만 일본은 더 세밀하게 분류해야 합니다. 페트병 라벨을 벗기고 뚜껑과 본체를 따로 버리는 등 처음에는 당황했습니다.

또한 접객 서비스의 정중함에도 감동했습니다. 편의점에서도 "어서 오세요"하고 웃는 얼굴로 맞아줍니다. 다만 그만큼 서비스업에서 일하는 사람의 부담이 크지 않을까 하고도 느낍니다.

마지막으로 현금 문화가 뿌리 깊다는 것입니다. 한국에서는 거의 카드로 결제하지만 일본에서는 아직 현금만 되는 가게가 의외로 많습니다. 최근에는 캐시리스가 진행되고 있지만 완전히 침투하지는 않은 인상입니다.

문화의 차이를 아는 것으로 자기 나라에 대해서도 다시 생각하게 되었습니다.',
  38
);

-- N3-21: 転職エージェントの案内 (advertisement)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'IT転職エージェントの案内',
  'IT業界への転職をお考えの方へ

「テックキャリア」は、外国人ITエンジニア専門の転職エージェントです。

【こんな方におすすめ】
・日本のIT企業で働きたい方
・現在の給与に不満がある方
