-- N3-23: 日本のペット事情 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本のペット事情',
  '日本では近年、ペットを飼う人が増えています。特にコロナ禍以降、家で過ごす時間が増えたことで、犬や猫を飼い始めた人が多くなりました。

日本ペットフード協会の調査によると、犬の飼育頭数は約705万頭、猫は約884万頭で、猫が犬を上回っています。猫は散歩の必要がなく、一人暮らしの方でも飼いやすいことが理由の一つです。

日本のペット市場は年間約1.7兆円の規模で、ペット保険やペットホテル、ペット向けの健康食品など、サービスが多様化しています。最近では、ペットと一緒に入れるカフェやレストランも増えています。

一方で、課題もあります。ペットの高齢化に伴い、介護が必要になるケースが増加しています。また、飼育放棄による保護動物の問題も深刻です。自治体や動物保護団体が里親探しに取り組んでいますが、根本的な解決にはペットを飼うことへの責任感をもっと広めていく必要があります。',
  'article',
  'N3',
  190,
  'ペット事情',
  '[{"word":"飼育","reading":"しいく","meaning_ko":"사육"},{"word":"上回る","reading":"うわまわる","meaning_ko":"웃돌다"},{"word":"多様化","reading":"たようか","meaning_ko":"다양화"},{"word":"放棄","reading":"ほうき","meaning_ko":"방기, 포기"},{"word":"里親","reading":"さとおや","meaning_ko":"입양 부모"}]'::jsonb,
  ARRAY['〜によると', '〜に伴い', '〜ていく必要がある'],
  '일본에서는 최근 반려동물을 키우는 사람이 늘고 있습니다. 특히 코로나 이후 집에서 보내는 시간이 늘면서 개나 고양이를 키우기 시작한 사람이 많아졌습니다.

일본 펫푸드 협회의 조사에 따르면 개의 사육 두수는 약 705만 마리, 고양이는 약 884만 마리로 고양이가 개를 웃돌고 있습니다. 고양이는 산책이 필요 없고 1인 가구도 키우기 쉬운 것이 이유 중 하나입니다.

일본의 반려동물 시장은 연간 약 1.7조 엔 규모로 펫 보험, 펫 호텔, 반려동물용 건강식품 등 서비스가 다양화되고 있습니다. 최근에는 반려동물과 함께 들어갈 수 있는 카페나 레스토랑도 늘고 있습니다.

한편 과제도 있습니다. 반려동물의 고령화에 따라 간병이 필요한 케이스가 증가하고 있습니다. 또한 사육 포기에 의한 보호 동물 문제도 심각합니다. 지자체나 동물 보호 단체가 입양처 찾기에 노력하고 있지만 근본적인 해결에는 반려동물을 키우는 것에 대한 책임감을 더 넓혀 나갈 필요가 있습니다.',
  41
);

-- N3-24: シェアハウスの入居案内 (advertisement)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'シェアハウスの入居案内',
  '国際シェアハウス「グローバルハウス中野」入居者募集中！

外国人と日本人が一緒に暮らすシェアハウスです。日本語の練習にも最適な環境です。

