-- N3-25: 外国人向け確定申告ガイド (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '外国人向け確定申告ガイド',
  '外国人のための確定申告ガイド

日本で給料をもらっている外国人の方も、確定申告が必要な場合があります。

【確定申告が必要な人】
・年収が2000万円を超える人
・副業の収入が年間20万円を超える人
・医療費が年間10万円を超えた人（還付が受けられます）
・年の途中で退職し、年末調整を受けていない人

【必要な書類】
・源泉徴収票（会社からもらいます）
・マイナンバーカード（または通知カード＋本人確認書類）
・経費の領収書（副業がある場合）

【申告方法】
1. 国税庁のWebサイトで申告書を作成（日本語のみ）
2. 税務署に直接行く（相談コーナーあり）
3. e-Taxでオンライン申告

申告期間は毎年2月16日〜3月15日です。期限を過ぎると延滞税がかかりますので、早めに準備しましょう。

わからないことがあれば、税務署の無料相談を利用してください。',
  'instruction',
  'N3',
  180,
  '確定申告',
  '[{"word":"確定申告","reading":"かくていしんこく","meaning_ko":"확정 신고"},{"word":"還付","reading":"かんぷ","meaning_ko":"환급"},{"word":"源泉徴収票","reading":"げんせんちょうしゅうひょう","meaning_ko":"원천징수표"},{"word":"税務署","reading":"ぜいむしょ","meaning_ko":"세무서"},{"word":"延滞税","reading":"えんたいぜい","meaning_ko":"연체세"}]'::jsonb,
  ARRAY['〜場合があります', '〜を超える', '〜ので'],
  '외국인을 위한 확정 신고 가이드

일본에서 급여를 받는 외국인도 확정 신고가 필요한 경우가 있습니다.

【확정 신고가 필요한 사람】
・연수입이 2000만 엔을 넘는 사람
・부업 수입이 연간 20만 엔을 넘는 사람
・의료비가 연간 10만 엔을 넘은 사람 (환급을 받을 수 있습니다)
・연도 중간에 퇴직하여 연말 정산을 받지 않은 사람

【필요 서류】
・원천징수표 (회사에서 받습니다)
・마이넘버 카드 (또는 통지카드+본인 확인 서류)
・경비 영수증 (부업이 있는 경우)

【신고 방법】
1. 국세청 웹사이트에서 신고서 작성 (일본어만)
2. 세무서에 직접 방문 (상담 코너 있음)
3. e-Tax로 온라인 신고

신고 기간은 매년 2월 16일~3월 15일입니다. 기한이 지나면 연체세가 부과되므로 일찍 준비합시다.

모르는 것이 있으면 세무서의 무료 상담을 이용해 주세요.',
  43
);

-- N3-26: テクノロジーと教育 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'テクノロジーと教育の未来',
  'テクノロジーの進歩により、教育のあり方が大きく変わりつつあります。

AIを活用した学習アプリは、一人ひとりの理解度に合わせて問題を出題するため、効率的な学習が可能になりました。従来の「全員が同じペースで学ぶ」というスタイルから、個別最適化された学びへと移行しています。

オンライン教育も普及が進んでいます。地方に住んでいても、都市部と同じ質の授業を受けられるようになりました。特に語学学習の分野では、ネイティブスピーカーとのオンラインレッスンが手軽に利用できるようになっています。

一方で、デジタルデバイド（情報格差）の問題も指摘されています。インターネット環境やデバイスを持っていない家庭の子どもたちは、デジタル教育の恩恵を十分に受けられない可能性があります。

また、対面でのコミュニケーションや、実際に手を動かして学ぶ経験の重要性も忘れてはなりません。テクノロジーはあくまでツールであり、それをどう活用するかは人間次第です。',
  'article',
  'N3',
  200,
  'テクノロジーと教育',
  '[{"word":"活用","reading":"かつよう","meaning_ko":"활용"},{"word":"個別","reading":"こべつ","meaning_ko":"개별"},{"word":"普及","reading":"ふきゅう","meaning_ko":"보급"},{"word":"格差","reading":"かくさ","meaning_ko":"격차"},{"word":"恩恵","reading":"おんけい","meaning_ko":"은혜"}]'::jsonb,
  ARRAY['〜つつある', '〜ようになった', '〜てはならない'],
  '테크놀로지의 진보에 의해 교육의 방식이 크게 바뀌고 있습니다.

AI를 활용한 학습 앱은 개개인의 이해도에 맞춰 문제를 출제하기 때문에 효율적인 학습이 가능해졌습니다. 종래의 "모두가 같은 페이스로 배우는" 스타일에서 개별 최적화된 학습으로 이행하고 있습니다.

온라인 교육도 보급이 진행되고 있습니다. 지방에 살고 있어도 도시와 같은 질의 수업을 받을 수 있게 되었습니다. 특히 어학 학습 분야에서는 원어민과의 온라인 레슨을 간편하게 이용할 수 있게 되었습니다.

한편 디지털 디바이드(정보 격차) 문제도 지적되고 있습니다. 인터넷 환경이나 디바이스를 갖고 있지 않은 가정의 아이들은 디지털 교육의 혜택을 충분히 받지 못할 가능성이 있습니다.

또한 대면 커뮤니케이션이나 실제로 손을 움직여 배우는 경험의 중요성도 잊어서는 안 됩니다. 테크놀로지는 어디까지나 도구이며 그것을 어떻게 활용할지는 사람에게 달려 있습니다.',
  44
);

-- N3-27: 就活体験記 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '外国人の就活体験記',
  '外国人として日本で就職活動をした経験をお話しします。

就活を始めたのは大学3年の12月でした。日本の就活は独特で、エントリーシートの提出、Webテスト、グループディスカッション、面接と、いくつもの段階があります。

最も苦労したのはエントリーシートです。「学生時代に力を入れたこと」「あなたの強みと弱み」など、自分のことを日本語で詳しく書く必要がありました。何度も先輩に添削してもらいました。

面接では、日本独特の受け答えに慣れるのが大変でした。例えば、「志望動機」は単に「御社に入りたい」ではなく、その企業のどこに魅力を感じ、自分のスキルをどう活かせるかを具体的に述べなければなりません。

最終的に、IT企業2社から内定をいただきました。就活は大変でしたが、日本のビジネス文化を深く理解する良い機会になりました。外国人留学生の方には、早めの準備とOB訪問をおすすめします。',
  'essay',
  'N3',
  200,
  '就職活動',
  '[{"word":"就職活動","reading":"しゅうしょくかつどう","meaning_ko":"취업 활동"},{"word":"提出","reading":"ていしゅつ","meaning_ko":"제출"},{"word":"志望動機","reading":"しぼうどうき","meaning_ko":"지원 동기"},{"word":"内定","reading":"ないてい","meaning_ko":"내정, 합격 통보"},{"word":"添削","reading":"てんさく","meaning_ko":"첨삭, 교정"}]'::jsonb,
  ARRAY['〜なければならない', '〜てもらう', '〜をおすすめします'],
  '외국인으로서 일본에서 취업 활동을 한 경험을 이야기하겠습니다.

취활을 시작한 것은 대학 3학년 12월이었습니다. 일본의 취활은 독특해서 엔트리시트 제출, 웹 테스트, 그룹 토론, 면접 등 여러 단계가 있습니다.

가장 힘들었던 것은 엔트리시트입니다. "학생 시절 힘을 쏟은 일", "당신의 강점과 약점" 등 자신에 대해 일본어로 상세하게 쓸 필요가 있었습니다. 몇 번이나 선배에게 첨삭을 받았습니다.

면접에서는 일본 특유의 응답에 익숙해지는 것이 힘들었습니다. 예를 들어 "지원 동기"는 단순히 "귀사에 들어가고 싶다"가 아니라 그 기업의 어디에 매력을 느끼고 자신의 스킬을 어떻게 살릴 수 있는지를 구체적으로 말해야 합니다.

최종적으로 IT 기업 2곳에서 내정을 받았습니다. 취활은 힘들었지만 일본의 비즈니스 문화를 깊이 이해하는 좋은 기회가 되었습니다. 외국인 유학생분들에게는 일찍 준비하는 것과 OB 방문을 추천합니다.',
  45
);

-- N3-28: マンション購入vs賃貸 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'マンション購入と賃貸の比較',
  '日本で長く暮らすなら、「家を買うか借りるか」は大きな決断です。それぞれのメリットとデメリットを比較してみましょう。

【購入のメリット】
・資産として残る。ローンを払い終えれば、住居費がなくなる
・自由にリフォームできる
・老後の住まいの心配が減る

【購入のデメリット】
・初期費用が高い（頭金、手数料など）
・固定資産税や管理費がかかる
・転勤や引っ越しがしにくい

【賃貸のメリット】
・初期費用が比較的安い
・引っ越しがしやすい
・修繕費は大家さんの負担

【賃貸のデメリット】
・いくら家賃を払っても自分のものにならない
・更新料が発生する（2年ごとに家賃1か月分が一般的）
・高齢になると借りにくくなる場合がある

外国人の場合、永住権の有無によって住宅ローンの条件が変わることがあります。まずは銀行に相談してみることをおすすめします。',
  'article',
  'N3',
  190,
  '住宅選択',
  '[{"word":"資産","reading":"しさん","meaning_ko":"자산"},{"word":"固定資産税","reading":"こていしさんぜい","meaning_ko":"고정 자산세"},{"word":"修繕費","reading":"しゅうぜんひ","meaning_ko":"수선비"},{"word":"更新料","reading":"こうしんりょう","meaning_ko":"갱신료"},{"word":"永住権","reading":"えいじゅうけん","meaning_ko":"영주권"}]'::jsonb,
  ARRAY['〜なら', '〜てみましょう', '〜場合がある'],
  '일본에서 오래 산다면 "집을 살 것인가 빌릴 것인가"는 큰 결정입니다. 각각의 장단점을 비교해 봅시다.

【구매의 장점】
・자산으로 남는다. 대출을 다 갚으면 주거비가 없어진다
・자유롭게 리폼할 수 있다
・노후 주거 걱정이 줄어든다

【구매의 단점】
・초기 비용이 높다 (계약금, 수수료 등)
・고정 자산세와 관리비가 든다
・전근이나 이사를 하기 어렵다

【임대의 장점】
・초기 비용이 비교적 싸다
・이사하기 쉽다
・수선비는 집주인 부담

【임대의 단점】
・아무리 월세를 내도 자기 것이 되지 않는다
・갱신료가 발생한다 (2년마다 월세 1개월분이 일반적)
・고령이 되면 빌리기 어려워지는 경우가 있다

외국인의 경우 영주권 유무에 따라 주택 대출 조건이 달라질 수 있습니다. 먼저 은행에 상담해 보는 것을 추천합니다.',
  46
);

-- N3-29: 社内勉強会の案内 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '社内勉強会の案内',
  '第8回 社内テック勉強会のお知らせ

今回のテーマ：「TypeScriptで型安全な開発を始めよう」

日時：3月28日（金）18:30〜20:00
場所：本社6階 大会議室（オンライン参加も可）
発表者：開発部 佐藤太郎

【内容】
1. TypeScriptとは？JavaScriptとの違い
2. 型定義の基本（string, number, boolean, interface, type）
3. 実際のプロジェクトでの導入事例
4. よくあるエラーとその解決方法
5. 質疑応答

【対象】
・プログラミングの基礎知識がある方
・TypeScriptに興味がある方
・JavaScript経験者で型の恩恵を知りたい方

参加費無料。飲み物と軽食を用意しています。
前回は35名の参加がありました。席に限りがありますので、参加ご希望の方は3月25日までに社内ポータルからお申し込みください。

勉強会後は希望者で懇親会も予定しています（実費）。',
  'notice',
  'N3',
  180,
  '社内勉強会',
  '[{"word":"型安全","reading":"かたあんぜん","meaning_ko":"타입 세이프"},{"word":"導入事例","reading":"どうにゅうじれい","meaning_ko":"도입 사례"},{"word":"質疑応答","reading":"しつぎおうとう","meaning_ko":"질의응답"},{"word":"懇親会","reading":"こんしんかい","meaning_ko":"친목회"},{"word":"実費","reading":"じっぴ","meaning_ko":"실비"}]'::jsonb,
  ARRAY['〜も可', '〜に限りがある', '〜までに'],
  '제8회 사내 테크 스터디 안내

이번 주제: "TypeScript로 타입 세이프한 개발을 시작하자"

일시: 3월 28일 (금) 18:30~20:00
장소: 본사 6층 대회의실 (온라인 참가도 가능)
발표자: 개발부 사토 타로

【내용】
1. TypeScript란? JavaScript와의 차이점
2. 타입 정의 기본 (string, number, boolean, interface, type)
3. 실제 프로젝트에서의 도입 사례
4. 자주 있는 에러와 해결 방법
5. 질의응답

【대상】
・프로그래밍 기초 지식이 있는 분
・TypeScript에 관심 있는 분
・JavaScript 경험자로 타입의 혜택을 알고 싶은 분

참가비 무료. 음료와 가벼운 음식을 준비합니다.
지난번에는 35명이 참가했습니다. 좌석에 제한이 있으므로 참가를 원하시는 분은 3월 25일까지 사내 포털에서 신청해 주세요.

스터디 후에는 희망자끼리 친목회도 예정하고 있습니다 (실비).',
  47
);

-- N3-30: ボランティア体験記 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '地域ボランティア体験記',
  '先月、地域のボランティア活動に初めて参加しました。外国人の子どもたちに日本語を教えるボランティアです。

毎週土曜日の午前中、公民館に集まって2時間活動します。私が担当したのは、ベトナムから来た小学3年生のリンちゃんです。日本に来てまだ半年で、学校の授業についていくのが大変な状況でした。

最初は教え方がわからず苦労しました。日本語教育の専門知識がないので、どう説明すれば伝わるか試行錯誤の連続でした。しかし、先輩ボランティアからアドバイスをもらい、絵カードを使ったり、ゲーム形式にしたりすることで、楽しみながら学べる工夫を始めました。

3か月が経った今、リンちゃんは学校で友達とおしゃべりできるようになりました。「先生、今日は友達と給食の話をしたよ！」と報告してくれたとき、本当にうれしかったです。

ボランティアを通じて、自分が外国に来たときに感じた不安を思い出しました。言葉が通じない怖さは、誰よりもわかっているつもりです。この経験を活かして、これからも活動を続けていきたいと思います。',
  'essay',
  'N3',
  220,
  'ボランティア体験',
  '[{"word":"公民館","reading":"こうみんかん","meaning_ko":"공민관"},{"word":"試行錯誤","reading":"しこうさくご","meaning_ko":"시행착오"},{"word":"工夫","reading":"くふう","meaning_ko":"궁리, 연구"},{"word":"通じる","reading":"つうじる","meaning_ko":"통하다"},{"word":"活かす","reading":"いかす","meaning_ko":"살리다"}]'::jsonb,
  ARRAY['〜ようになった', '〜てくれた', '〜ていきたい'],
  '지난달 지역 봉사활동에 처음 참가했습니다. 외국인 아이들에게 일본어를 가르치는 봉사입니다.

매주 토요일 오전에 공민관에 모여 2시간 활동합니다. 제가 담당한 것은 베트남에서 온 초등학교 3학년 린 양입니다. 일본에 온 지 아직 반년으로 학교 수업을 따라가는 것이 힘든 상황이었습니다.

처음에는 가르치는 방법을 몰라서 고생했습니다. 일본어 교육 전문 지식이 없어서 어떻게 설명하면 전달될지 시행착오의 연속이었습니다. 하지만 선배 봉사자에게 조언을 받아 그림 카드를 사용하거나 게임 형식으로 하거나 하면서 즐기면서 배울 수 있는 방법을 시작했습니다.

3개월이 지난 지금 린 양은 학교에서 친구와 수다를 떨 수 있게 되었습니다. "선생님, 오늘은 친구와 급식 이야기를 했어요!"라고 보고해 줬을 때 정말 기뻤습니다.

봉사를 통해 자신이 외국에 왔을 때 느꼈던 불안을 떠올렸습니다. 말이 통하지 않는 무서움은 누구보다 알고 있다고 생각합니다. 이 경험을 살려서 앞으로도 활동을 계속해 나가고 싶다고 생각합니다.',
  48
);

