-- N2-10: アジャイル開発とウォーターフォール (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'アジャイル開発とウォーターフォール開発の比較',
  'ソフトウェア開発における手法として、アジャイル開発とウォーターフォール開発が広く知られている。それぞれに特徴があり、プロジェクトの性質によって適切な手法を選択することが重要である。

ウォーターフォール開発は、要件定義、設計、実装、テスト、運用という工程を順番に進める手法である。全体の計画を最初に立てるため、スケジュールやコストの見通しが立てやすい。官公庁や金融機関など、仕様変更が少なく、品質基準が厳格なプロジェクトに向いている。

一方、アジャイル開発は、短い開発サイクル（スプリント）を繰り返しながら、少しずつ機能を追加していく手法である。顧客のフィードバックを素早く取り入れられるため、要件が変わりやすいWebサービスやスタートアップ企業のプロジェクトに適している。

近年の日本のIT業界では、アジャイル開発の採用が増えている。しかし、日本特有の「合意形成」を重視する文化との相性に課題を感じる企業も少なくない。両手法のメリットを組み合わせたハイブリッド型のアプローチを取る企業も増えつつある。',
  'article',
  'N2',
  240,
  'ソフトウェア開発手法',
  '[{"word":"手法","reading":"しゅほう","meaning_ko":"수법, 방법론"},{"word":"要件定義","reading":"ようけんていぎ","meaning_ko":"요건 정의"},{"word":"工程","reading":"こうてい","meaning_ko":"공정"},{"word":"合意形成","reading":"ごういけいせい","meaning_ko":"합의 형성"},{"word":"相性","reading":"あいしょう","meaning_ko":"궁합"}]'::jsonb,
  ARRAY['〜において', '〜に向いている', '〜つつある'],
  '소프트웨어 개발 방법론으로 애자일 개발과 워터폴 개발이 널리 알려져 있다. 각각 특징이 있으며 프로젝트의 성격에 따라 적절한 방법론을 선택하는 것이 중요하다.

워터폴 개발은 요건 정의, 설계, 구현, 테스트, 운용이라는 공정을 순서대로 진행하는 방법이다. 전체 계획을 처음에 세우기 때문에 일정이나 비용의 전망을 세우기 쉽다. 관공청이나 금융기관 등 사양 변경이 적고 품질 기준이 엄격한 프로젝트에 적합하다.

한편 애자일 개발은 짧은 개발 사이클(스프린트)을 반복하면서 조금씩 기능을 추가해 나가는 방법이다. 고객의 피드백을 빠르게 반영할 수 있어 요건이 변하기 쉬운 웹 서비스나 스타트업 기업의 프로젝트에 적합하다.

최근 일본 IT 업계에서는 애자일 개발의 채용이 늘고 있다. 그러나 일본 특유의 "합의 형성"을 중시하는 문화와의 궁합에 과제를 느끼는 기업도 적지 않다. 양 방법론의 장점을 조합한 하이브리드형 접근법을 취하는 기업도 늘고 있다.',
  37
);

-- N2-11: 日本企業における外国人エンジニアの現状 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本企業における外国人エンジニアの現状',
  '経済産業省の推計によれば、2030年には日本のIT人材が最大79万人不足するとされている。この深刻な人材不足を補うため、外国人ITエンジニアの採用が加速している。

現在、日本で働く外国人ITエンジニアは約5万人と推定され、その多くは中国、インド、ベトナム、韓国出身である。彼らが日本企業を選ぶ理由として、技術力の高さ、安定した雇用環境、そして治安の良さが挙げられる。

しかし、外国人エンジニアが直面する課題も多い。最も大きいのは言語の壁である。技術的なコミュニケーションは英語で可能でも、社内の会議や日常のやり取りは日本語が中心であり、情報格差が生じやすい。

また、日本特有の「暗黙の了解」に基づくコミュニケーションスタイルも障壁となっている。明確な指示よりも「空気を読む」ことが求められる場面に戸惑う外国人は少なくない。

先進的な企業では、社内文書の多言語化、メンター制度の導入、異文化理解研修の実施などの対策を講じている。外国人エンジニアの定着率を高めることは、企業の国際競争力の強化にも直結する重要な課題であると言えよう。',
  'report',
  'N2',
  260,
  '外国人エンジニアの現状',
  '[{"word":"推計","reading":"すいけい","meaning_ko":"추계"},{"word":"雇用","reading":"こよう","meaning_ko":"고용"},{"word":"暗黙の了解","reading":"あんもくのりょうかい","meaning_ko":"암묵적 양해"},{"word":"障壁","reading":"しょうへき","meaning_ko":"장벽"},{"word":"定着率","reading":"ていちゃくりつ","meaning_ko":"정착률"}]'::jsonb,
  ARRAY['〜によれば', '〜とされている', '〜と言えよう'],
  '경제산업성의 추계에 따르면 2030년에는 일본의 IT 인재가 최대 79만 명 부족할 것으로 되어 있다. 이 심각한 인재 부족을 보충하기 위해 외국인 IT 엔지니어의 채용이 가속화되고 있다.

현재 일본에서 일하는 외국인 IT 엔지니어는 약 5만 명으로 추정되며 그 대부분은 중국, 인도, 베트남, 한국 출신이다. 그들이 일본 기업을 선택하는 이유로 기술력의 높음, 안정된 고용 환경, 그리고 치안의 좋음이 꼽힌다.

그러나 외국인 엔지니어가 직면하는 과제도 많다. 가장 큰 것은 언어의 장벽이다. 기술적 커뮤니케이션은 영어로 가능해도 사내 회의나 일상적 소통은 일본어가 중심이어서 정보 격차가 생기기 쉽다.

또한 일본 특유의 "암묵적 양해"에 기반한 커뮤니케이션 스타일도 장벽이 되고 있다. 명확한 지시보다 "분위기를 읽는 것"이 요구되는 상황에 당혹하는 외국인이 적지 않다.

선진적인 기업에서는 사내 문서의 다국어화, 멘토 제도 도입, 이문화 이해 연수 실시 등의 대책을 강구하고 있다. 외국인 엔지니어의 정착률을 높이는 것은 기업의 국제 경쟁력 강화에도 직결하는 중요한 과제라고 할 수 있을 것이다.',
  38
);

-- N2-12: 情報セキュリティポリシー (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '情報セキュリティポリシー',
  '株式会社テックブリッジ 情報セキュリティポリシー（抜粋）

1. 目的
本ポリシーは、当社が保有する情報資産を適切に保護し、情報セキュリティに関するリスクを最小限に抑えることを目的とする。

2. パスワード管理
・パスワードは12文字以上とし、英数字・記号を組み合わせること
・90日ごとにパスワードを変更すること
・同一のパスワードを複数のサービスで使い回さないこと
・パスワードを付箋に書いてディスプレイに貼る等の行為を禁止する

3. データの取り扱い
・機密情報を含むファイルにはパスワードを設定すること
・USBメモリ等の外部記憶媒体の使用は原則禁止とする
・業務データをクラウドストレージに保存する際は、会社指定のサービスのみ使用可

4. インシデント対応
・情報漏洩が疑われる場合は、直ちにセキュリティ担当者に報告すること
・不審なメールを受信した場合は、開封せずに情報システム部に転送すること

5. 罰則
本ポリシーに違反した場合、懲戒処分の対象となることがある。',
  'instruction',
  'N2',
  240,
  '情報セキュリティ',
  '[{"word":"情報資産","reading":"じょうほうしさん","meaning_ko":"정보 자산"},{"word":"機密","reading":"きみつ","meaning_ko":"기밀"},{"word":"漏洩","reading":"ろうえい","meaning_ko":"유출"},{"word":"懲戒処分","reading":"ちょうかいしょぶん","meaning_ko":"징계 처분"},{"word":"抜粋","reading":"ばっすい","meaning_ko":"발췌"}]'::jsonb,
  ARRAY['〜を目的とする', '〜こと（義務）', '〜となることがある'],
  '주식회사 테크브릿지 정보 보안 정책 (발췌)

1. 목적
본 정책은 당사가 보유한 정보 자산을 적절히 보호하고 정보 보안에 관한 리스크를 최소한으로 억제하는 것을 목적으로 한다.

2. 비밀번호 관리
・비밀번호는 12자 이상으로 영숫자·기호를 조합할 것
・90일마다 비밀번호를 변경할 것
・동일한 비밀번호를 여러 서비스에서 재사용하지 않을 것
・비밀번호를 포스트잇에 써서 모니터에 붙이는 등의 행위를 금지한다

3. 데이터 취급
・기밀 정보를 포함한 파일에는 비밀번호를 설정할 것
・USB 메모리 등 외부 저장 매체의 사용은 원칙 금지로 한다
・업무 데이터를 클라우드 스토리지에 저장할 시 회사 지정 서비스만 사용 가능

4. 인시던트 대응
・정보 유출이 의심되는 경우 즉시 보안 담당자에게 보고할 것
・수상한 메일을 수신한 경우 열지 말고 정보시스템부에 전송할 것

5. 벌칙
본 정책을 위반한 경우 징계 처분의 대상이 될 수 있다.',
  39
);

-- N2-13: AIと著作権の問題 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'AIと著作権の問題',
  '生成AIの急速な発展に伴い、著作権をめぐる議論が世界中で活発化している。AIが既存の著作物を学習データとして利用することの合法性、そしてAIが生成したコンテンツの著作権の帰属について、法的な枠組みの整備が急がれている。

日本の著作権法第30条の4では、情報解析のための著作物の利用は原則として著作権者の許諾なく行えるとされている。この規定は、AIの学習に関しては世界的にも比較的寛容なものとして注目されてきた。

しかし、AIが特定のアーティストのスタイルを模倣した作品を大量に生成するケースが問題視されるようになった。技術的には合法であっても、クリエイターの経済的利益や創作意欲を損なう可能性があるという懸念は無視できない。

この問題に対する各国のアプローチは異なる。EUはAI規制法を制定し、学習データの透明性を義務づける方向で動いている。一方、米国では裁判を通じた判例の蓄積によってルール形成が進められている。

技術の進歩とクリエイターの権利保護のバランスをどう取るかは、今後のデジタル社会における最も重要な課題の一つである。',
  'article',
  'N2',
  260,
  'AIと著作権',
  '[{"word":"著作権","reading":"ちょさくけん","meaning_ko":"저작권"},{"word":"帰属","reading":"きぞく","meaning_ko":"귀속"},{"word":"寛容","reading":"かんよう","meaning_ko":"관용"},{"word":"模倣","reading":"もほう","meaning_ko":"모방"},{"word":"判例","reading":"はんれい","meaning_ko":"판례"}]'::jsonb,
  ARRAY['〜に伴い', '〜とされている', '〜ざるを得ない'],
  '생성 AI의 급속한 발전에 따라 저작권을 둘러싼 논의가 전 세계에서 활발해지고 있다. AI가 기존 저작물을 학습 데이터로 이용하는 것의 합법성, 그리고 AI가 생성한 콘텐츠의 저작권 귀속에 대해 법적 프레임워크 정비가 시급하다.

일본 저작권법 제30조의 4에서는 정보 분석을 위한 저작물의 이용은 원칙적으로 저작권자의 허락 없이 할 수 있다고 되어 있다. 이 규정은 AI의 학습에 관해서는 세계적으로도 비교적 관대한 것으로 주목받아 왔다.

그러나 AI가 특정 아티스트의 스타일을 모방한 작품을 대량으로 생성하는 케이스가 문제시되고 있다. 기술적으로는 합법이라 해도 크리에이터의 경제적 이익이나 창작 의욕을 해칠 가능성이 있다는 우려는 무시할 수 없다.

이 문제에 대한 각국의 접근법은 다르다. EU는 AI 규제법을 제정하여 학습 데이터의 투명성을 의무화하는 방향으로 움직이고 있다. 한편 미국에서는 재판을 통한 판례 축적에 의해 규칙 형성이 진행되고 있다.

기술의 진보와 크리에이터의 권리 보호의 밸런스를 어떻게 잡을 것인가는 향후 디지털 사회에서 가장 중요한 과제 중 하나이다.',
  40
);

-- N2-14: ビジネスメール：取引先への提案 (email)
