-- N2-15: 日本の少子高齢化問題 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の少子高齢化問題',
  '日本は世界で最も少子高齢化が進んだ国の一つである。2024年の出生数は約70万人と過去最少を更新し、合計特殊出生率は1.20まで低下した。65歳以上の高齢者は総人口の約29%を占めるに至っている。

少子化の背景には複合的な要因がある。若者の経済的不安定さ、長時間労働による育児との両立困難、教育費の高騰、そして結婚に対する価値観の多様化などが指摘されている。特に東京を中心とした都市部では、住居費の高さが子育て世代の大きな負担となっている。

政府は様々な対策を講じてきた。児童手当の拡充、保育施設の整備、育児休業制度の充実などである。2023年には「こども家庭庁」が新設され、子育て支援策の司令塔としての役割を担うことになった。

しかし、これまでの対策は出生率の回復に十分な効果をもたらしていないのが現実である。フランスや北欧諸国のように出生率を回復させた国々は、経済的支援だけでなく、社会全体で子育てを支える意識改革を伴っていた。

日本においても、制度面の整備に加え、長時間労働の是正や男性の育児参加の促進など、社会構造そのものの変革が不可欠であろう。',
  'essay',
  'N2',
  280,
  '少子高齢化',
  '[{"word":"合計特殊出生率","reading":"ごうけいとくしゅしゅっしょうりつ","meaning_ko":"합계특수출생률"},{"word":"両立","reading":"りょうりつ","meaning_ko":"양립"},{"word":"高騰","reading":"こうとう","meaning_ko":"고등, 급등"},{"word":"拡充","reading":"かくじゅう","meaning_ko":"확충"},{"word":"不可欠","reading":"ふかけつ","meaning_ko":"불가결"}]'::jsonb,
  ARRAY['〜に至っている', '〜をもたらす', '〜であろう'],
  '일본은 세계에서 가장 저출산 고령화가 진행된 나라 중 하나이다. 2024년 출생 수는 약 70만 명으로 역대 최저를 경신했으며 합계특수출생률은 1.20까지 하락했다. 65세 이상 고령자는 총인구의 약 29%를 차지하기에 이르렀다.

저출산의 배경에는 복합적 요인이 있다. 젊은이의 경제적 불안정, 장시간 노동에 의한 육아와의 양립 곤란, 교육비 급등, 그리고 결혼에 대한 가치관의 다양화 등이 지적되고 있다. 특히 도쿄를 중심으로 한 도시부에서는 주거비의 높음이 육아 세대의 큰 부담이 되고 있다.

정부는 다양한 대책을 강구해 왔다. 아동 수당 확충, 보육 시설 정비, 육아 휴직 제도 충실 등이다. 2023년에는 "어린이가정청"이 신설되어 육아 지원책의 사령탑 역할을 맡게 되었다.

그러나 지금까지의 대책은 출생률 회복에 충분한 효과를 가져오지 못하고 있는 것이 현실이다. 프랑스나 북유럽 국가들처럼 출생률을 회복시킨 나라들은 경제적 지원뿐만 아니라 사회 전체에서 육아를 지지하는 의식 개혁을 수반하고 있었다.

일본에서도 제도면의 정비에 더해 장시간 노동의 시정이나 남성의 육아 참가 촉진 등 사회 구조 자체의 변혁이 불가결할 것이다.',
  42
);

-- N2-16: クラウドサービス導入報告書 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'クラウドサービス導入報告書',
  '社内クラウドサービス導入プロジェクト 完了報告書

1. プロジェクト概要
オンプレミスで運用していた社内システムをAWSクラウドに移行するプロジェクト。2025年10月に着手し、2026年1月に完了した。

2. 導入成果
・サーバー運用コスト：年間約1,200万円の削減（40%減）
・システム可用性：99.95%→99.99%に向上
・デプロイ頻度：月1回→週2回に増加
・障害復旧時間：平均4時間→30分に短縮

3. 発生した課題と対応
・データ移行中に一部のデータ不整合が発生（原因：文字コードの差異）→ 移行スクリプトを修正し、検証環境で再テスト後に本番移行を実施
・既存のVPN接続設定の変更が必要であった → 情報システム部と連携し、全社員のPC設定を更新

4. 今後の課題
・マルチリージョン構成によるさらなる冗長性の確保
・コスト最適化のための未使用リソースの定期的な棚卸し
・社内エンジニアのクラウドスキル向上（AWS認定資格の取得推奨）

以上',
  'report',
  'N2',
  250,
  'クラウド導入報告',
  '[{"word":"可用性","reading":"かようせい","meaning_ko":"가용성"},{"word":"障害","reading":"しょうがい","meaning_ko":"장애"},{"word":"復旧","reading":"ふっきゅう","meaning_ko":"복구"},{"word":"冗長性","reading":"じょうちょうせい","meaning_ko":"이중화, 리던던시"},{"word":"棚卸し","reading":"たなおろし","meaning_ko":"재고 조사"}]'::jsonb,
  ARRAY['〜に着手する', '〜に向上する', '〜によるさらなる'],
  '사내 클라우드 서비스 도입 프로젝트 완료 보고서

1. 프로젝트 개요
온프레미스에서 운용하던 사내 시스템을 AWS 클라우드로 이관하는 프로젝트. 2025년 10월에 착수하여 2026년 1월에 완료.

2. 도입 성과
・서버 운용 비용: 연간 약 1,200만 엔 삭감 (40% 감)
・시스템 가용성: 99.95%→99.99%로 향상
・디플로이 빈도: 월 1회→주 2회로 증가
・장애 복구 시간: 평균 4시간→30분으로 단축

3. 발생한 과제와 대응
・데이터 이관 중 일부 데이터 불일치 발생 (원인: 문자 코드 차이) → 이관 스크립트를 수정하고 검증 환경에서 재테스트 후 본번 이관 실시
・기존 VPN 접속 설정 변경이 필요했음 → 정보시스템부와 연계하여 전 사원 PC 설정 업데이트

4. 향후 과제
・멀티 리전 구성에 의한 추가적인 이중화 확보
・비용 최적화를 위한 미사용 리소스의 정기적 점검
・사내 엔지니어의 클라우드 스킬 향상 (AWS 인증 자격 취득 권장)

이상',
  43
);

-- N2-17: 日本のスタートアップ生態系 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本のスタートアップ・エコシステム',
  '日本のスタートアップ・エコシステムは、近年大きな転換期を迎えている。政府は2022年を「スタートアップ創出元年」と位置づけ、5年間で10万社のスタートアップ創出を目標に掲げた。

日本のスタートアップ投資額は年間約8,000億円と、米国の約40兆円や中国の約10兆円と比較すると依然として小規模である。しかし、その成長率は著しく、5年前と比べて約3倍に拡大している。

特に注目すべきは、SaaS、フィンテック、ヘルステック分野でのイノベーションである。レガシーシステムからの脱却が遅れている日本の大企業にとって、これらの分野のスタートアップとの協業は、デジタルトランスフォーメーションを加速させる有力な手段となっている。

課題としては、リスクを取ることに対する文化的な抵抗感がある。終身雇用の伝統が根強い日本では、安定した大企業を辞めてスタートアップに挑戦することへの心理的ハードルが高い。また、失敗に対する社会的なスティグマも、起業家精神の醸成を妨げる要因となっている。

エコシステムの成熟には時間を要するが、大学発ベンチャーの増加や、大企業からの人材流出の活発化など、変化の兆しは確実に表れている。',
  'article',
  'N2',
  270,
  'スタートアップ',
  '[{"word":"転換期","reading":"てんかんき","meaning_ko":"전환기"},{"word":"協業","reading":"きょうぎょう","meaning_ko":"협업"},{"word":"抵抗感","reading":"ていこうかん","meaning_ko":"저항감"},{"word":"醸成","reading":"じょうせい","meaning_ko":"양성, 조성"},{"word":"兆し","reading":"きざし","meaning_ko":"조짐"}]'::jsonb,
  ARRAY['〜と位置づけ', '〜に比べて', '〜を要する'],
  '일본의 스타트업 에코시스템은 최근 큰 전환기를 맞이하고 있다. 정부는 2022년을 "스타트업 창출 원년"으로 자리매김하고 5년간 10만 사의 스타트업 창출을 목표로 내걸었다.

일본의 스타트업 투자액은 연간 약 8,000억 엔으로 미국의 약 40조 엔이나 중국의 약 10조 엔과 비교하면 여전히 소규모이다. 그러나 그 성장률은 현저하며 5년 전에 비해 약 3배로 확대되었다.

특히 주목해야 할 것은 SaaS, 핀테크, 헬스테크 분야에서의 혁신이다. 레거시 시스템으로부터의 탈각이 늦어지고 있는 일본 대기업에게 이들 분야의 스타트업과의 협업은 디지털 트랜스포메이션을 가속시키는 유력한 수단이 되고 있다.

과제로는 리스크를 감수하는 것에 대한 문화적 저항감이 있다. 종신고용의 전통이 뿌리 깊은 일본에서는 안정된 대기업을 그만두고 스타트업에 도전하는 것에 대한 심리적 허들이 높다. 또한 실패에 대한 사회적 낙인도 기업가 정신의 양성을 방해하는 요인이 되고 있다.

에코시스템의 성숙에는 시간이 필요하지만 대학발 벤처의 증가나 대기업으로부터의 인재 유출 활성화 등 변화의 조짐은 확실히 나타나고 있다.',
  44
);

-- N2-18: 職場のメンタルヘルス対策 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '職場のメンタルヘルス対策',
  '社員のみなさまへ — メンタルヘルスケアのご案内

当社は社員の心身の健康を経営の最重要課題の一つと位置づけ、以下のメンタルヘルス対策を実施しております。

【ストレスチェック制度】
年1回のストレスチェックを全社員に実施しています。結果は個人に直接通知され、会社には本人の同意なく開示されることはありません。高ストレス者には産業医との面談を推奨しています。

【相談窓口】
・産業医面談：毎月第2・第4水曜日（予約制）
・社外カウンセリング：電話・オンラインで24時間対応（費用は会社負担）
・ハラスメント相談窓口：人事部（匿名での相談も可能）

【セルフケアのポイント】
・十分な睡眠を確保する（7〜8時間が目安）
・定期的な運動を心がける
・一人で抱え込まず、周囲に相談する
・有給休暇を計画的に取得する

心の不調は、早期に対処することが重要です。「少し疲れたな」と感じたら、遠慮なく相談窓口をご利用ください。

人事部 健康管理室',
  'notice',
  'N2',
  240,
  'メンタルヘルス',
  '[{"word":"産業医","reading":"さんぎょうい","meaning_ko":"산업의"},{"word":"開示","reading":"かいじ","meaning_ko":"공개"},{"word":"匿名","reading":"とくめい","meaning_ko":"익명"},{"word":"抱え込む","reading":"かかえこむ","meaning_ko":"혼자 떠안다"},{"word":"遠慮なく","reading":"えんりょなく","meaning_ko":"사양 없이"}]'::jsonb,
  ARRAY['〜と位置づけ', '〜ことはありません', '〜ことが重要です'],
  '사원 여러분에게 — 정신 건강 관리 안내

당사는 사원의 심신 건강을 경영의 최중요 과제 중 하나로 자리매김하고 아래의 정신 건강 대책을 실시하고 있습니다.

【스트레스 체크 제도】
연 1회 스트레스 체크를 전 사원에게 실시합니다. 결과는 개인에게 직접 통지되며 회사에는 본인의 동의 없이 공개되지 않습니다. 고스트레스자에게는 산업의와의 면담을 권장합니다.

【상담 창구】
・산업의 면담: 매월 2·4번째 수요일 (예약제)
・사외 카운슬링: 전화·온라인 24시간 대응 (비용은 회사 부담)
・괴롭힘 상담 창구: 인사부 (익명 상담도 가능)

【셀프 케어 포인트】
・충분한 수면 확보 (7~8시간이 기준)
・정기적 운동을 마음에 두기
・혼자 떠안지 말고 주위에 상담하기
・유급 휴가를 계획적으로 취득하기

마음의 부조는 조기에 대처하는 것이 중요합니다. "좀 피곤하다"고 느끼면 사양 없이 상담 창구를 이용해 주세요.

인사부 건강관리실',
  45
);

-- N2-19: データプライバシーと個人情報保護 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'データプライバシーと個人情報保護',
  'デジタル化の進展に伴い、個人情報の取り扱いに対する社会的関心が高まっている。日本の個人情報保護法は2003年に制定されて以来、幾度かの改正を経て、現在では事業者に対して厳格な義務を課している。

2022年の改正では、個人情報の漏洩が発生した場合の個人情報保護委員会への報告義務化や、不正利用に対する罰則の強化が盛り込まれた。また、本人の請求による個人データの利用停止・消去権も拡充された。

ITエンジニアにとって、この法律の理解は不可欠である。システム設計の段階から「プライバシー・バイ・デザイン」の原則を取り入れ、必要最小限のデータのみを収集し、適切なアクセス制御を実装することが求められる。

クッキー規制やGDPRなど、海外の規制動向にも注意を払う必要がある。グローバルにサービスを展開する企業は、各国の法規制に準拠したデータ処理を行わなければならない。

技術者の倫理観と法的知識の両方が、デジタル社会の信頼性を支える基盤となるのである。',
  'article',
  'N2',
  250,
  'データプライバシー',
  '[{"word":"制定","reading":"せいてい","meaning_ko":"제정"},{"word":"罰則","reading":"ばっそく","meaning_ko":"벌칙"},{"word":"拡充","reading":"かくじゅう","meaning_ko":"확충"},{"word":"準拠","reading":"じゅんきょ","meaning_ko":"준거"},{"word":"基盤","reading":"きばん","meaning_ko":"기반"}]'::jsonb,
  ARRAY['〜を経て', '〜なければならない', '〜のである'],
  '디지털화의 진전에 따라 개인정보 취급에 대한 사회적 관심이 높아지고 있다. 일본의 개인정보보호법은 2003년에 제정된 이래 여러 차례 개정을 거쳐 현재는 사업자에게 엄격한 의무를 부과하고 있다.

2022년 개정에서는 개인정보 유출이 발생한 경우 개인정보보호위원회에의 보고 의무화나 부정 이용에 대한 벌칙 강화가 포함되었다. 또한 본인의 청구에 의한 개인 데이터의 이용 정지·삭제권도 확충되었다.

IT 엔지니어에게 이 법률의 이해는 불가결하다. 시스템 설계 단계부터 "프라이버시 바이 디자인" 원칙을 도입하고 필요 최소한의 데이터만 수집하며 적절한 접근 제어를 구현하는 것이 요구된다.

쿠키 규제나 GDPR 등 해외의 규제 동향에도 주의를 기울일 필요가 있다. 글로벌하게 서비스를 전개하는 기업은 각국의 법규제에 준거한 데이터 처리를 해야 한다.

기술자의 윤리관과 법적 지식 양쪽이 디지털 사회의 신뢰성을 지지하는 기반이 되는 것이다.',
  46
);

-- N2-20: 日本の鉄道文化 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の鉄道文化と技術',
  '日本の鉄道は、その正確さ、安全性、技術力において世界的に高い評価を受けている。新幹線の開業以来60年間で死亡事故ゼロという記録は、日本の鉄道技術の象徴的な成果である。

東海道新幹線は1日あたり約170本が運行され、平均遅延時間はわずか約0.9分である。この驚異的な定時運行率を支えているのは、高度な運行管理システム、徹底した保守点検体制、そして運転士や車掌の高い職業意識である。

鉄道は日本人の生活インフラとして深く根づいている。首都圏では1日に約4,000万人が鉄道を利用し、通勤ラッシュ時の混雑率は180%を超える路線もある。この過密な輸送を破綻なく運営する運行管理能力は、各国の鉄道関係者から注目されている。

一方、鉄道業界も変革を迫られている。人口減少に伴う利用者の減少、運転士の高齢化と人手不足、老朽化したインフラの維持費用の増大などが課題である。JR各社はこれらの課題に対し、自動運転技術の開発、MaaS（Mobility as a Service）の推進、駅ナカビジネスの拡大などで対応を図っている。',
  'essay',
  'N2',
  260,
  '鉄道文化と技術',
  '[{"word":"定時運行率","reading":"ていじうんこうりつ","meaning_ko":"정시 운행률"},{"word":"保守点検","reading":"ほしゅてんけん","meaning_ko":"보수 점검"},{"word":"破綻","reading":"はたん","meaning_ko":"파탄"},{"word":"老朽化","reading":"ろうきゅうか","meaning_ko":"노후화"},{"word":"自動運転","reading":"じどううんてん","meaning_ko":"자율 주행"}]'::jsonb,
  ARRAY['〜において', '〜に伴う', '〜を図っている'],
  '일본의 철도는 그 정확성, 안전성, 기술력에서 세계적으로 높은 평가를 받고 있다. 신칸센 개업 이래 60년간 사망사고 제로라는 기록은 일본 철도 기술의 상징적 성과이다.

도카이도 신칸센은 하루 약 170편이 운행되며 평균 지연 시간은 겨우 약 0.9분이다. 이 경이적인 정시 운행률을 지탱하는 것은 고도의 운행 관리 시스템, 철저한 보수 점검 체제, 그리고 운전사와 차장의 높은 직업 의식이다.

철도는 일본인의 생활 인프라로 깊이 뿌리내리고 있다. 수도권에서는 하루에 약 4,000만 명이 철도를 이용하며 통근 러시 시 혼잡률이 180%를 넘는 노선도 있다. 이 과밀한 수송을 파탄 없이 운영하는 운행 관리 능력은 각국의 철도 관계자로부터 주목받고 있다.

한편 철도 업계도 변혁을 강요받고 있다. 인구 감소에 따른 이용자 감소, 운전사의 고령화와 인력 부족, 노후화된 인프라 유지비 증대 등이 과제이다. JR 각사는 이러한 과제에 대해 자율 주행 기술 개발, MaaS 추진, 역 내부 비즈니스 확대 등으로 대응을 도모하고 있다.',
  47
);

-- N2-21: 外国人社員への評価面談フィードバック (email)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '評価面談フィードバック',
  '件名：2025年下期 評価面談フィードバック

パクさん

先日の評価面談、お疲れ様でした。面談の内容を以下にまとめましたので、ご確認ください。

【総合評価】B+（期待を上回る成果）

【評価のポイント】
1. 技術力（A評価）
・TypeScriptへのリファクタリングを主導し、コードの保守性を大幅に向上させた
・テストカバレッジを45%から78%に引き上げた貢献は特筆に値する

2. コミュニケーション（B評価）
・チーム内での技術的な議論への参加が積極的になった
・改善点：会議での発言がまだ少ない。日本語の敬語に自信がなくても、積極的に意見を述べてほしい

3. チームワーク（A評価）
・後輩エンジニアへのメンタリングを自発的に行っている点は高く評価したい

【今後の期待】
・リーダーシップのさらなる発揮を期待する
・設計フェーズからの参画を増やしてほしい

不明な点があれば、いつでも相談してください。

開発部 山田課長',
  'email',
  'N2',
  230,
  '評価面談',
  '[{"word":"下期","reading":"しもき","meaning_ko":"하반기"},{"word":"保守性","reading":"ほしゅせい","meaning_ko":"유지보수성"},{"word":"特筆に値する","reading":"とくひつにあたいする","meaning_ko":"특필할 가치가 있다"},{"word":"自発的","reading":"じはつてき","meaning_ko":"자발적"},{"word":"参画","reading":"さんかく","meaning_ko":"참획, 참여"}]'::jsonb,
  ARRAY['〜に値する', '〜てほしい', '〜を期待する'],
  '제목: 2025년 하반기 평가 면담 피드백

박 씨

일전 평가 면담 수고하셨습니다. 면담 내용을 아래에 정리했으니 확인해 주세요.

【종합 평가】B+ (기대를 웃도는 성과)

【평가 포인트】
1. 기술력 (A 평가)
・TypeScript로의 리팩토링을 주도하여 코드의 유지보수성을 대폭 향상시킴
・테스트 커버리지를 45%에서 78%로 끌어올린 공헌은 특필할 가치가 있음

2. 커뮤니케이션 (B 평가)
・팀 내 기술적 논의 참여가 적극적이 됨
・개선점: 회의에서의 발언이 아직 적다. 일본어 경어에 자신이 없더라도 적극적으로 의견을 말해 주었으면 함

3. 팀워크 (A 평가)
・후배 엔지니어에 대한 멘토링을 자발적으로 하고 있는 점을 높이 평가하고 싶음

【향후 기대】
・리더십의 더한 발휘를 기대함
・설계 페이즈부터의 참여를 늘려 주었으면 함

불명확한 점이 있으면 언제든 상담해 주세요.

개발부 야마다 과장',
  48
);

-- N2-22: 日本語の敬語体系 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語の敬語体系',
  '日本語の敬語は、社会的関係性を言語で表現する精緻な体系である。文化庁の分類では、敬語は尊敬語、謙譲語I、謙譲語II（丁重語）、丁寧語、美化語の5種類に分けられる。

尊敬語は相手の行為を高める表現であり、「いらっしゃる」「おっしゃる」「ご覧になる」などがある。謙譲語Iは自分の行為を低めることで相手を立てる表現で、「参る」「申す」「拝見する」などである。

ビジネスの場面では、社内と社外で敬語の使い方が変わる点が、外国人にとって特に難しい。例えば、自社の上司について社外の人に話す場合、「部長の山田は出張中です」のように敬称を付けず、尊敬語も使わない。これは日本の「ウチとソト」の概念に基づいている。

近年は敬語の簡略化が進み、「させていただく」の過剰使用が問題視されることもある。本来は相手の許可を得て行う行為に使う表現だが、「発表させていただきます」のように、許可を必要としない場面でも多用される傾向にある。

正しい敬語の運用は一朝一夕には身につかないが、相手への敬意を言葉で表現しようとする姿勢こそが最も重要なのではないだろうか。',
  'article',
  'N2',
  260,
  '日本語の敬語',
  '[{"word":"精緻","reading":"せいち","meaning_ko":"정치, 정밀"},{"word":"謙譲語","reading":"けんじょうご","meaning_ko":"겸양어"},{"word":"簡略化","reading":"かんりゃくか","meaning_ko":"간략화"},{"word":"過剰","reading":"かじょう","meaning_ko":"과잉"},{"word":"一朝一夕","reading":"いっちょういっせき","meaning_ko":"하루아침에"}]'::jsonb,
  ARRAY['〜に基づいている', '〜傾向にある', '〜のではないだろうか'],
  '일본어의 경어는 사회적 관계성을 언어로 표현하는 정밀한 체계이다. 문화청의 분류에서는 경어를 존경어, 겸양어I, 겸양어II(정중어), 공손어, 미화어의 5종류로 나눈다.

존경어는 상대의 행위를 높이는 표현으로 "이랏샤루", "옷샤루", "고란니 나루" 등이 있다. 겸양어I은 자신의 행위를 낮춤으로써 상대를 세우는 표현으로 "마이루", "모우스", "하이켄스루" 등이다.

비즈니스 상황에서는 사내와 사외에서 경어 사용법이 바뀌는 점이 외국인에게 특히 어렵다. 예를 들어 자사의 상사에 대해 사외 사람에게 말할 경우 "부장의 야마다는 출장 중입니다"처럼 경칭을 붙이지 않고 존경어도 사용하지 않는다. 이것은 일본의 "우치(안)와 소토(밖)" 개념에 기반한다.

최근에는 경어의 간략화가 진행되어 "사세테 이타다쿠"의 과잉 사용이 문제시되기도 한다. 원래는 상대의 허가를 얻어 하는 행위에 사용하는 표현이지만 "발표시키겠습니다"처럼 허가가 필요 없는 장면에서도 남용되는 경향이 있다.

올바른 경어 운용은 하루아침에 익힐 수 없지만 상대에 대한 경의를 말로 표현하려는 자세야말로 가장 중요한 것이 아닐까.',
  49
);

-- N2-23: 技術文書の書き方 (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '技術文書の書き方ガイド',
  '技術文書作成ガイドライン

エンジニアにとって、明確な技術文書を書く能力はコードを書く能力と同様に重要である。以下のガイドラインに従って、読みやすい文書を作成してほしい。

1. 対象読者を意識する
　文書を読む人の技術レベルを想定し、用語の説明の深さを調整する。新入社員向けと上級エンジニア向けでは、書き方を変える必要がある。

2. 構造を明確にする
　見出し、箇条書き、番号付きリストを活用し、情報の階層構造を視覚的に表現する。長い段落は避け、一つの段落には一つのトピックのみを含める。

3. 曖昧な表現を避ける
　×「かなり速い」→ ○「レスポンスタイムが200msから50msに改善」
　×「たくさんのユーザー」→ ○「月間アクティブユーザー10万人」

4. 図表を効果的に使う
　システム構成図、フローチャート、シーケンス図などを用いて、テキストだけでは伝わりにくい情報を視覚化する。

5. レビューを受ける
　第三者の目を通すことで、自分では気づかない誤りや不明瞭な箇所を発見できる。',
  'instruction',
  'N2',
  250,
  '技術文書',
  '[{"word":"想定","reading":"そうてい","meaning_ko":"상정"},{"word":"階層","reading":"かいそう","meaning_ko":"계층"},{"word":"箇条書き","reading":"かじょうがき","meaning_ko":"항목별 기재"},{"word":"視覚化","reading":"しかくか","meaning_ko":"시각화"},{"word":"不明瞭","reading":"ふめいりょう","meaning_ko":"불명료"}]'::jsonb,
  ARRAY['〜と同様に', '〜必要がある', '〜ことで'],
  '기술 문서 작성 가이드라인

엔지니어에게 명확한 기술 문서를 쓰는 능력은 코드를 쓰는 능력과 마찬가지로 중요하다. 아래 가이드라인에 따라 읽기 쉬운 문서를 작성해 주었으면 한다.

1. 대상 독자를 의식할 것
　문서를 읽는 사람의 기술 레벨을 상정하고 용어 설명의 깊이를 조정한다. 신입사원용과 상급 엔지니어용은 쓰는 법을 바꿀 필요가 있다.

2. 구조를 명확히 할 것
　제목, 항목별 기재, 번호 리스트를 활용하여 정보의 계층 구조를 시각적으로 표현한다. 긴 단락은 피하고 하나의 단락에는 하나의 토픽만 포함한다.

3. 애매한 표현을 피할 것
　× "꽤 빠르다" → ○ "응답 시간이 200ms에서 50ms로 개선"
　× "많은 유저" → ○ "월간 액티브 유저 10만 명"

4. 도표를 효과적으로 사용할 것
　시스템 구성도, 플로우차트, 시퀀스 다이어그램 등을 사용하여 텍스트만으로는 전달하기 어려운 정보를 시각화한다.

5. 리뷰를 받을 것
　제3자의 눈을 거치면 자신이 눈치채지 못한 오류나 불명료한 곳을 발견할 수 있다.',
  50
);

-- N2-24: 日本の災害対策と技術 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の災害対策と技術',
  '日本は地震、台風、津波、火山噴火など、多様な自然災害に見舞われる国である。この過酷な自然環境が、世界最高水準の防災技術の発展を促してきた。

地震対策における日本の技術は特に秀でている。緊急地震速報システムは、P波を検知してS波の到達前に警報を発信することで、数秒から数十秒の猶予時間を確保する。この短い時間が、電車の緊急停車、工場の生産ライン停止、エレベーターの最寄り階停止などの自動制御を可能にしている。

建築分野では、免震構造と制震構造の技術が進んでいる。免震構造は建物の基礎部分にゴムなどの装置を設置し、地震の揺れを建物に直接伝えない仕組みである。東京スカイツリーには、制震技術として伝統的な五重塔の構造原理が応用されている。

ICTを活用した防災も進展している。SNSを通じた災害情報の即時共有、AIによる被害予測、ドローンを用いた被災状況の調査など、テクノロジーが防災の各段階で活用されるようになった。

日本の防災技術と知見は、同様の災害リスクを抱える途上国への技術移転という形で国際貢献にもつながっている。',
  'article',
  'N2',
  260,
  '災害対策と技術',
  '[{"word":"見舞われる","reading":"みまわれる","meaning_ko":"당하다, 습격당하다"},{"word":"猶予","reading":"ゆうよ","meaning_ko":"유예"},{"word":"免震","reading":"めんしん","meaning_ko":"면진"},{"word":"進展","reading":"しんてん","meaning_ko":"진전"},{"word":"知見","reading":"ちけん","meaning_ko":"지견, 노하우"}]'::jsonb,
  ARRAY['〜を促してきた', '〜を可能にする', '〜につながっている'],
  '일본은 지진, 태풍, 쓰나미, 화산 분화 등 다양한 자연재해를 겪는 나라이다. 이 가혹한 자연환경이 세계 최고 수준의 방재 기술의 발전을 촉진해 왔다.

지진 대책에서 일본의 기술은 특히 뛰어나다. 긴급 지진 속보 시스템은 P파를 감지하여 S파 도달 전에 경보를 발신함으로써 수 초에서 수십 초의 유예 시간을 확보한다. 이 짧은 시간이 전철의 긴급 정지, 공장 생산 라인 정지, 엘리베이터의 가장 가까운 층 정지 등의 자동 제어를 가능하게 한다.

건축 분야에서는 면진 구조와 제진 구조의 기술이 진행되고 있다. 면진 구조는 건물의 기초 부분에 고무 등의 장치를 설치하여 지진의 흔들림을 건물에 직접 전달하지 않는 구조이다. 도쿄 스카이트리에는 제진 기술로 전통적인 오중탑의 구조 원리가 응용되어 있다.

ICT를 활용한 방재도 진전되고 있다. SNS를 통한 재해 정보의 즉시 공유, AI에 의한 피해 예측, 드론을 이용한 피해 상황 조사 등 테크놀로지가 방재의 각 단계에서 활용되게 되었다.

일본의 방재 기술과 지견은 유사한 재해 리스크를 안고 있는 개발도상국에의 기술 이전이라는 형태로 국제 공헌에도 연결되고 있다.',
  51
);

-- N2-25: 年次有給休暇取得促進の通知 (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '年次有給休暇取得促進のお知らせ',
  '全社員各位

年次有給休暇の取得促進について

労働基準法の改正により、年10日以上の有給休暇が付与される社員は、年5日以上の取得が義務づけられています。今年度の取得状況を確認したところ、未だ5日に達していない社員が全体の12%に上ることが判明しました。

対象者には個別にメールを送付しておりますが、年度末（3月31日）までに必ず取得してください。未取得の場合、会社として法令違反となり、罰則の対象となる可能性があります。

【推奨事項】
・計画的付与日：3月24日（月）、3月28日（金）を全社休暇推奨日とします
・連続取得の推奨：土日と組み合わせて3連休以上を作ることを推奨します
・チーム内での調整：チームリーダーは、メンバーの有給取得状況を確認し、取得しやすい環境づくりにご協力ください

有給休暇は労働者の権利です。「忙しいから取れない」のではなく、「取得するために業務を調整する」という意識を持ちましょう。

人事部',
  'notice',
  'N2',
  230,
  '有給休暇',
  '[{"word":"付与","reading":"ふよ","meaning_ko":"부여"},{"word":"義務づける","reading":"ぎむづける","meaning_ko":"의무화하다"},{"word":"法令","reading":"ほうれい","meaning_ko":"법령"},{"word":"推奨","reading":"すいしょう","meaning_ko":"추천"},{"word":"調整","reading":"ちょうせい","meaning_ko":"조정"}]'::jsonb,
  ARRAY['〜に上る', '〜となる可能性がある', '〜のではなく'],
  '전 사원 각위

연차 유급 휴가 취득 촉진에 대하여

노동 기준법 개정에 의해 연 10일 이상의 유급 휴가가 부여되는 사원은 연 5일 이상의 취득이 의무화되어 있습니다. 금년도 취득 상황을 확인한 결과 아직 5일에 달하지 않은 사원이 전체의 12%에 이르는 것이 판명되었습니다.

대상자에게는 개별적으로 메일을 보내고 있으나 연도 말(3월 31일)까지 반드시 취득해 주세요. 미취득의 경우 회사로서 법령 위반이 되어 벌칙 대상이 될 가능성이 있습니다.

【권장 사항】
・계획적 부여일: 3월 24일(월), 3월 28일(금)을 전사 휴가 권장일로 합니다
・연속 취득 권장: 주말과 조합하여 3연휴 이상을 만들 것을 권장합니다
・팀 내 조정: 팀리더는 멤버의 유급 취득 상황을 확인하고 취득하기 쉬운 환경 만들기에 협력해 주세요

유급 휴가는 노동자의 권리입니다. "바빠서 못 쓴다"가 아니라 "취득하기 위해 업무를 조정한다"는 의식을 가집시다.

인사부',
  52
);

-- N2-26: コードレビューのベストプラクティス (instruction)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'コードレビューのベストプラクティス',
  'コードレビューガイドライン

効果的なコードレビューは、コード品質の向上だけでなく、チーム全体のスキルアップにも貢献する。以下のベストプラクティスを参考にしてほしい。

【レビュアーとして】
1. 人格ではなくコードに対してフィードバックする
　×「こんな書き方をする人の気が知れない」
　○「この部分はXXパターンを使うと可読性が上がると思います」

2. 指摘だけでなく、良い点も伝える
　優れた実装やきれいなコードを見つけたら、積極的に褒める

3. 「なぜ」を説明する
　変更を提案する際は、その理由を明確にする。「こうした方がいい」だけでは、レビューイが納得できない

4. 重要度を明示する
　[must] 修正必須、[should] 修正推奨、[nit] 些細な指摘 のようにラベルをつける

【レビューイとして】
1. PRの説明を丁寧に書く（変更の目的、影響範囲、テスト方法）
2. 大きなPRは避け、300行以内を目安にする
3. フィードバックを個人攻撃と受け取らない
4. 不明な点は素直に質問する',
  'instruction',
  'N2',
  240,
  'コードレビュー',
  '[{"word":"可読性","reading":"かどくせい","meaning_ko":"가독성"},{"word":"些細","reading":"ささい","meaning_ko":"사소한"},{"word":"明示","reading":"めいじ","meaning_ko":"명시"},{"word":"納得","reading":"なっとく","meaning_ko":"납득"},{"word":"素直","reading":"すなお","meaning_ko":"솔직한"}]'::jsonb,
  ARRAY['〜だけでなく', '〜際は', '〜を目安にする'],
  '코드 리뷰 가이드라인

효과적인 코드 리뷰는 코드 품질 향상뿐만 아니라 팀 전체의 스킬업에도 공헌한다. 아래 베스트 프랙티스를 참고해 주었으면 한다.

【리뷰어로서】
1. 인격이 아닌 코드에 대해 피드백할 것
　× "이런 식으로 쓰는 사람의 심정을 모르겠다"
　○ "이 부분은 XX 패턴을 사용하면 가독성이 올라갈 것 같습니다"

2. 지적뿐만 아니라 좋은 점도 전할 것
　뛰어난 구현이나 깔끔한 코드를 발견하면 적극적으로 칭찬

3. "왜"를 설명할 것
　변경을 제안할 때는 그 이유를 명확히 한다. "이렇게 하는 게 낫다"만으로는 리뷰이가 납득할 수 없다

4. 중요도를 명시할 것
　[must] 수정 필수, [should] 수정 권장, [nit] 사소한 지적 처럼 라벨을 붙인다

【리뷰이로서】
1. PR 설명을 정중하게 쓸 것 (변경 목적, 영향 범위, 테스트 방법)
2. 큰 PR은 피하고 300줄 이내를 기준으로 할 것
3. 피드백을 개인 공격으로 받아들이지 말 것
4. 모르는 점은 솔직하게 질문할 것',
  53
);

-- N2-27: 日本の祭りと地域活性化 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の祭りと地域活性化',
  '日本全国には年間を通じて約30万の祭りが開催されている。祭りは古来より、五穀豊穣や無病息災を祈る宗教的行事として受け継がれてきたが、現代においては地域コミュニティの結束を強化し、地域経済を活性化する役割も担っている。

青森のねぶた祭は毎年約270万人の観光客を集め、経済波及効果は約500億円に上ると試算されている。京都の祇園祭は千年以上の歴史を持ち、ユネスコの無形文化遺産にも登録されている。

しかし、多くの地方の祭りは担い手不足という深刻な課題に直面している。少子高齢化と都市への人口流出により、祭りの運営や伝統技能の伝承が困難になっているのである。

こうした課題に対し、外国人住民の参加を促進する取り組みが注目されている。地域に暮らす外国人が祭りに参加することで、文化交流が深まるとともに、祭りの担い手不足の解消にもつながっている。

伝統を守りながらも、時代の変化に適応していく柔軟性が、日本の祭り文化の持続可能性を左右するだろう。',
  'essay',
  'N2',
  250,
  '祭りと地域活性化',
  '[{"word":"五穀豊穣","reading":"ごこくほうじょう","meaning_ko":"오곡풍양"},{"word":"波及効果","reading":"はきゅうこうか","meaning_ko":"파급 효과"},{"word":"担い手","reading":"にないて","meaning_ko":"담당자, 주역"},{"word":"伝承","reading":"でんしょう","meaning_ko":"전승"},{"word":"持続可能性","reading":"じぞくかのうせい","meaning_ko":"지속 가능성"}]'::jsonb,
  ARRAY['〜として受け継がれてきた', '〜に上ると', '〜を左右する'],
  '일본 전국에서는 연간 약 30만 개의 축제가 개최되고 있다. 축제는 예로부터 오곡풍양이나 무병장수를 기원하는 종교적 행사로 이어져 왔으나 현대에는 지역 커뮤니티의 결속을 강화하고 지역 경제를 활성화하는 역할도 담당하고 있다.

아오모리의 네부타 축제는 매년 약 270만 명의 관광객을 모으며 경제 파급 효과는 약 500억 엔에 이르는 것으로 추산되고 있다. 교토의 기온 축제는 천 년 이상의 역사를 가지며 유네스코 무형문화유산에도 등록되어 있다.

그러나 많은 지방 축제는 담당자 부족이라는 심각한 과제에 직면하고 있다. 저출산 고령화와 도시로의 인구 유출로 축제의 운영이나 전통 기능의 전승이 곤란해지고 있는 것이다.

이러한 과제에 대해 외국인 주민의 참가를 촉진하는 노력이 주목받고 있다. 지역에 사는 외국인이 축제에 참가함으로써 문화 교류가 깊어지는 동시에 축제의 담당자 부족 해소에도 연결되고 있다.

전통을 지키면서도 시대의 변화에 적응해 가는 유연성이 일본의 축제 문화의 지속 가능성을 좌우할 것이다.',
  54
);

-- N2-28: 障害報告書テンプレート (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'システム障害報告書',
  'システム障害報告書

1. 障害概要
発生日時：2026年2月28日 14:23
復旧日時：2026年2月28日 15:47（障害時間：1時間24分）
影響範囲：全ユーザーの注文処理機能
影響ユーザー数：推定約3,200名
重大度：P1（サービス全体に影響）

2. 事象
注文APIが500エラーを返し、ユーザーが注文を完了できない状態となった。エラー率は最大95%に達した。

3. 根本原因
デプロイ時のデータベースマイグレーションスクリプトにバグがあり、注文テーブルのインデックスが破損した。本来、マイグレーションはステージング環境でテスト済みであるべきだが、今回は時間的制約から本番環境に直接適用してしまった。

4. 復旧対応
・14:30 アラート検知、オンコールエンジニアが調査開始
・14:45 原因特定、マイグレーションのロールバックを実行
・15:20 インデックスの再構築完了
・15:47 全機能の正常動作を確認、復旧宣言

5. 再発防止策
・マイグレーションの本番適用前のステージング環境でのテストを必須化
・デプロイ手順のチェックリストにマイグレーション検証項目を追加
・自動ロールバック機能の実装',
  'report',
  'N2',
  260,
  'システム障害報告',
  '[{"word":"復旧","reading":"ふっきゅう","meaning_ko":"복구"},{"word":"事象","reading":"じしょう","meaning_ko":"사상, 현상"},{"word":"根本原因","reading":"こんぽんげんいん","meaning_ko":"근본 원인"},{"word":"破損","reading":"はそん","meaning_ko":"파손"},{"word":"再発防止","reading":"さいはつぼうし","meaning_ko":"재발 방지"}]'::jsonb,
  ARRAY['〜であるべき', '〜てしまった', '〜を必須化'],
  '시스템 장애 보고서

1. 장애 개요
발생 일시: 2026년 2월 28일 14:23
복구 일시: 2026년 2월 28일 15:47 (장애 시간: 1시간 24분)
영향 범위: 전 유저의 주문 처리 기능
영향 유저 수: 추정 약 3,200명
중대도: P1 (서비스 전체에 영향)

2. 현상
주문 API가 500 에러를 반환하여 유저가 주문을 완료할 수 없는 상태가 되었다. 에러율은 최대 95%에 달했다.

3. 근본 원인
디플로이 시 데이터베이스 마이그레이션 스크립트에 버그가 있어 주문 테이블의 인덱스가 파손되었다. 본래 마이그레이션은 스테이징 환경에서 테스트 완료 상태여야 하지만 이번에는 시간적 제약으로 본번 환경에 직접 적용해 버렸다.

4. 복구 대응
・14:30 알림 감지, 온콜 엔지니어가 조사 시작
・14:45 원인 특정, 마이그레이션 롤백 실행
・15:20 인덱스 재구축 완료
・15:47 전 기능 정상 동작 확인, 복구 선언

5. 재발 방지책
・마이그레이션의 본번 적용 전 스테이징 환경에서의 테스트를 필수화
・디플로이 절차 체크리스트에 마이그레이션 검증 항목 추가
・자동 롤백 기능 구현',
  55
);

-- N2-29: マイクロサービスアーキテクチャ (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'マイクロサービスアーキテクチャの考察',
  'マイクロサービスアーキテクチャは、大規模なアプリケーションを独立した小さなサービスに分割して開発・運用する手法である。各サービスは特定のビジネス機能を担い、APIを通じて相互に通信する。

モノリシックアーキテクチャと比較した場合のメリットは明確である。第一に、各サービスを独立してデプロイできるため、開発チームの自律性が高まる。第二に、サービスごとに最適な技術スタックを選択できる。第三に、特定のサービスのみをスケールアウトすることで、リソースの効率的な活用が可能となる。

しかし、マイクロサービスの導入には相応のコストと複雑性が伴う。サービス間通信のレイテンシ、分散トランザクションの整合性確保、障害の伝播防止（サーキットブレーカーパターン）、そして数十から数百に及ぶサービスの監視とデバッグの困難さは、無視できない課題である。

Netflixの事例に見られるように、マイクロサービスへの移行は段階的に行うべきであり、組織の成熟度と技術的能力を見極めた上で判断する必要がある。小規模なチームや初期段階のプロダクトにおいては、モノリスから始めて必要に応じて分割していく「モノリス・ファースト」のアプローチが現実的であろう。',
  'article',
  'N2',
  270,
  'マイクロサービス',
  '[{"word":"分割","reading":"ぶんかつ","meaning_ko":"분할"},{"word":"自律性","reading":"じりつせい","meaning_ko":"자율성"},{"word":"整合性","reading":"せいごうせい","meaning_ko":"정합성"},{"word":"伝播","reading":"でんぱ","meaning_ko":"전파"},{"word":"見極める","reading":"みきわめる","meaning_ko":"간파하다"}]'::jsonb,
  ARRAY['〜と比較した場合', '〜べきであり', '〜であろう'],
  '마이크로서비스 아키텍처는 대규모 애플리케이션을 독립된 작은 서비스로 분할하여 개발·운용하는 방법이다. 각 서비스는 특정 비즈니스 기능을 담당하며 API를 통해 상호 통신한다.

모놀리식 아키텍처와 비교한 경우의 장점은 명확하다. 첫째, 각 서비스를 독립적으로 디플로이할 수 있어 개발 팀의 자율성이 높아진다. 둘째, 서비스별로 최적의 기술 스택을 선택할 수 있다. 셋째, 특정 서비스만 스케일아웃함으로써 리소스의 효율적 활용이 가능해진다.

그러나 마이크로서비스 도입에는 상응하는 비용과 복잡성이 수반된다. 서비스간 통신의 레이턴시, 분산 트랜잭션의 정합성 확보, 장애 전파 방지(서킷 브레이커 패턴), 그리고 수십에서 수백에 이르는 서비스의 모니터링과 디버깅의 어려움은 무시할 수 없는 과제이다.

Netflix의 사례에서 볼 수 있듯이 마이크로서비스로의 이행은 단계적으로 해야 하며 조직의 성숙도와 기술적 능력을 간파한 후에 판단할 필요가 있다. 소규모 팀이나 초기 단계의 프로덕트에서는 모놀리스부터 시작하여 필요에 따라 분할해 나가는 "모놀리스 퍼스트" 접근법이 현실적일 것이다.',
  56
);

-- N2-30: 外国人労働者の社会統合 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '外国人労働者の社会統合に向けて',
  '日本で働く外国人労働者は200万人を超え、過去最高を更新し続けている。彼らは日本経済を支える重要な存在であるにもかかわらず、社会統合に向けた施策は依然として不十分な状態にある。

最も深刻な課題は言語教育の機会格差である。技能実習生や特定技能労働者の多くは、体系的な日本語教育を受ける機会が限られている。業務に必要な最低限の日本語は身につけても、行政手続きや医療機関の受診に必要な日本語力が不足しているケースは少なくない。

住居の確保も大きな障壁となっている。外国人であることを理由に入居を断られるケースが依然として報告されており、住居確保のための保証制度の整備が求められている。

子どもの教育も見過ごせない課題である。日本語を母語としない児童生徒のうち、日本語指導が必要な者は約5万人に上る。しかし、日本語教育の専門的な訓練を受けた教員は圧倒的に不足しており、自治体間の対応にも大きな格差がある。

外国人を「一時的な労働力」としてではなく、「共に暮らす隣人」として受け入れる社会の意識改革が、すべての施策の根底にあるべきものではないだろうか。多文化共生社会の実現は、日本社会全体の豊かさにつながるものである。',
  'essay',
  'N2',
  280,
  '外国人労働者の社会統合',
  '[{"word":"統合","reading":"とうごう","meaning_ko":"통합"},{"word":"施策","reading":"しさく","meaning_ko":"시책"},{"word":"格差","reading":"かくさ","meaning_ko":"격차"},{"word":"障壁","reading":"しょうへき","meaning_ko":"장벽"},{"word":"共生","reading":"きょうせい","meaning_ko":"공생"}]'::jsonb,
  ARRAY['〜にもかかわらず', '〜にあるべき', '〜ではないだろうか'],
  '일본에서 일하는 외국인 노동자는 200만 명을 넘어 역대 최고를 경신하고 있다. 그들은 일본 경제를 지탱하는 중요한 존재임에도 불구하고 사회 통합을 향한 시책은 여전히 불충분한 상태에 있다.

가장 심각한 과제는 언어 교육의 기회 격차이다. 기능 실습생이나 특정 기능 노동자의 대부분은 체계적인 일본어 교육을 받을 기회가 한정되어 있다. 업무에 필요한 최소한의 일본어는 익혀도 행정 수속이나 의료기관 진료에 필요한 일본어 능력이 부족한 케이스는 적지 않다.

주거 확보도 큰 장벽이 되고 있다. 외국인인 것을 이유로 입주를 거절당하는 케이스가 여전히 보고되고 있으며 주거 확보를 위한 보증 제도 정비가 요구되고 있다.

자녀의 교육도 간과할 수 없는 과제이다. 일본어를 모어로 하지 않는 아동·학생 중 일본어 지도가 필요한 자는 약 5만 명에 이른다. 그러나 일본어 교육의 전문적 훈련을 받은 교원은 압도적으로 부족하며 지자체간 대응에도 큰 격차가 있다.

외국인을 "일시적 노동력"으로서가 아니라 "함께 사는 이웃"으로 받아들이는 사회의 의식 개혁이 모든 시책의 근저에 있어야 할 것이 아닐까. 다문화 공생 사회의 실현은 일본 사회 전체의 풍요로움에 연결되는 것이다.',
  57
);

-- ============================================
-- N1 Reading Passages (10-30) — Additional 21
