-- N1-10: 技術的負債と組織のジレンマ (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '技術的負債と組織のジレンマ',
  '技術的負債（テクニカルデット）とは、ソフトウェア開発において、短期的な利益のために長期的な保守性を犠牲にした設計判断の蓄積を指す概念である。この比喩はウォード・カニンガムによって1992年に提唱されたが、その本質は金融における負債と同様に、返済を先延ばしにすればするほど利子が膨らみ、最終的には組織の技術的な機動力を著しく損なうという点にある。

技術的負債が蓄積する原因は多岐にわたる。市場投入までの時間的圧力、不十分な設計レビュー、要件の頻繁な変更、そして開発者のスキル不足などが挙げられる。しかし、見落とされがちなのは、組織的な要因である。技術的負債の返済、すなわちリファクタリングは、短期的にはビジネス価値を直接生み出さないため、プロダクトオーナーやマネジメント層からの理解を得にくい。

この構造的な問題に対処するには、技術的負債を可視化し、ビジネスへの影響を定量的に示すことが不可欠である。例えば、レガシーコードの修正に要する工数の増加率や、デプロイ頻度の低下、障害発生率の上昇などを定期的に計測し、経営層に報告する仕組みを構築することが肝要である。

究極的には、技術的負債の管理は技術者だけの責任ではなく、経営戦略の一環として位置づけられるべきものである。短期的な機能追加と長期的なコード品質のバランスをいかに取るかは、組織の持続的な競争力を左右する経営判断に他ならない。',
  'essay',
  'N1',
  330,
  '技術的負債',
  '[{"word":"負債","reading":"ふさい","meaning_ko":"부채"},{"word":"犠牲","reading":"ぎせい","meaning_ko":"희생"},{"word":"機動力","reading":"きどうりょく","meaning_ko":"기동력"},{"word":"可視化","reading":"かしか","meaning_ko":"가시화"},{"word":"肝要","reading":"かんよう","meaning_ko":"긴요, 중요"}]'::jsonb,
  ARRAY['〜を指す概念', '〜に他ならない', '〜べきものである'],
  '기술적 부채(테크니컬 데트)란 소프트웨어 개발에서 단기적 이익을 위해 장기적 유지보수성을 희생한 설계 판단의 축적을 가리키는 개념이다. 이 비유는 워드 커닝엄에 의해 1992년에 제창되었으나 그 본질은 금융에서의 부채와 마찬가지로 상환을 미루면 미룰수록 이자가 불어나 최종적으로는 조직의 기술적 기동력을 현저히 손상시킨다는 점에 있다.

기술적 부채가 축적되는 원인은 다방면에 걸쳐 있다. 시장 투입까지의 시간적 압력, 불충분한 설계 리뷰, 요건의 빈번한 변경, 그리고 개발자의 스킬 부족 등이 꼽힌다. 그러나 간과하기 쉬운 것은 조직적 요인이다. 기술적 부채의 상환, 즉 리팩토링은 단기적으로는 비즈니스 가치를 직접 창출하지 않기 때문에 프로덕트 오너나 매니지먼트층의 이해를 얻기 어렵다.

이 구조적 문제에 대처하려면 기술적 부채를 가시화하고 비즈니스에의 영향을 정량적으로 보여주는 것이 불가결하다. 예를 들어 레거시 코드의 수정에 소요되는 공수의 증가율이나 디플로이 빈도의 저하, 장애 발생률의 상승 등을 정기적으로 측정하고 경영층에 보고하는 구조를 구축하는 것이 긴요하다.

궁극적으로 기술적 부채의 관리는 기술자만의 책임이 아니라 경영 전략의 일환으로 자리매김되어야 할 것이다. 단기적 기능 추가와 장기적 코드 품질의 밸런스를 어떻게 잡을 것인가는 조직의 지속적 경쟁력을 좌우하는 경영 판단에 다름 아니다.',
  46
);

-- N1-11: 日本型雇用システムの変容 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本型雇用システムの変容と展望',
  '終身雇用、年功序列、企業別労働組合を三本柱とする日本型雇用システムは、戦後の高度経済成長期に確立され、日本企業の国際競争力の源泉として機能してきた。しかし、バブル経済の崩壊以降、このシステムは根本的な変容を迫られている。

終身雇用の前提は、企業の持続的な成長と安定した事業環境であった。グローバル化とデジタル化が加速する現代において、長期的な雇用保障を維持することは多くの企業にとって困難になりつつある。経団連会長が「終身雇用を守り続けるのは難しい」と公言したことは、象徴的な出来事であった。

年功序列に代わる成果主義の導入も進んでいる。ジョブ型雇用への移行を宣言する大企業が相次ぎ、職務内容と報酬を明確に紐づける人事制度の整備が進められている。しかし、メンバーシップ型の雇用慣行に慣れた中高年社員の処遇問題は、依然として企業にとって重い課題である。

一方で、日本型雇用システムの全面的な否定が正しいかどうかは慎重に検討する必要がある。長期的な視点での人材育成、組織への帰属意識による協調性、暗黙知の継承といった利点は、安易に失うべきではないだろう。重要なのは、旧来のシステムの利点を残しながら、個人の多様なキャリア志向に応じた柔軟な仕組みを構築していくことではないだろうか。',
  'article',
  'N1',
  320,
  '日本型雇用システム',
  '[{"word":"年功序列","reading":"ねんこうじょれつ","meaning_ko":"연공서열"},{"word":"源泉","reading":"げんせん","meaning_ko":"원천"},{"word":"紐づける","reading":"ひもづける","meaning_ko":"연결하다"},{"word":"帰属意識","reading":"きぞくいしき","meaning_ko":"귀속 의식"},{"word":"暗黙知","reading":"あんもくち","meaning_ko":"암묵지"}]'::jsonb,
  ARRAY['〜として機能してきた', '〜つつある', '〜べきではないだろう'],
  '종신 고용, 연공서열, 기업별 노동조합을 세 기둥으로 하는 일본형 고용 시스템은 전후 고도 경제 성장기에 확립되어 일본 기업의 국제 경쟁력의 원천으로 기능해 왔다. 그러나 버블 경제 붕괴 이후 이 시스템은 근본적인 변용을 강요받고 있다.

종신 고용의 전제는 기업의 지속적 성장과 안정된 사업 환경이었다. 글로벌화와 디지털화가 가속하는 현대에서 장기적 고용 보장을 유지하는 것은 많은 기업에게 곤란해지고 있다. 경단련 회장이 "종신 고용을 계속 지키는 것은 어렵다"고 공언한 것은 상징적 사건이었다.

연공서열을 대신하는 성과주의 도입도 진행되고 있다. 잡형 고용으로의 이행을 선언하는 대기업이 잇따르며 직무 내용과 보수를 명확히 연결하는 인사 제도 정비가 진행되고 있다. 그러나 멤버십형 고용 관행에 익숙한 중고년 사원의 처우 문제는 여전히 기업에게 무거운 과제이다.

한편 일본형 고용 시스템의 전면적 부정이 올바른지는 신중하게 검토할 필요가 있다. 장기적 관점에서의 인재 육성, 조직에의 귀속 의식에 의한 협조성, 암묵지의 계승이라는 이점은 안이하게 잃어서는 안 될 것이다. 중요한 것은 구래의 시스템의 이점을 남기면서 개인의 다양한 커리어 지향에 따른 유연한 구조를 구축해 나가는 것이 아닐까.',
  47
);

-- N1-12: 量子コンピューティングの現状と課題 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '量子コンピューティングの現状と課題',
  '量子コンピューティングは、量子力学の原理を計算に応用する革新的技術である。従来のコンピュータが0か1のビットで情報を処理するのに対し、量子コンピュータは量子ビット（キュービット）を用いることで、0と1の重ね合わせ状態を同時に表現できる。この性質により、特定の計算問題において従来のコンピュータを圧倒的に凌駕する処理能力を発揮する可能性を秘めている。

現在、Google、IBM、Microsoftなどの大手テクノロジー企業が開発競争を繰り広げており、2019年にはGoogleが「量子超越性」の達成を主張した。しかし、実用的な量子コンピュータの実現には、依然として多くの技術的障壁が存在する。

最大の課題はエラー訂正である。量子ビットは環境からの干渉に対して極めて脆弱であり、わずかな温度変化や振動によってもデコヒーレンス（量子状態の崩壊）が発生する。現在の量子コンピュータは「NISQ（Noisy Intermediate-Scale Quantum）」と呼ばれる段階にあり、エラー率の高さが実用的な計算を妨げている。

それでもなお、量子コンピューティングへの期待は大きい。創薬シミュレーション、金融ポートフォリオの最適化、暗号解読、材料科学など、その応用領域は広範にわたる。特に、現行の暗号方式が量子コンピュータによって破られる可能性は、ポスト量子暗号の研究開発を喫緊の課題としている。',
  'article',
  'N1',
  340,
  '量子コンピューティング',
  '[{"word":"凌駕","reading":"りょうが","meaning_ko":"능가"},{"word":"脆弱","reading":"ぜいじゃく","meaning_ko":"취약"},{"word":"崩壊","reading":"ほうかい","meaning_ko":"붕괴"},{"word":"広範","reading":"こうはん","meaning_ko":"광범"},{"word":"喫緊","reading":"きっきん","meaning_ko":"긴급, 시급"}]'::jsonb,
  ARRAY['〜のに対し', '〜を秘めている', '〜としている'],
  '양자 컴퓨팅은 양자역학의 원리를 계산에 응용하는 혁신적 기술이다. 종래의 컴퓨터가 0 또는 1의 비트로 정보를 처리하는 데 반해 양자 컴퓨터는 양자 비트(큐비트)를 사용함으로써 0과 1의 중첩 상태를 동시에 표현할 수 있다. 이 성질에 의해 특정 계산 문제에서 종래 컴퓨터를 압도적으로 능가하는 처리 능력을 발휘할 가능성을 품고 있다.

현재 Google, IBM, Microsoft 등 대형 테크놀로지 기업이 개발 경쟁을 벌이고 있으며 2019년에는 Google이 "양자 우월성" 달성을 주장했다. 그러나 실용적인 양자 컴퓨터의 실현에는 여전히 많은 기술적 장벽이 존재한다.

최대 과제는 에러 정정이다. 양자 비트는 환경으로부터의 간섭에 대해 극히 취약하며 약간의 온도 변화나 진동에 의해서도 디코히런스(양자 상태의 붕괴)가 발생한다. 현재의 양자 컴퓨터는 "NISQ(Noisy Intermediate-Scale Quantum)"라 불리는 단계에 있으며 에러율의 높음이 실용적 계산을 방해하고 있다.

그럼에도 불구하고 양자 컴퓨팅에 대한 기대는 크다. 신약 시뮬레이션, 금융 포트폴리오 최적화, 암호 해독, 재료 과학 등 그 응용 영역은 광범위하다. 특히 현행 암호 방식이 양자 컴퓨터에 의해 깨질 가능성은 포스트 양자 암호의 연구 개발을 시급한 과제로 만들고 있다.',
  48
);

-- N1-13: 日本の司法制度と裁判員制度 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '裁判員制度の意義と課題',
  '2009年に導入された裁判員制度は、一般市民が刑事裁判に参加する画期的な制度改革であった。この制度の目的は、司法に対する国民の信頼を高め、裁判の内容を国民にとってより身近で分かりやすいものとすることにある。

裁判員は、選挙人名簿から無作為に抽出された候補者の中から選任される。裁判員6名と裁判官3名で構成される合議体が、殺人や強盗致傷などの重大事件について、有罪・無罪の判断および量刑の決定を行う。

導入から15年以上が経過し、制度の成果と課題が明確になってきた。肯定的な面としては、量刑の幅が広がり、被害者の視点がより反映されるようになったことが挙げられる。また、法廷でのプレゼンテーションが工夫され、裁判の透明性が向上したとの評価もある。

しかし、課題も少なくない。裁判員の精神的負担は深刻であり、残虐な証拠写真への暴露によるPTSDの発症が報告されている。また、辞退率の上昇は、市民の負担感の増大を示唆している。さらに、守秘義務の範囲が広いことから、裁判員経験者が自らの体験を社会に還元しにくいという構造的な問題もある。

市民参加型司法の理念を維持しながら、いかにして裁判員の負担を軽減し、制度への参加意欲を高めていくかが、今後の重要な課題であろう。',
  'article',
  'N1',
  320,
  '裁判員制度',
  '[{"word":"無作為","reading":"むさくい","meaning_ko":"무작위"},{"word":"合議体","reading":"ごうぎたい","meaning_ko":"합의체"},{"word":"量刑","reading":"りょうけい","meaning_ko":"양형"},{"word":"暴露","reading":"ばくろ","meaning_ko":"폭로, 노출"},{"word":"守秘義務","reading":"しゅひぎむ","meaning_ko":"비밀 유지 의무"}]'::jsonb,
  ARRAY['〜にある', '〜としては', '〜であろう'],
  '2009년에 도입된 재판원 제도는 일반 시민이 형사 재판에 참가하는 획기적인 제도 개혁이었다. 이 제도의 목적은 사법에 대한 국민의 신뢰를 높이고 재판 내용을 국민에게 보다 친근하고 알기 쉬운 것으로 하는 데 있다.

재판원은 선거인 명부에서 무작위로 추출된 후보자 중에서 선임된다. 재판원 6명과 재판관 3명으로 구성되는 합의체가 살인이나 강도상해 등의 중대 사건에 대해 유죄·무죄의 판단 및 양형 결정을 행한다.

도입 후 15년 이상이 경과하여 제도의 성과와 과제가 명확해졌다. 긍정적 면으로는 양형의 폭이 넓어져 피해자의 관점이 보다 반영되게 된 점이 꼽힌다. 또한 법정에서의 프레젠테이션이 궁리되어 재판의 투명성이 향상되었다는 평가도 있다.

그러나 과제도 적지 않다. 재판원의 정신적 부담은 심각하며 잔혹한 증거 사진에의 노출에 의한 PTSD 발증이 보고되고 있다. 또한 사퇴율의 상승은 시민의 부담감 증대를 시사하고 있다. 나아가 비밀 유지 의무의 범위가 넓은 것으로 인해 재판원 경험자가 자신의 체험을 사회에 환원하기 어렵다는 구조적 문제도 있다.

시민 참가형 사법의 이념을 유지하면서 어떻게 재판원의 부담을 경감하고 제도에의 참가 의욕을 높여 갈 것인가가 향후의 중요한 과제일 것이다.',
  49
);

-- N1-14: 企業のDX推進と組織変革 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '企業のDX推進と組織変革',
  'DX推進委員会 中間報告書

1. 背景と目的
経済産業省の「DXレポート」が警鐘を鳴らした「2025年の崖」問題、すなわちレガシーシステムの刷新が進まない場合に年間最大12兆円の経済損失が生じうるという試算は、当社にとっても他人事ではない。本委員会は、当社のDX推進における現状分析と今後の方策を提言することを目的として設置された。

2. 現状分析
当社のDX成熟度を経済産業省のDX推進指標に基づき評価した結果、5段階中レベル2（一部で実施）に留まることが明らかになった。基幹システムの7割以上が導入から15年以上経過しており、システム間のデータ連携が困難な「サイロ化」が深刻である。

3. 提言
(1) 経営トップのコミットメント：DXはIT部門だけの課題ではなく経営戦略そのものである
(2) データ基盤の構築：全社的なデータプラットフォームを整備し、データドリブンな意思決定を可能にする
(3) 人材育成：全社員のデジタルリテラシー底上げと、DX推進リーダーの育成
(4) アジャイル型の推進体制：小さく始めて素早く検証する文化の醸成

DXの本質は技術導入ではなく、ビジネスモデルと組織文化の変革にある。この認識なくしてDXの成功はあり得ないと断言する。',
  'report',
  'N1',
  310,
  'DX推進',
  '[{"word":"刷新","reading":"さっしん","meaning_ko":"쇄신"},{"word":"方策","reading":"ほうさく","meaning_ko":"방책"},{"word":"成熟度","reading":"せいじゅくど","meaning_ko":"성숙도"},{"word":"醸成","reading":"じょうせい","meaning_ko":"양성, 조성"},{"word":"断言","reading":"だんげん","meaning_ko":"단언"}]'::jsonb,
  ARRAY['〜を目的として', '〜なくしては', '〜にある'],
  'DX 추진위원회 중간 보고서

1. 배경과 목적
경제산업성의 "DX 리포트"가 경종을 울린 "2025년의 절벽" 문제, 즉 레거시 시스템의 쇄신이 진행되지 않을 경우 연간 최대 12조 엔의 경제 손실이 발생할 수 있다는 추산은 당사에게도 남의 일이 아니다. 본 위원회는 당사의 DX 추진에서의 현황 분석과 향후 방책을 제언하는 것을 목적으로 설치되었다.

2. 현상 분석
당사의 DX 성숙도를 경제산업성의 DX 추진 지표에 기반하여 평가한 결과 5단계 중 레벨 2(일부에서 실시)에 머무는 것이 명확해졌다. 기간 시스템의 7할 이상이 도입 후 15년 이상 경과하였으며 시스템간 데이터 연계가 곤란한 "사일로화"가 심각하다.

3. 제언
(1) 경영 톱의 커밋먼트: DX는 IT 부문만의 과제가 아니라 경영 전략 그 자체이다
(2) 데이터 기반 구축: 전사적 데이터 플랫폼을 정비하고 데이터 드리븐한 의사결정을 가능하게 한다
(3) 인재 육성: 전 사원의 디지털 리터러시 바닥 올리기와 DX 추진 리더의 육성
(4) 애자일형 추진 체제: 작게 시작하여 빠르게 검증하는 문화의 양성

DX의 본질은 기술 도입이 아니라 비즈니스 모델과 조직 문화의 변혁에 있다. 이 인식 없이는 DX의 성공은 있을 수 없다고 단언한다.',
  50
);

-- N1-15: 言語相対性仮説とプログラミング言語 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '言語相対性仮説とプログラミング言語',
  '言語学におけるサピア＝ウォーフの仮説、すなわち使用する言語が思考様式に影響を与えるという言語相対性仮説は、自然言語の領域を超えて、プログラミング言語にも当てはまるのではないかという議論がある。

この考え方は、ポール・グレアムのエッセイ「Beating the Averages」においても言及されている。彼は、プログラマーが使用するプログラミング言語が、そのプログラマーの問題解決能力に影響を与えると主張した。Lispのようなマクロ機能を持つ言語に習熟したプログラマーは、Javaのみを使用するプログラマーとは異なる抽象化の能力を獲得するというのである。

実際、関数型プログラミングの考え方に触れたことのある開発者は、命令型言語を使用する場合でも、副作用の最小化やイミュータブルなデータ構造の活用を意識する傾向がある。逆に、オブジェクト指向パラダイムに慣れた開発者は、あらゆる問題をクラスの階層構造で捉えようとする傾向がある。

しかし、この類推には限界もある。自然言語と異なり、プログラミング言語は意図的に学習・切り替えが可能であり、多言語プログラマーは複数のパラダイムを場面に応じて使い分けることができる。むしろ重要なのは、特定の言語やパラダイムに固執することなく、問題の性質に最適な思考ツールを柔軟に選択できる能力を養うことであろう。',
  'essay',
  'N1',
  330,
  '言語と思考',
  '[{"word":"仮説","reading":"かせつ","meaning_ko":"가설"},{"word":"習熟","reading":"しゅうじゅく","meaning_ko":"숙달"},{"word":"類推","reading":"るいすい","meaning_ko":"유추"},{"word":"固執","reading":"こしつ","meaning_ko":"고집"},{"word":"養う","reading":"やしなう","meaning_ko":"기르다"}]'::jsonb,
  ARRAY['〜のではないか', '〜というのである', '〜ことであろう'],
  '언어학에서의 사피어-워프 가설, 즉 사용하는 언어가 사고 방식에 영향을 준다는 언어 상대성 가설은 자연 언어의 영역을 넘어 프로그래밍 언어에도 해당되는 것은 아닌가 하는 논의가 있다.

이 생각은 폴 그레이엄의 에세이 "Beating the Averages"에서도 언급되고 있다. 그는 프로그래머가 사용하는 프로그래밍 언어가 그 프로그래머의 문제 해결 능력에 영향을 준다고 주장했다. Lisp 같은 매크로 기능을 가진 언어에 숙달된 프로그래머는 Java만 사용하는 프로그래머와는 다른 추상화 능력을 획득한다는 것이다.

실제로 함수형 프로그래밍 사고방식에 접한 적이 있는 개발자는 명령형 언어를 사용하는 경우에도 부작용의 최소화나 불변 데이터 구조의 활용을 의식하는 경향이 있다. 반대로 객체지향 패러다임에 익숙한 개발자는 모든 문제를 클래스의 계층 구조로 파악하려는 경향이 있다.

그러나 이 유추에는 한계도 있다. 자연 언어와 달리 프로그래밍 언어는 의도적으로 학습·전환이 가능하며 다국어 프로그래머는 복수의 패러다임을 상황에 따라 구분하여 사용할 수 있다. 오히려 중요한 것은 특정 언어나 패러다임에 고집하지 않고 문제의 성질에 최적인 사고 도구를 유연하게 선택할 수 있는 능력을 기르는 것일 것이다.',
  51
);

-- N1-16: 日本の移民政策の転換 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の移民政策の転換点',
  '日本は長年にわたり、公式には「移民を受け入れない」という立場を維持してきた。しかし、2019年の改正入管法施行による「特定技能」在留資格の創設は、事実上の移民政策の転換点として広く認識されている。

特定技能制度は、深刻な人手不足に直面する14の産業分野において、一定の技能と日本語能力を有する外国人材を受け入れるものである。特定技能1号は最長5年の在留を認め、特定技能2号は家族帯同と在留期間の更新が可能であり、実質的に永住への道を開いている。

この制度の意義は、従来の技能実習制度が建前としていた「国際貢献」から、「労働力の確保」という目的を明示した点にある。しかしながら、技能実習制度における失踪や人権侵害の問題が完全に解消されたわけではなく、新制度においても労働者の権利保護が十分に機能しているかについては、厳しい目が注がれている。

より本質的な問いは、日本社会が「多民族・多文化社会」への移行を受容する準備ができているかということであろう。法制度の整備だけでなく、地域社会における共生の仕組みづくり、教育現場での多文化教育の推進、そして何より、異なる文化的背景を持つ人々を対等なパートナーとして尊重する社会意識の醸成が不可欠である。',
  'article',
  'N1',
  310,
  '移民政策',
  '[{"word":"施行","reading":"しこう","meaning_ko":"시행"},{"word":"帯同","reading":"たいどう","meaning_ko":"동반"},{"word":"失踪","reading":"しっそう","meaning_ko":"실종"},{"word":"受容","reading":"じゅよう","meaning_ko":"수용"},{"word":"対等","reading":"たいとう","meaning_ko":"대등"}]'::jsonb,
  ARRAY['〜として認識されている', '〜わけではない', '〜が不可欠である'],
  '일본은 오랫동안 공식적으로는 "이민을 받아들이지 않는다"는 입장을 유지해 왔다. 그러나 2019년 개정 입관법 시행에 의한 "특정기능" 체류 자격의 창설은 사실상의 이민 정책의 전환점으로 널리 인식되고 있다.

특정기능 제도는 심각한 인력 부족에 직면한 14개 산업 분야에서 일정한 기능과 일본어 능력을 가진 외국인 인재를 받아들이는 것이다. 특정기능 1호는 최장 5년의 체류를 인정하고 특정기능 2호는 가족 동반과 체류 기간 갱신이 가능하여 실질적으로 영주로의 길을 열고 있다.

이 제도의 의의는 종래의 기능실습 제도가 명분으로 삼았던 "국제 공헌"에서 "노동력 확보"라는 목적을 명시한 점에 있다. 그러나 기능실습 제도에서의 실종이나 인권 침해 문제가 완전히 해소된 것은 아니며 새 제도에서도 노동자의 권리 보호가 충분히 기능하고 있는지에 대해서는 엄격한 시선이 주어지고 있다.

보다 본질적인 물음은 일본 사회가 "다민족·다문화 사회"로의 이행을 수용할 준비가 되어 있느냐는 것일 것이다. 법제도의 정비뿐만 아니라 지역 사회에서의 공생 구조 만들기, 교육 현장에서의 다문화 교육 추진, 그리고 무엇보다 다른 문화적 배경을 가진 사람들을 대등한 파트너로 존중하는 사회 의식의 양성이 불가결하다.',
  52
);

-- N1-17: 意思決定のバイアス (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '意思決定における認知バイアス',
  '行動経済学の発展により、人間の意思決定が必ずしも合理的ではないことが科学的に実証されてきた。ダニエル・カーネマンとエイモス・トベルスキーが提唱したプロスペクト理論は、人間が利益と損失を非対称に評価することを明らかにした。同額の利益よりも損失の方が心理的インパクトが約2倍大きいという「損失回避性」は、ビジネスの場面でも日常生活でも広く観察される。

確証バイアスもまた、意思決定を歪める強力な認知バイアスである。人は自らの既存の信念や仮説を裏付ける情報を選択的に収集・解釈し、矛盾する情報を無意識に軽視する傾向がある。ソフトウェア開発においても、自分のコードにバグがないと信じたいがために、テストが甘くなるという現象は決して珍しくない。

さらに、集団意思決定においては「集団思考」の罠に注意が必要である。チームの和を重視するあまり、異論を唱えることが抑制され、結果として不合理な意思決定がなされる危険性がある。これは日本の組織文化においては特に顕著であり、「空気を読む」文化が健全な批判的思考を妨げることがある。

これらのバイアスを完全に排除することは不可能であるが、その存在を認識し、意思決定プロセスに構造的な対策を組み込むことで、その影響を最小化することは可能である。',
  'essay',
  'N1',
  320,
  '認知バイアス',
  '[{"word":"非対称","reading":"ひたいしょう","meaning_ko":"비대칭"},{"word":"確証","reading":"かくしょう","meaning_ko":"확증"},{"word":"歪める","reading":"ゆがめる","meaning_ko":"왜곡하다"},{"word":"顕著","reading":"けんちょ","meaning_ko":"현저"},{"word":"排除","reading":"はいじょ","meaning_ko":"배제"}]'::jsonb,
  ARRAY['〜により', '〜がために', '〜ことは不可能である'],
  '행동경제학의 발전에 의해 인간의 의사결정이 반드시 합리적이지는 않다는 것이 과학적으로 실증되어 왔다. 다니엘 카너먼과 아모스 트버스키가 제창한 전망 이론은 인간이 이익과 손실을 비대칭적으로 평가한다는 것을 밝혔다. 같은 금액의 이익보다 손실 쪽이 심리적 임팩트가 약 2배 크다는 "손실 회피성"은 비즈니스 장면에서도 일상생활에서도 널리 관찰된다.

확증 편향 또한 의사결정을 왜곡하는 강력한 인지 편향이다. 사람은 자신의 기존 신념이나 가설을 뒷받침하는 정보를 선택적으로 수집·해석하고 모순되는 정보를 무의식적으로 경시하는 경향이 있다. 소프트웨어 개발에서도 자기 코드에 버그가 없다고 믿고 싶어서 테스트가 느슨해지는 현상은 결코 드물지 않다.

나아가 집단 의사결정에서는 "집단 사고"의 함정에 주의가 필요하다. 팀의 화합을 중시한 나머지 이견을 제기하는 것이 억제되어 결과적으로 불합리한 의사결정이 이루어질 위험성이 있다. 이것은 일본의 조직 문화에서 특히 현저하며 "분위기를 읽는" 문화가 건전한 비판적 사고를 방해하는 경우가 있다.

이러한 편향을 완전히 배제하는 것은 불가능하지만 그 존재를 인식하고 의사결정 프로세스에 구조적 대책을 포함시킴으로써 그 영향을 최소화하는 것은 가능하다.',
  53
);

-- N1-18: 持続可能な都市開発 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '持続可能な都市開発モデル',
  '世界の都市人口は2050年までに全人口の68%に達すると予測されており、持続可能な都市開発は人類が直面する最重要課題の一つとなっている。日本においても、東京一極集中の是正と地方都市の活性化は、国土の均衡ある発展にとって不可欠なテーマである。

コンパクトシティ構想は、この課題に対する日本の回答の一つである。富山市はその先進事例として国際的にも注目を集めている。LRT（次世代路面電車）の整備を軸に、公共交通沿線への居住や商業施設の集約を推進し、車に依存しない持続可能な都市構造への転換を図っている。

スマートシティの概念もまた、都市問題の解決に大きな可能性を秘めている。IoTセンサーによるリアルタイムの都市データ収集、AIを活用した交通最適化、再生可能エネルギーの効率的な配分など、テクノロジーを都市運営に統合する取り組みが各地で進められている。

しかし、テクノロジー主導のアプローチだけでは不十分である。持続可能な都市の実現には、市民参加型のガバナンス、コミュニティの再構築、そして「住みたい街」としての魅力の創出が欠かせない。効率性と人間性のバランスをいかに保つかが、都市計画者に課せられた根源的な問いである。',
  'article',
  'N1',
  300,
  '持続可能な都市開発',
  '[{"word":"一極集中","reading":"いっきょくしゅうちゅう","meaning_ko":"일극 집중"},{"word":"是正","reading":"ぜせい","meaning_ko":"시정"},{"word":"集約","reading":"しゅうやく","meaning_ko":"집약"},{"word":"配分","reading":"はいぶん","meaning_ko":"배분"},{"word":"根源的","reading":"こんげんてき","meaning_ko":"근원적"}]'::jsonb,
  ARRAY['〜にとって不可欠', '〜を秘めている', '〜が課せられた'],
  '세계 도시 인구는 2050년까지 전 인구의 68%에 달할 것으로 예측되며 지속 가능한 도시 개발은 인류가 직면하는 최중요 과제 중 하나가 되고 있다. 일본에서도 도쿄 일극 집중의 시정과 지방 도시의 활성화는 국토의 균형 있는 발전에 불가결한 테마이다.

컴팩트 시티 구상은 이 과제에 대한 일본의 답 중 하나이다. 도야마시는 그 선진 사례로 국제적으로도 주목을 모으고 있다. LRT(차세대 노면전차)의 정비를 축으로 대중교통 연선으로의 거주와 상업 시설의 집약을 추진하며 차에 의존하지 않는 지속 가능한 도시 구조로의 전환을 도모하고 있다.

스마트 시티 개념 또한 도시 문제 해결에 큰 가능성을 품고 있다. IoT 센서에 의한 실시간 도시 데이터 수집, AI를 활용한 교통 최적화, 재생 가능 에너지의 효율적 배분 등 테크놀로지를 도시 운영에 통합하는 노력이 각지에서 진행되고 있다.

그러나 테크놀로지 주도의 접근만으로는 불충분하다. 지속 가능한 도시의 실현에는 시민 참가형 거버넌스, 커뮤니티의 재구축, 그리고 "살고 싶은 마을"로서의 매력 창출이 빠질 수 없다. 효율성과 인간성의 밸런스를 어떻게 유지할 것인가가 도시 계획자에게 부과된 근원적 물음이다.',
  54
);

-- N1-19: オープンソースソフトウェアの経済学 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'オープンソースソフトウェアの経済学',
  'オープンソースソフトウェア（OSS）は、そのソースコードが公開され、誰でも自由に使用・修正・再配布できるソフトウェアである。Linux、Apache、PostgreSQL、Reactなど、現代のデジタルインフラストラクチャの根幹を支えるOSSは枚挙にいとまがない。

経済学的観点から見ると、OSSの存在は従来の市場メカニズムでは説明しきれない現象である。なぜ開発者は、直接的な金銭報酬なしに、高品質なソフトウェアを無償で提供するのか。この問いに対しては、複数の説明が提示されている。

第一に、シグナリング仮説がある。OSSへの貢献を通じて技術力を可視化することで、より良い雇用機会を獲得できるという期待が動機となるという考え方である。GitHub上での活動がポートフォリオとして機能している現状は、この仮説を裏付けている。

第二に、ネットワーク外部性の観点がある。OSSの利用者が増えるほど、バグ報告や機能改善への貢献が増加し、ソフトウェアの品質が向上するという正のフィードバックループが形成される。リーナス・トーバルズの「十分な目があれば、全てのバグは浅い」という言葉は、この効果を端的に表現している。

OSSは、競争と協力が共存する独特の経済生態系を形成しており、その持続可能性をいかに担保するかは、デジタル経済全体にとっての重要な課題である。',
  'essay',
  'N1',
  310,
  'オープンソースの経済学',
  '[{"word":"枚挙にいとまがない","reading":"まいきょにいとまがない","meaning_ko":"일일이 열거할 수 없다"},{"word":"報酬","reading":"ほうしゅう","meaning_ko":"보수"},{"word":"裏付ける","reading":"うらづける","meaning_ko":"뒷받침하다"},{"word":"担保","reading":"たんぽ","meaning_ko":"담보, 보장"},{"word":"生態系","reading":"せいたいけい","meaning_ko":"생태계"}]'::jsonb,
  ARRAY['〜しきれない', '〜という考え方', '〜にとっての'],
  '오픈소스 소프트웨어(OSS)는 소스 코드가 공개되어 누구나 자유롭게 사용·수정·재배포할 수 있는 소프트웨어이다. Linux, Apache, PostgreSQL, React 등 현대 디지털 인프라스트럭처의 근간을 지탱하는 OSS는 일일이 열거할 수 없을 정도이다.

경제학적 관점에서 보면 OSS의 존재는 종래의 시장 메커니즘으로는 설명하기 어려운 현상이다. 왜 개발자는 직접적인 금전적 보수 없이 고품질 소프트웨어를 무상으로 제공하는가. 이 물음에 대해서는 복수의 설명이 제시되고 있다.

첫째, 시그널링 가설이 있다. OSS에의 공헌을 통해 기술력을 가시화함으로써 보다 좋은 고용 기회를 획득할 수 있다는 기대가 동기가 된다는 생각이다. GitHub에서의 활동이 포트폴리오로 기능하고 있는 현상은 이 가설을 뒷받침하고 있다.

둘째, 네트워크 외부성의 관점이 있다. OSS의 이용자가 늘수록 버그 보고나 기능 개선에의 공헌이 증가하여 소프트웨어의 품질이 향상된다는 긍정적 피드백 루프가 형성된다. 리누스 토발즈의 "충분한 눈이 있으면 모든 버그는 얕다"라는 말은 이 효과를 단적으로 표현하고 있다.

OSS는 경쟁과 협력이 공존하는 독특한 경제 생태계를 형성하고 있으며 그 지속 가능성을 어떻게 담보할 것인가는 디지털 경제 전체에 있어서의 중요한 과제이다.',
  55
);

-- N1-20: 日本企業の海外展開戦略 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本企業の東南アジア展開戦略',
  '日本企業の東南アジア市場への進出は、1985年のプラザ合意以降の円高を契機に本格化した。当初は製造コストの削減を主な目的とした生産拠点の移転が中心であったが、現在ではASEAN諸国の経済成長に伴う内需拡大を見据えた市場開拓型の進出へとその性格を変えつつある。

ASEAN地域の人口は約6.8億人を擁し、平均年齢は約30歳と若い。中間所得層の急速な拡大により、消費市場としてのポテンシャルは極めて高い。特にベトナム、インドネシア、フィリピンは、今後20年間で最も高い経済成長が見込まれる国々である。

しかし、日本企業の東南アジア展開においては、いくつかの構造的な課題が指摘されている。第一に、現地化の不足である。経営の意思決定が日本本社に集中し、現地のニーズや市場変化への迅速な対応が困難となるケースが少なくない。第二に、現地人材の登用の遅れである。幹部ポストを日本人駐在員が占める構造は、優秀な現地人材の離職を招き、組織の現地化を阻害する要因となっている。

韓国や中国の企業が、より積極的な現地化戦略によってASEAN市場でのシェアを急速に拡大している現状を鑑みると、日本企業もまた、グローバルガバナンスのあり方を根本から見直す時期に来ていると言わざるを得ない。',
  'report',
  'N1',
  310,
  '海外展開戦略',
  '[{"word":"拠点","reading":"きょてん","meaning_ko":"거점"},{"word":"内需","reading":"ないじゅ","meaning_ko":"내수"},{"word":"登用","reading":"とうよう","meaning_ko":"등용"},{"word":"阻害","reading":"そがい","meaning_ko":"저해"},{"word":"鑑みる","reading":"かんがみる","meaning_ko":"감안하다"}]'::jsonb,
  ARRAY['〜を契機に', '〜を見据えた', '〜と言わざるを得ない'],
  '일본 기업의 동남아시아 시장 진출은 1985년 플라자 합의 이후의 엔고를 계기로 본격화했다. 당초에는 제조 비용 삭감을 주 목적으로 한 생산 거점 이전이 중심이었으나 현재는 ASEAN 국가들의 경제 성장에 따른 내수 확대를 내다본 시장 개척형 진출로 그 성격을 바꾸고 있다.

ASEAN 지역의 인구는 약 6.8억 명을 보유하며 평균 연령은 약 30세로 젊다. 중간 소득층의 급속한 확대에 의해 소비 시장으로서의 잠재력은 극히 높다. 특히 베트남, 인도네시아, 필리핀은 향후 20년간 가장 높은 경제 성장이 예상되는 나라들이다.

그러나 일본 기업의 동남아 전개에서는 몇 가지 구조적 과제가 지적되고 있다. 첫째, 현지화의 부족이다. 경영 의사결정이 일본 본사에 집중되어 현지 니즈나 시장 변화에의 신속한 대응이 곤란해지는 케이스가 적지 않다. 둘째, 현지 인재 등용의 지연이다. 간부 포스트를 일본인 주재원이 차지하는 구조는 우수한 현지 인재의 이직을 초래하고 조직의 현지화를 저해하는 요인이 되고 있다.

한국이나 중국 기업이 보다 적극적인 현지화 전략으로 ASEAN 시장에서의 점유율을 급속히 확대하고 있는 현상을 감안하면 일본 기업 또한 글로벌 거버넌스의 방식을 근본부터 재검토할 시기에 와 있다고 말하지 않을 수 없다.',
  56
);

-- N1-21: 倫理的AIの設計原則 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '倫理的AIの設計原則',
  '人工知能の社会実装が加速する中、AIシステムの倫理的設計は喫緊の課題となっている。欧州委員会が2019年に公表した「信頼できるAIのための倫理ガイドライン」は、7つの要件を提示しているが、これを技術的に実現することは容易ではない。

公平性（フェアネス）の確保は、最も議論が活発な領域の一つである。AIモデルが学習するデータに社会的偏見が含まれている場合、その偏見がモデルの出力に再生産される。採用選考AIが女性候補者を不利に評価した事例や、顔認識AIの精度が人種によって著しく異なる問題は、この課題の深刻さを示している。

透明性と説明可能性もまた、重要な原則である。深層学習モデルは高い精度を達成する一方で、その意思決定プロセスはブラックボックスとなりがちである。医療診断や信用審査など、個人の生活に重大な影響を及ぼす領域では、なぜその判断に至ったかを説明できることが不可欠である。

プライバシーの保護と社会的有用性のバランスも繊細な問題である。パンデミック時の接触追跡アプリは、公衆衛生上の利益と個人のプライバシーの対立を鮮明にした。

最終的に、倫理的AIの実現は技術者だけの責任ではない。法学者、倫理学者、社会学者、そして市民社会を含む多様なステークホルダーによる継続的な対話と合意形成こそが、人間中心のAI社会を実現する鍵となるのである。',
  'essay',
  'N1',
  330,
  '倫理的AI',
  '[{"word":"喫緊","reading":"きっきん","meaning_ko":"긴급, 시급"},{"word":"偏見","reading":"へんけん","meaning_ko":"편견"},{"word":"再生産","reading":"さいせいさん","meaning_ko":"재생산"},{"word":"繊細","reading":"せんさい","meaning_ko":"섬세"},{"word":"合意形成","reading":"ごういけいせい","meaning_ko":"합의 형성"}]'::jsonb,
  ARRAY['〜となっている', '〜こそが', '〜のである'],
  '인공지능의 사회 실장이 가속되는 가운데 AI 시스템의 윤리적 설계는 시급한 과제가 되고 있다. 유럽위원회가 2019년에 공표한 "신뢰할 수 있는 AI를 위한 윤리 가이드라인"은 7개 요건을 제시하고 있으나 이를 기술적으로 실현하는 것은 쉽지 않다.

공정성(페어니스)의 확보는 가장 논의가 활발한 영역 중 하나이다. AI 모델이 학습하는 데이터에 사회적 편견이 포함되어 있는 경우 그 편견이 모델의 출력에 재생산된다. 채용 선고 AI가 여성 후보자를 불리하게 평가한 사례나 얼굴 인식 AI의 정확도가 인종에 따라 현저히 다른 문제는 이 과제의 심각성을 보여주고 있다.

투명성과 설명 가능성도 또한 중요한 원칙이다. 심층학습 모델은 높은 정확도를 달성하는 한편 그 의사결정 프로세스는 블랙박스가 되기 쉽다. 의료 진단이나 신용 심사 등 개인의 생활에 중대한 영향을 미치는 영역에서는 왜 그 판단에 이르렀는지를 설명할 수 있는 것이 불가결하다.

프라이버시 보호와 사회적 유용성의 밸런스도 섬세한 문제이다. 팬데믹 시의 접촉 추적 앱은 공중 보건상의 이익과 개인의 프라이버시의 대립을 선명하게 했다.

최종적으로 윤리적 AI의 실현은 기술자만의 책임이 아니다. 법학자, 윤리학자, 사회학자, 그리고 시민 사회를 포함한 다양한 이해관계자에 의한 지속적인 대화와 합의 형성이야말로 인간 중심의 AI 사회를 실현하는 열쇠가 되는 것이다.',
  57
);

-- N1-22: 日本庭園の美学 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本庭園に見る美学',
  '日本庭園は、自然の風景を抽象化し、限られた空間の中に宇宙を表現しようとする芸術形式である。その根底には、禅の思想から派生した「侘び寂び」の美学が流れている。

枯山水は、その極致と言えよう。水を一切用いず、白砂と石のみで水の流れや海の広がりを表現する。京都龍安寺の石庭は、15個の石が配置されているが、どの角度から見ても同時に15個すべてを見ることはできないと言われている。この「不完全さ」こそが、観る者の想像力を喚起し、完全なるものへの到達不可能性という禅の核心を体現しているのである。

借景という技法も、日本庭園の特筆すべき特徴である。庭園の外部にある山や森を、あたかも庭の一部であるかのように取り込む手法は、庭園と自然の境界を曖昧にし、人為と自然の調和を志向する日本の美意識を如実に物語っている。

現代の都市空間においても、日本庭園の原理は生き続けている。ミニマリズムを基調とした日本のインテリアデザインや、「間」を重視する建築設計には、庭園美学のDNAが色濃く反映されている。

日本庭園が世界中で高く評価される理由は、それが単なる装飾芸術ではなく、自然と人間の関係性についての深い哲学的省察を内包しているからに他ならない。',
  'essay',
  'N1',
  300,
  '日本庭園の美学',
  '[{"word":"抽象化","reading":"ちゅうしょうか","meaning_ko":"추상화"},{"word":"派生","reading":"はせい","meaning_ko":"파생"},{"word":"極致","reading":"きょくち","meaning_ko":"극치"},{"word":"喚起","reading":"かんき","meaning_ko":"환기"},{"word":"省察","reading":"せいさつ","meaning_ko":"성찰"}]'::jsonb,
  ARRAY['〜と言えよう', '〜こそが', '〜からに他ならない'],
  '일본 정원은 자연의 풍경을 추상화하여 한정된 공간 안에 우주를 표현하려는 예술 형식이다. 그 근저에는 선(禅)의 사상에서 파생된 "와비사비"의 미학이 흐르고 있다.

가레산스이(마른 정원)는 그 극치라고 할 수 있을 것이다. 물을 일절 사용하지 않고 흰 모래와 돌만으로 물의 흐름이나 바다의 넓음을 표현한다. 교토 료안지의 석정은 15개의 돌이 배치되어 있으나 어떤 각도에서 보아도 동시에 15개 모두를 볼 수는 없다고 한다. 이 "불완전함"이야말로 보는 이의 상상력을 환기하고 완전한 것에의 도달 불가능성이라는 선의 핵심을 체현하고 있는 것이다.

차경이라는 기법도 일본 정원의 특필할 만한 특징이다. 정원 외부에 있는 산이나 숲을 마치 정원의 일부인 것처럼 받아들이는 수법은 정원과 자연의 경계를 모호하게 하고 인위와 자연의 조화를 지향하는 일본의 미의식을 여실히 말해주고 있다.

현대의 도시 공간에서도 일본 정원의 원리는 살아 있다. 미니멀리즘을 기조로 한 일본의 인테리어 디자인이나 "마(간)"를 중시하는 건축 설계에는 정원 미학의 DNA가 짙게 반영되어 있다.

일본 정원이 세계에서 높이 평가받는 이유는 그것이 단순한 장식 예술이 아니라 자연과 인간의 관계성에 대한 깊은 철학적 성찰을 내포하고 있기 때문에 다름 아니다.',
  58
);

-- N1-23: 日本の知的財産戦略 (report)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本の知的財産戦略の課題',
  '知的財産戦略は、イノベーション主導型経済への転換を図る上で、国家戦略の中枢に位置づけられるべきものである。日本は特許出願件数において世界第3位を維持しているものの、その活用率や経済的価値の創出において、米国や中国との差が拡大しつつある。

特許の質と活用に着目すると、日本企業の特許の多くが「防衛型」に偏っている実態が浮かび上がる。すなわち、自社技術を模倣から守るための特許取得が中心であり、ライセンス収入や事業戦略と連動した「攻めの知財戦略」が不足しているのである。

標準必須特許（SEP）の獲得においても、日本は立ち遅れが顕著である。5Gや次世代通信規格における標準必須特許の保有件数は、中国のHuaweiやQualcommに大きく水をあけられている。国際標準の策定プロセスに積極的に関与し、自国技術を標準規格に組み込んでいく戦略的取り組みが求められる。

知的財産教育の充実も急務である。理工系の研究者や技術者のみならず、経営者やビジネスパーソンが知的財産の価値を正しく理解し、経営戦略の不可分の要素として位置づける素養を身につけることが必要であろう。',
  'report',
  'N1',
  280,
  '知的財産戦略',
  '[{"word":"中枢","reading":"ちゅうすう","meaning_ko":"중추"},{"word":"偏る","reading":"かたよる","meaning_ko":"치우치다"},{"word":"模倣","reading":"もほう","meaning_ko":"모방"},{"word":"顕著","reading":"けんちょ","meaning_ko":"현저"},{"word":"素養","reading":"そよう","meaning_ko":"소양"}]'::jsonb,
  ARRAY['〜べきものである', '〜つつある', '〜であろう'],
  '지적 재산 전략은 이노베이션 주도형 경제로의 전환을 도모하는 데 있어 국가 전략의 중추에 자리매김되어야 할 것이다. 일본은 특허 출원 건수에서 세계 제3위를 유지하고 있으나 그 활용률이나 경제적 가치 창출에서 미국이나 중국과의 차이가 확대되고 있다.

특허의 질과 활용에 주목하면 일본 기업의 특허 대부분이 "방어형"에 치우쳐 있는 실태가 떠오른다. 즉 자사 기술을 모방으로부터 지키기 위한 특허 취득이 중심이며 라이선스 수입이나 사업 전략과 연동한 "공격의 지재 전략"이 부족한 것이다.

표준 필수 특허(SEP) 획득에서도 일본은 뒤처짐이 현저하다. 5G나 차세대 통신 규격에서의 표준 필수 특허 보유 건수는 중국의 Huawei나 Qualcomm에 크게 뒤지고 있다. 국제 표준의 책정 프로세스에 적극적으로 관여하고 자국 기술을 표준 규격에 포함시켜 나가는 전략적 노력이 요구된다.

지적 재산 교육의 충실도 급선무이다. 이공계 연구자나 기술자뿐만 아니라 경영자나 비즈니스 퍼슨이 지적 재산의 가치를 올바르게 이해하고 경영 전략의 불가분의 요소로 자리매김하는 소양을 갖추는 것이 필요할 것이다.',
  59
);

-- N1-24: 異文化マネジメント論 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '異文化マネジメントの理論と実践',
  'グローバル化が進展する現代のビジネス環境において、異文化マネジメントは経営学における中核的なテーマとなっている。ヘールト・ホフステードの文化次元理論は、国民文化の差異を定量的に分析する枠組みを提供し、異文化間のマネジメントに多大な示唆を与えてきた。

ホフステードの分析において、日本は「不確実性の回避」が極めて高い国として位置づけられている。これは、日本企業が緻密な計画立案やリスク管理を重視し、標準化された手順を好む傾向と合致する。一方で、この特性は変化の激しい環境における意思決定の遅延をもたらすこともある。

権力距離の次元も重要な分析軸である。韓国や中国と比較すると、日本は中程度の権力距離に位置するが、年功序列制度や敬語体系に見られるように、組織内の序列は依然として重要な意味を持つ。外国人社員が日本企業で戸惑うのは、この暗黙的な序列構造と、それに基づく情報共有の非対称性である。

エリン・メイヤーの「カルチャーマップ」は、より実践的な枠組みを提供している。コミュニケーションの直接性、フィードバックの方法、意思決定プロセス、信頼構築の基盤など、8つの軸で文化差を整理することで、具体的な行動指針を導出できる。異文化チームのマネジメントにおいては、文化差を「問題」ではなく「資源」として捉え、多様な視点を統合する能力こそが求められるのである。',
  'article',
  'N1',
  330,
  '異文化マネジメント',
  '[{"word":"中核的","reading":"ちゅうかくてき","meaning_ko":"핵심적"},{"word":"示唆","reading":"しさ","meaning_ko":"시사"},{"word":"緻密","reading":"ちみつ","meaning_ko":"치밀"},{"word":"合致","reading":"がっち","meaning_ko":"합치"},{"word":"導出","reading":"どうしゅつ","meaning_ko":"도출"}]'::jsonb,
  ARRAY['〜において', '〜こそが求められる', '〜として捉える'],
  '글로벌화가 진전하는 현대 비즈니스 환경에서 이문화 매니지먼트는 경영학에서의 핵심적 테마가 되고 있다. 헤르트 호프스테더의 문화 차원 이론은 국민 문화의 차이를 정량적으로 분석하는 틀을 제공하여 이문화간 매니지먼트에 큰 시사를 주어 왔다.

호프스테더의 분석에서 일본은 "불확실성의 회피"가 극히 높은 나라로 자리매김되어 있다. 이것은 일본 기업이 치밀한 계획 수립이나 리스크 관리를 중시하고 표준화된 절차를 선호하는 경향과 합치한다. 한편 이 특성은 변화가 격한 환경에서의 의사결정 지연을 초래하기도 한다.

권력 거리의 차원도 중요한 분석축이다. 한국이나 중국과 비교하면 일본은 중간 정도의 권력 거리에 위치하지만 연공서열 제도나 경어 체계에서 볼 수 있듯이 조직 내 서열은 여전히 중요한 의미를 지닌다. 외국인 사원이 일본 기업에서 당혹하는 것은 이 암묵적 서열 구조와 그에 기반한 정보 공유의 비대칭성이다.

에린 메이어의 "컬처 맵"은 보다 실천적인 틀을 제공하고 있다. 커뮤니케이션의 직접성, 피드백 방법, 의사결정 프로세스, 신뢰 구축의 기반 등 8개 축으로 문화차를 정리함으로써 구체적 행동 지침을 도출할 수 있다. 이문화 팀 매니지먼트에서는 문화차를 "문제"가 아니라 "자원"으로 파악하고 다양한 시점을 통합하는 능력이야말로 요구되는 것이다.',
  60
);

-- N1-25: 日本の介護問題と技術革新 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '介護問題と技術革新の可能性',
  '超高齢社会を迎えた日本において、介護の問題は社会全体を揺るがす危機的状況にある。2025年には、いわゆる「団塊の世代」全員が75歳以上の後期高齢者となり、介護需要は爆発的に増大する。一方で、介護人材は2025年に約32万人、2040年には約69万人が不足すると推計されている。

この需給ギャップを埋める手段として、介護ロボットやICTの活用が注目されている。移乗支援ロボットは、要介護者をベッドから車椅子へ移動させる際の身体的負担を大幅に軽減する。見守りセンサーは、夜間の転倒や徘徊を検知し、少ない人員でも安全な介護を可能にする。

AIを活用したケアプラン作成支援も実用化が進んでいる。過去のケアデータを分析し、利用者一人ひとりに最適化されたケアプランを提案するシステムは、ケアマネジャーの業務負担の軽減と、ケアの質の向上の両方に貢献している。

しかし、技術の導入に対する現場の抵抗感は根強い。「介護は人の温もりが大切」という信念は、決して否定されるべきものではない。重要なのは、テクノロジーが人間に代わるのではなく、人間がより質の高い介護を提供するための支援ツールとして位置づけることである。機械にできることは機械に任せ、人間にしかできない傾聴や共感に、より多くの時間を割くことこそが、テクノロジーと介護の理想的な共存の姿であろう。',
  'article',
  'N1',
  320,
  '介護と技術',
  '[{"word":"需給","reading":"じゅきゅう","meaning_ko":"수급"},{"word":"移乗","reading":"いじょう","meaning_ko":"이승, 옮기기"},{"word":"徘徊","reading":"はいかい","meaning_ko":"배회"},{"word":"傾聴","reading":"けいちょう","meaning_ko":"경청"},{"word":"共存","reading":"きょうぞん","meaning_ko":"공존"}]'::jsonb,
  ARRAY['〜に代わる', '〜こそが', '〜であろう'],
  '초고령 사회를 맞이한 일본에서 개호(돌봄) 문제는 사회 전체를 뒤흔드는 위기적 상황에 있다. 2025년에는 이른바 "단카이 세대" 전원이 75세 이상의 후기 고령자가 되어 개호 수요는 폭발적으로 증대한다. 한편 개호 인재는 2025년에 약 32만 명, 2040년에는 약 69만 명이 부족할 것으로 추계되고 있다.

이 수급 갭을 메우는 수단으로 개호 로봇이나 ICT의 활용이 주목받고 있다. 이승 지원 로봇은 요개호자를 침대에서 휠체어로 옮길 때의 신체적 부담을 대폭 경감한다. 감시 센서는 야간의 전도나 배회를 감지하여 적은 인원으로도 안전한 개호를 가능하게 한다.

AI를 활용한 케어플랜 작성 지원도 실용화가 진행되고 있다. 과거의 케어 데이터를 분석하고 이용자 한 명 한 명에 최적화된 케어플랜을 제안하는 시스템은 케어매니저의 업무 부담 경감과 케어의 질 향상 양쪽에 공헌하고 있다.

그러나 기술 도입에 대한 현장의 저항감은 뿌리 깊다. "개호는 사람의 온기가 중요하다"는 신념은 결코 부정되어야 할 것이 아니다. 중요한 것은 테크놀로지가 인간을 대신하는 것이 아니라 인간이 보다 질 높은 개호를 제공하기 위한 지원 도구로 자리매김하는 것이다. 기계가 할 수 있는 것은 기계에 맡기고 인간만이 할 수 있는 경청이나 공감에 보다 많은 시간을 할애하는 것이야말로 테크놀로지와 개호의 이상적 공존의 모습일 것이다.',
  61
);

-- N1-26: デジタル通貨と金融の未来 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  'デジタル通貨と金融の未来',
  '中央銀行デジタル通貨（CBDC）の研究開発が世界各国で加速している。中国のデジタル人民元は既にパイロット段階を経て実用化に向かっており、欧州中央銀行もデジタルユーロの準備段階に入っている。日本銀行もまた、2023年からパイロット実験を開始し、技術的な検証を進めている。

CBDCが既存の金融システムに与える影響は多岐にわたる。決済の即時性と低コスト化は、特に国際送金において革命的な変化をもたらす可能性がある。現行の国際送金システムでは数日を要し、高額な手数料が課されるが、CBDCを活用した送金では、これらの非効率性が大幅に解消されうる。

一方で、CBDCの導入は商業銀行のビジネスモデルを根底から覆す可能性も孕んでいる。個人が中央銀行に直接口座を持てるようになれば、商業銀行の預金仲介機能は縮小を余儀なくされる。金融システムの安定性を維持しつつ、イノベーションを促進するという相反する要請をいかに両立させるかが、政策立案者に課せられた難題である。

プライバシーの問題も避けて通れない。CBDCは原理的に全ての取引を追跡可能にするため、政府による金融監視の強化につながりかねない。匿名性の確保と不正取引の防止のバランスは、制度設計における最も繊細な論点の一つである。',
  'article',
  'N1',
  310,
  'デジタル通貨',
  '[{"word":"覆す","reading":"くつがえす","meaning_ko":"뒤집다"},{"word":"孕む","reading":"はらむ","meaning_ko":"품다, 내포하다"},{"word":"余儀なくされる","reading":"よぎなくされる","meaning_ko":"어쩔 수 없이 되다"},{"word":"相反する","reading":"あいはんする","meaning_ko":"상반되다"},{"word":"繊細","reading":"せんさい","meaning_ko":"섬세"}]'::jsonb,
  ARRAY['〜にわたる', '〜かねない', '〜の一つである'],
  '중앙은행 디지털 통화(CBDC)의 연구 개발이 세계 각국에서 가속화되고 있다. 중국의 디지털 위안화는 이미 파일럿 단계를 거쳐 실용화를 향하고 있으며 유럽 중앙은행도 디지털 유로의 준비 단계에 들어갔다. 일본은행 또한 2023년부터 파일럿 실험을 개시하여 기술적 검증을 진행하고 있다.

CBDC가 기존 금융 시스템에 미치는 영향은 다방면에 걸친다. 결제의 즉시성과 저비용화는 특히 국제 송금에서 혁명적 변화를 가져올 가능성이 있다. 현행 국제 송금 시스템에서는 수일이 소요되고 고액의 수수료가 부과되지만 CBDC를 활용한 송금에서는 이러한 비효율성이 대폭 해소될 수 있다.

한편 CBDC의 도입은 상업은행의 비즈니스 모델을 근저부터 뒤집을 가능성도 내포하고 있다. 개인이 중앙은행에 직접 계좌를 가질 수 있게 되면 상업은행의 예금 중개 기능은 축소를 피할 수 없게 된다. 금융 시스템의 안정성을 유지하면서 이노베이션을 촉진한다는 상반되는 요청을 어떻게 양립시킬 것인가가 정책 입안자에게 부과된 난제이다.

프라이버시 문제도 피해 갈 수 없다. CBDC는 원리적으로 모든 거래를 추적 가능하게 하므로 정부에 의한 금융 감시 강화로 이어질 우려가 있다. 익명성 확보와 부정 거래 방지의 밸런스는 제도 설계에서 가장 섬세한 논점 중 하나이다.',
  62
);

-- N1-27: 日本の食品ロス問題 (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '食品ロス削減への挑戦',
  '日本における食品ロスは年間約472万トンに上り、これは国民一人当たりに換算すると、毎日おにぎり約1個分の食品を廃棄していることに相当する。世界では約8億人が飢餓に苦しんでいる中、この数字は先進国としての倫理的責任を問われるものである。

食品ロスの発生源は、事業系と家庭系に大別される。事業系では、製造過程での規格外品の廃棄、小売店での売れ残り、飲食店での食べ残しが主な原因である。特に日本独自の商慣行である「3分の1ルール」は、賞味期限の3分の1が経過した時点で小売店への納品が拒否されるという厳格な基準であり、まだ十分に食べられる食品の廃棄を招いている。

家庭系食品ロスは全体の約47%を占める。過剰な買い物、使い切れない食材の廃棄、食べ残しが主な要因である。核家族化と単身世帯の増加に伴い、大容量パックの食材を使い切れないケースが増加している。

フードバンクやフードシェアリングアプリなどの取り組みは拡大しているものの、欧州諸国と比較するとまだ発展途上にある。フランスでは2016年に大型スーパーマーケットにおける食品廃棄を法律で禁止しており、日本においても同様の規制的アプローチの導入が検討されてしかるべきであろう。',
  'article',
  'N1',
  290,
  '食品ロス',
  '[{"word":"換算","reading":"かんさん","meaning_ko":"환산"},{"word":"廃棄","reading":"はいき","meaning_ko":"폐기"},{"word":"飢餓","reading":"きが","meaning_ko":"기아"},{"word":"商慣行","reading":"しょうかんこう","meaning_ko":"상관행"},{"word":"しかるべき","reading":"しかるべき","meaning_ko":"마땅한"}]'::jsonb,
  ARRAY['〜に上り', '〜に相当する', '〜てしかるべき'],
  '일본의 식품 로스는 연간 약 472만 톤에 이르며 이것은 국민 1인당으로 환산하면 매일 주먹밥 약 1개분의 식품을 폐기하고 있는 것에 해당한다. 세계에서는 약 8억 명이 기아에 시달리고 있는 가운데 이 수치는 선진국으로서의 윤리적 책임을 묻는 것이다.

식품 로스의 발생원은 사업계와 가정계로 대별된다. 사업계에서는 제조 과정에서의 규격외품 폐기, 소매점에서의 팔다 남은 것, 음식점에서의 먹다 남은 것이 주요 원인이다. 특히 일본 고유의 상관행인 "3분의 1 룰"은 유통 기한의 3분의 1이 경과한 시점에서 소매점에의 납품이 거부된다는 엄격한 기준이며 아직 충분히 먹을 수 있는 식품의 폐기를 초래하고 있다.

가정계 식품 로스는 전체의 약 47%를 차지한다. 과잉 구매, 다 쓰지 못하는 식재료의 폐기, 먹다 남은 것이 주요 요인이다. 핵가족화와 단신 세대의 증가에 따라 대용량 팩의 식재료를 다 쓰지 못하는 케이스가 증가하고 있다.

푸드 뱅크나 푸드 셰어링 앱 등의 노력은 확대되고 있으나 유럽 국가와 비교하면 아직 발전 도상에 있다. 프랑스에서는 2016년에 대형 슈퍼마켓에서의 식품 폐기를 법률로 금지했으며 일본에서도 유사한 규제적 접근의 도입이 검토되어야 마땅할 것이다.',
  63
);

-- N1-28: 分散システムの一貫性モデル (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '分散システムにおける一貫性モデル',
  '分散システムの設計において、CAP定理は避けて通れない理論的制約である。エリック・ブリューワーが2000年に提唱したこの定理は、分散システムにおいて一貫性（Consistency）、可用性（Availability）、分断耐性（Partition tolerance）の3つを同時に完全に満たすことは不可能であるとしている。

ネットワーク分断は現実の分散システムでは不可避であるため、実質的にはCPシステム（一貫性と分断耐性を重視）とAPシステム（可用性と分断耐性を重視）の二者択一となる。銀行の口座残高管理のような厳密な一貫性が求められるシステムではCPが、SNSのタイムラインのように若干の遅延が許容されるシステムではAPが選択される。

しかし、この二項対立的な理解は過度に単純化されているとの批判もある。実際のシステム設計においては、結果整合性（Eventual Consistency）という概念が広く採用されている。これは、一時的な不整合を許容しつつも、最終的にはすべてのノードが同一の状態に収束することを保証するモデルである。AmazonのDynamoDBはこのアプローチの代表的な実装例である。

さらに近年では、CRDTのような、競合を構造的に解消するデータ構造の研究も進んでいる。分散システムの設計は、理論的制約を理解した上で、ビジネス要件に応じた最適なトレードオフを見極める高度な判断が求められる領域である。',
  'article',
  'N1',
  310,
  '分散システム',
  '[{"word":"制約","reading":"せいやく","meaning_ko":"제약"},{"word":"不可避","reading":"ふかひ","meaning_ko":"불가피"},{"word":"二者択一","reading":"にしゃたくいつ","meaning_ko":"양자택일"},{"word":"収束","reading":"しゅうそく","meaning_ko":"수렴"},{"word":"競合","reading":"きょうごう","meaning_ko":"경합"}]'::jsonb,
  ARRAY['〜とされている', '〜との批判もある', '〜が求められる'],
  '분산 시스템의 설계에서 CAP 정리는 피해갈 수 없는 이론적 제약이다. 에릭 브루어가 2000년에 제창한 이 정리는 분산 시스템에서 일관성(Consistency), 가용성(Availability), 분단 내성(Partition tolerance)의 3가지를 동시에 완전히 충족하는 것은 불가능하다고 하고 있다.

네트워크 분단은 현실의 분산 시스템에서는 불가피하므로 실질적으로는 CP 시스템(일관성과 분단 내성 중시)과 AP 시스템(가용성과 분단 내성 중시)의 양자택일이 된다. 은행의 계좌 잔고 관리와 같은 엄밀한 일관성이 요구되는 시스템에서는 CP가, SNS의 타임라인처럼 약간의 지연이 허용되는 시스템에서는 AP가 선택된다.

그러나 이 이항 대립적 이해는 과도하게 단순화되어 있다는 비판도 있다. 실제 시스템 설계에서는 결과적 일관성(Eventual Consistency)이라는 개념이 널리 채용되고 있다. 이것은 일시적 불일치를 허용하면서도 최종적으로는 모든 노드가 동일한 상태에 수렴하는 것을 보증하는 모델이다. Amazon의 DynamoDB는 이 접근법의 대표적 구현 예이다.

나아가 최근에는 CRDT와 같은 경합을 구조적으로 해소하는 데이터 구조의 연구도 진행되고 있다. 분산 시스템의 설계는 이론적 제약을 이해한 위에서 비즈니스 요건에 따른 최적의 트레이드오프를 간파하는 고도의 판단이 요구되는 영역이다.',
  64
);

-- N1-29: 教育格差と社会的再生産 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '教育格差と社会的再生産のメカニズム',
  '教育は社会的公正の実現にとって最も重要な手段であると同時に、既存の社会的不平等を再生産する装置としても機能し得る。ピエール・ブルデューの文化資本論は、この矛盾を鋭く分析した。

ブルデューによれば、教育システムは表面的には能力主義に基づく公平な競争の場を提供しているように見えるが、実際には上位階層の文化資本を正統な知識として承認し、再生産する機能を果たしている。読書習慣、芸術的素養、言語運用能力など、家庭環境を通じて獲得される文化的資源は、学校教育における成功に大きく影響する。

日本においても、家庭の経済状況と子どもの学力の相関は明確である。全国学力テストの結果は、保護者の年収や学歴と有意な相関を示しており、「生まれた家庭」が教育達成を規定する構造が存在する。進学塾や私立学校への投資は、家庭の経済力に依存しており、教育の機会均等という理念は形骸化しつつあると言わざるを得ない。

この問題に対する処方箋は多岐にわたるが、根本的には、公教育の質的向上こそが最も重要であろう。経済的背景に関わらず質の高い教育を受けられる社会を構築することは、効率性の観点からも正当化される。人材の潜在能力を社会全体として最大化することは、経済成長と社会的安定の双方にとって不可欠だからである。',
  'essay',
  'N1',
  300,
  '教育格差',
  '[{"word":"再生産","reading":"さいせいさん","meaning_ko":"재생산"},{"word":"承認","reading":"しょうにん","meaning_ko":"승인"},{"word":"素養","reading":"そよう","meaning_ko":"소양"},{"word":"形骸化","reading":"けいがいか","meaning_ko":"형해화"},{"word":"処方箋","reading":"しょほうせん","meaning_ko":"처방전"}]'::jsonb,
  ARRAY['〜と同時に', '〜によれば', '〜と言わざるを得ない'],
  '교육은 사회적 공정의 실현에 있어 가장 중요한 수단인 동시에 기존의 사회적 불평등을 재생산하는 장치로서도 기능할 수 있다. 피에르 부르디외의 문화자본론은 이 모순을 날카롭게 분석했다.

부르디외에 따르면 교육 시스템은 표면적으로는 능력주의에 기반한 공정한 경쟁의 장을 제공하는 것처럼 보이지만 실제로는 상위 계층의 문화자본을 정통한 지식으로 승인하고 재생산하는 기능을 하고 있다. 독서 습관, 예술적 소양, 언어 운용 능력 등 가정환경을 통해 획득되는 문화적 자원은 학교 교육에서의 성공에 크게 영향을 미친다.

일본에서도 가정의 경제 상황과 자녀의 학력의 상관은 명확하다. 전국 학력 테스트의 결과는 보호자의 연수입이나 학력과 유의미한 상관을 보이고 있으며 "태어난 가정"이 교육 달성을 규정하는 구조가 존재한다. 학원이나 사립학교에의 투자는 가정의 경제력에 의존하고 있으며 교육의 기회 균등이라는 이념은 형해화되고 있다고 말하지 않을 수 없다.

이 문제에 대한 처방전은 다방면에 걸치지만 근본적으로는 공교육의 질적 향상이야말로 가장 중요할 것이다. 경제적 배경에 관계없이 질 높은 교육을 받을 수 있는 사회를 구축하는 것은 효율성의 관점에서도 정당화된다. 인재의 잠재 능력을 사회 전체로서 최대화하는 것은 경제 성장과 사회적 안정 양쪽에 불가결하기 때문이다.',
  65
);

-- N1-30: 日本語教育の未来像 (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, topic, vocabulary_notes, grammar_notes, translation_ko, sort_order)
VALUES (
  '日本語教育の未来像',
  '日本語教育は今、大きな転換点に立っている。日本国内の外国人居住者は約340万人に達し、技能実習生や特定技能労働者の増加に伴い、「生活者としての外国人」への日本語教育の需要は急速に拡大している。一方で、海外における日本語学習者は約380万人を数え、アニメやゲームなどのポップカルチャーを入り口とした学習動機の多様化が進んでいる。

従来の日本語教育は、文法訳読法を基盤とし、日本語能力試験（JLPT）の合格を主な目標として設計されてきた。しかし、コミュニカティブ・アプローチやタスクベースの教授法が主流となる中で、「できる日本語」、すなわちタスク遂行能力としての日本語力が重視されるようになっている。

AIと自然言語処理技術の進展は、日本語教育のあり方を根本から変えうる。AI翻訳の精度が向上し続ける中、「なぜ外国語を学ぶ必要があるのか」という根源的な問いが投げかけられている。しかし、言語学習の価値は単なる情報伝達の効率性に還元されるものではない。異なる言語で思考することは、世界の見方を複数化し、認知的柔軟性を高める。言語は文化への扉であり、他者理解の基盤である。

日本語教育の未来は、テクノロジーと人間の教師の協働にあるだろう。AIが文法チェックや発音矯正を担い、人間の教師が文化的文脈の理解や動機づけ、学習者一人ひとりの個別ニーズへの対応を担う。この役割分担こそが、より効果的で人間的な日本語教育を実現する鍵となるのではないだろうか。',
  'essay',
  'N1',
  340,
  '日本語教育の未来',
  '[{"word":"転換点","reading":"てんかんてん","meaning_ko":"전환점"},{"word":"遂行","reading":"すいこう","meaning_ko":"수행"},{"word":"還元","reading":"かんげん","meaning_ko":"환원"},{"word":"矯正","reading":"きょうせい","meaning_ko":"교정"},{"word":"協働","reading":"きょうどう","meaning_ko":"협동"}]'::jsonb,
  ARRAY['〜に立っている', '〜ものではない', '〜のではないだろうか'],
  '일본어 교육은 지금 큰 전환점에 서 있다. 일본 국내의 외국인 거주자는 약 340만 명에 달하며 기능실습생이나 특정기능 노동자의 증가에 따라 "생활자로서의 외국인"에 대한 일본어 교육 수요는 급속히 확대되고 있다. 한편 해외에서의 일본어 학습자는 약 380만 명을 세며 애니메이션이나 게임 등 팝 컬처를 입구로 한 학습 동기의 다양화가 진행되고 있다.

종래의 일본어 교육은 문법 번역법을 기반으로 하여 일본어능력시험(JLPT) 합격을 주요 목표로 설계되어 왔다. 그러나 커뮤니커티브 어프로치나 태스크 기반 교수법이 주류가 되는 가운데 "할 수 있는 일본어", 즉 태스크 수행 능력으로서의 일본어 능력이 중시되게 되었다.

AI와 자연어 처리 기술의 진전은 일본어 교육의 방식을 근본부터 바꿀 수 있다. AI 번역의 정확도가 향상을 계속하는 가운데 "왜 외국어를 배울 필요가 있는가"라는 근원적 물음이 던져지고 있다. 그러나 언어 학습의 가치는 단순한 정보 전달의 효율성으로 환원되는 것이 아니다. 다른 언어로 사고하는 것은 세계를 보는 방식을 복수화하고 인지적 유연성을 높인다. 언어는 문화로의 문이며 타자 이해의 기반이다.

일본어 교육의 미래는 테크놀로지와 인간 교사의 협동에 있을 것이다. AI가 문법 체크나 발음 교정을 담당하고 인간 교사가 문화적 맥락의 이해나 동기 부여, 학습자 한 명 한 명의 개별 니즈에의 대응을 담당한다. 이 역할 분담이야말로 보다 효과적이고 인간적인 일본어 교육을 실현하는 열쇠가 되는 것이 아닐까.',
  66
);
